window.CBT_DATA=window.CBT_DATA||{};window.CBT_DATA["written/2026-1"]={"track":"written","round":"2026-1","questions":[{"id":"written-2026-1-1","no":1,"unit":"소프트웨어 설계","q":"입력되는 데이터를 컴퓨터의 프로세서가 처리하기 전에 미리 처리함으로써 프로세서의 처리 시간을 줄여주는 프로그램 또는 하드웨어를 무엇이라 하는가?","choices":["Duplexing","FEP","EAI","GPL"],"ans":2,"exp":{"concept":"전처리기(FEP, Front-End Processor)는 입력 데이터를 메인 프로세서(호스트 컴퓨터)가 처리하기 전에 미리 정리·변환·검사해 두는 프로그램이나 하드웨어입니다. 덕분에 메인 프로세서는 본래의 처리에만 집중할 수 있어 처리 시간이 줄어듭니다. 식당에서 주방장이 요리하기 전에 보조가 재료를 미리 손질해 두는 것과 같습니다.","choices":[{"verdict":"오답","why":"Duplexing(이중화·양방향 통신)은 장치나 회선을 두 개로 두거나 송수신을 동시에 하는 방식으로, 입력을 미리 처리하는 것과는 관계가 없습니다."},{"verdict":"정답","why":"FEP(Front-End Processor)는 입력 데이터를 프로세서가 처리하기 전에 미리 처리하여 프로세서의 처리 시간을 줄여 주는 프로그램 또는 하드웨어입니다."},{"verdict":"오답","why":"EAI(Enterprise Application Integration)는 기업 내 여러 애플리케이션을 연계·통합하는 솔루션입니다."},{"verdict":"오답","why":"GPL(General Public License)은 자유 소프트웨어 재단이 만든 오픈소스 라이선스입니다."}],"keywords":[{"term":"FEP(Front-End Processor)","desc":"호스트 앞단에서 입력 데이터를 미리 처리하는 전처리기"},{"term":"EAI(Enterprise Application Integration)","desc":"기업 내 이기종 애플리케이션을 연계·통합하는 솔루션"},{"term":"ESB(Enterprise Service Bus)","desc":"버스를 중심으로 서비스를 느슨하게 연계하는 통합 방식"},{"term":"GPL(General Public License)","desc":"소스 공개 의무가 있는 대표적 오픈소스 라이선스"}],"memo":"Front(앞)에서 먼저 처리 = FEP, 앞단 손질 담당"}},{"id":"written-2026-1-2","no":2,"unit":"소프트웨어 설계","q":"파이프 필터 형태의 소프트웨어 아키텍처에 관한 설명으로 옳은 것은?","choices":["계층 모델이라고도 부른다.","노드와 간선으로 이루어진다.","서브시스템이 입력 데이터를 받아서 처리한 뒤 그 결과를 다음 서브시스템에 넘겨주는 과정을 반복한다.","3개의 서브시스템(모델, 뷰, 제어)으로 이루어져 있다."],"ans":3,"exp":{"concept":"파이프-필터(Pipe-Filter) 아키텍처는 데이터가 흐르는 각 처리 단계를 필터로 만들고, 필터끼리 파이프로 이어서 앞 단계의 처리 결과를 다음 단계로 넘기는 구조입니다. 공장의 컨베이어 벨트처럼 각 작업대(필터)가 받은 것을 가공해서 다음 작업대로 넘겨주는 모습입니다. 데이터 변환, 컴파일러, 유닉스 셸의 파이프(|) 등에 쓰입니다.","choices":[{"verdict":"오답","why":"계층 모델은 레이어 패턴(Layers Pattern)의 다른 이름으로, 시스템을 계층으로 나누어 위아래 계층끼리만 상호작용하는 구조입니다."},{"verdict":"오답","why":"노드와 간선은 그래프를 이루는 일반적인 구성 요소를 말하는 표현일 뿐, 파이프-필터 아키텍처를 설명하는 정의가 아닙니다."},{"verdict":"정답","why":"파이프-필터는 서브시스템(필터)이 입력 데이터를 받아 처리한 뒤 그 결과를 파이프를 통해 다음 서브시스템으로 넘겨주는 과정을 반복하는 구조입니다."},{"verdict":"오답","why":"모델, 뷰, 제어의 3개 서브시스템으로 이루어진 것은 MVC(Model-View-Controller) 패턴입니다."}],"keywords":[{"term":"파이프-필터 패턴","desc":"필터(처리 단계)를 파이프로 연결해 데이터를 차례로 넘기는 구조"},{"term":"레이어 패턴","desc":"시스템을 계층으로 나누는 구조, 계층 모델이라고도 함(예: OSI 7계층)"},{"term":"MVC 패턴","desc":"모델·뷰·컨트롤러 3개 서브시스템으로 구성"},{"term":"클라이언트-서버 패턴","desc":"하나의 서버와 여러 클라이언트로 구성"},{"term":"마스터-슬레이브 패턴","desc":"마스터가 슬레이브들을 제어하는 구조, 실시간 시스템에 사용"}],"memo":"파이프 = 수도관, 물(데이터)이 필터를 차례로 통과한다"}},{"id":"written-2026-1-3","no":3,"unit":"소프트웨어 설계","q":"다음이 설명하는 디자인 패턴은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>객체를 하나 생성하면 그 객체를 어디서나 참조할 수 있으나, 여러 프로세스가 동시에 참조하는 것은 불가능하다.</li><li>클래스 내에서 인스턴스가 하나뿐임을 보장하고, 불필요한 메모리 낭비를 최소화할 수 있다.</li></ul></div>","choices":["Singleton","Decorator","Adapter","Prototype"],"ans":1,"exp":{"concept":"싱글톤(Singleton) 패턴은 어떤 클래스의 인스턴스(객체)가 프로그램 전체에서 딱 하나만 만들어지도록 보장하는 생성 패턴입니다. 한 번 만든 객체를 어디서나 꺼내 쓰므로 불필요하게 객체를 여러 번 만드는 메모리 낭비를 줄일 수 있습니다. 교과서에서는 '어디서든 참조할 수 있지만 여러 프로세스가 동시에 참조할 수는 없다'는 특징을 함께 외웁니다. 학교에 교장 선생님이 한 명뿐인 것과 비슷합니다.","choices":[{"verdict":"정답","why":"인스턴스가 하나뿐임을 보장하고, 생성된 객체를 어디서든 참조할 수 있게 하는 패턴은 싱글톤(Singleton)입니다."},{"verdict":"오답","why":"데코레이터(Decorator)는 객체 간 결합을 통해 기존 객체에 기능을 동적으로 덧붙이는 구조 패턴입니다."},{"verdict":"오답","why":"어댑터(Adapter)는 호환되지 않는 인터페이스를 가진 클래스들을 연결해 함께 쓸 수 있게 하는 구조 패턴입니다."},{"verdict":"오답","why":"프로토타입(Prototype)은 원본 객체를 복제하는 방법으로 새 객체를 생성하는 생성 패턴입니다."}],"keywords":[{"term":"Singleton","desc":"인스턴스를 하나만 만들도록 보장하는 생성 패턴"},{"term":"Prototype","desc":"원본 객체를 복제해 새 객체를 만드는 생성 패턴"},{"term":"Decorator","desc":"객체에 기능을 동적으로 추가하는 구조 패턴"},{"term":"Adapter","desc":"호환되지 않는 인터페이스를 이어 주는 구조 패턴"}],"memo":"Single = 하나, 싱글톤은 인스턴스가 딱 하나"}},{"id":"written-2026-1-4","no":4,"unit":"소프트웨어 설계","q":"GoF(Gangs of Four) 디자인 패턴의 분류에 속하지 않는 것은?","choices":["구조 패턴","객체 패턴","행위 패턴","생성 패턴"],"ans":2,"exp":{"concept":"GoF(Gang of Four) 디자인 패턴은 네 명의 저자가 정리한 23가지 설계 패턴으로, 목적에 따라 생성 패턴, 구조 패턴, 행위 패턴의 세 가지로 나뉩니다. 생성은 객체를 만드는 방법, 구조는 클래스·객체를 조합하는 방법, 행위는 객체끼리 책임을 나누고 소통하는 방법을 다룹니다. '객체 패턴'이라는 분류는 없습니다.","choices":[{"verdict":"오답","why":"구조 패턴(Structural Pattern)은 클래스나 객체를 조합해 더 큰 구조를 만드는 패턴으로 GoF 분류에 속합니다(어댑터, 브리지, 컴포지트, 데코레이터, 퍼사드, 플라이웨이트, 프록시)."},{"verdict":"정답","why":"GoF 디자인 패턴은 생성·구조·행위 패턴 세 가지로만 분류하며, 객체 패턴이라는 분류는 없습니다."},{"verdict":"오답","why":"행위 패턴(Behavioral Pattern)은 객체 사이의 상호작용과 책임 분배를 다루는 패턴으로 GoF 분류에 속합니다(옵서버, 전략, 커맨드 등 11개)."},{"verdict":"오답","why":"생성 패턴(Creational Pattern)은 객체 생성 방식을 다루는 패턴으로 GoF 분류에 속합니다(추상 팩토리, 빌더, 팩토리 메소드, 프로토타입, 싱글톤)."}],"keywords":[{"term":"생성 패턴(5개)","desc":"추상 팩토리, 빌더, 팩토리 메소드, 프로토타입, 싱글톤"},{"term":"구조 패턴(7개)","desc":"어댑터, 브리지, 컴포지트, 데코레이터, 퍼사드, 플라이웨이트, 프록시"},{"term":"행위 패턴(11개)","desc":"책임 연쇄, 커맨드, 인터프리터, 반복자, 중재자, 메멘토, 옵서버, 상태, 전략, 템플릿 메소드, 방문자"}],"memo":"GoF는 생구행(생성·구조·행위), 5·7·11개"}},{"id":"written-2026-1-5","no":5,"unit":"소프트웨어 설계","q":"다음 중 비기능 요구사항에 관한 설명으로 옳은 것은?","choices":["처리 속도 및 시간, 처리량 등 성능에 관한 요구사항은 비기능 요구사항에 해당하지 않는다.","“차량 대여 시스템에서 제공하는 모든 화면은 3초 안에 사용자에게 보여야 한다”는 것은 비기능 요구사항에 해당한다.","은행의 조회, 입금, 출금, 이체 등이 어떻게 수행되는지의 여부는 비기능 요구사항에 해당한다.","보안 및 접근 통제를 위한 요구사항은 비기능 요구사항에는 해당하지 않는다."],"ans":2,"exp":{"concept":"기능 요구사항은 시스템이 '무엇을 하는가'(조회, 입금, 출금 같은 기능)이고, 비기능 요구사항은 그 기능을 '얼마나 잘 하는가'(성능, 보안, 품질, 제약사항)입니다. 자동차로 치면 '달린다, 멈춘다'는 기능이고 '시속 100km까지 5초, 잠금장치 필수'는 비기능입니다.","choices":[{"verdict":"오답","why":"처리 속도·시간·처리량 같은 성능 요구사항은 대표적인 비기능 요구사항입니다."},{"verdict":"정답","why":"'모든 화면은 3초 안에 보여야 한다'는 응답 시간, 즉 성능에 관한 요구사항이므로 비기능 요구사항입니다."},{"verdict":"오답","why":"조회·입금·출금·이체가 어떻게 수행되는지는 시스템이 제공해야 할 기능 자체이므로 기능 요구사항입니다."},{"verdict":"오답","why":"보안 및 접근 통제 요구사항은 대표적인 비기능 요구사항입니다."}],"keywords":[{"term":"기능 요구사항","desc":"시스템이 수행해야 할 기능(입력·출력·처리)에 대한 요구"},{"term":"비기능 요구사항","desc":"성능, 보안, 품질, 제약사항 등 기능 외적인 요구"},{"term":"성능 요구사항","desc":"처리 속도, 응답 시간, 처리량 등"}],"memo":"기능 = 무엇을, 비기능 = 얼마나 빠르고 안전하게"}},{"id":"written-2026-1-6","no":6,"unit":"소프트웨어 설계","q":"통신용 프로그램을 생성해 포트를 할당하고, 클라이언트가 통신을 요청하면 해당 클라이언트와 연결해 주는 내·외부 송·수신 연계기술은?","choices":["소켓 기술","프로토타입 기술","DB링크 기술","스크럼 기술"],"ans":1,"exp":{"concept":"연계 기술은 서로 다른 시스템이 데이터를 주고받게 해 주는 방법입니다. 그중 소켓(Socket)은 통신용 프로그램을 만들어 포트를 열어 두고, 클라이언트가 접속을 요청하면 연결해 주는 방식입니다. 가게 문(포트)을 열어 두고 손님(클라이언트)이 오면 맞이하는 것과 같습니다.","choices":[{"verdict":"정답","why":"소켓 기술은 서버 소켓을 생성해 포트를 할당하고, 클라이언트의 통신 요청 시 클라이언트와 연결해 송수신하는 연계 기술입니다."},{"verdict":"오답","why":"프로토타입은 실제 시스템을 만들기 전 견본(시제품)을 만들어 요구사항을 확인하는 개발 기법으로, 연계 기술이 아닙니다."},{"verdict":"오답","why":"DB 링크는 데이터베이스가 제공하는 DB 링크 객체를 이용해 수신 측 DB가 송신 측 DB에 직접 접속하는 연계 기술로, 포트 할당·클라이언트 연결 방식이 아닙니다."},{"verdict":"오답","why":"스크럼(Scrum)은 팀이 짧은 주기(스프린트)로 개발하는 애자일 방법론으로, 연계 기술이 아닙니다."}],"keywords":[{"term":"소켓(Socket)","desc":"포트를 할당하고 클라이언트 요청 시 연결해 통신하는 기술"},{"term":"DB 링크(DB Link)","desc":"DB 링크 객체로 상대 DB에 직접 접속하는 연계 기술"},{"term":"API/Open API","desc":"송신 측이 제공하는 API로 데이터를 가져가는 연계 기술"},{"term":"웹 서비스(Web Service)","desc":"WSDL, UDDI, SOAP 프로토콜을 이용한 연계 기술"}],"memo":"소켓 = 콘센트, 포트에 꽂아(연결해) 통신한다"}},{"id":"written-2026-1-7","no":7,"unit":"소프트웨어 설계","q":"다음 중 CASE의 장점에 해당하지 않는 것은?","choices":["소프트웨어의 유지보수를 간편하게 수행할 수 있게 된다.","자동화된 기법을 통해 소프트웨어의 품질이 향상된다.","소프트웨어 모듈의 재사용성은 줄어든다.","소프트웨어의 생산성을 향상시킨다."],"ans":3,"exp":{"concept":"CASE(Computer Aided Software Engineering)는 소프트웨어 개발 과정의 분석·설계·구현·테스트 작업을 컴퓨터 도구로 자동화해 돕는 것입니다. 자동화 덕분에 생산성과 품질이 오르고, 유지보수가 쉬워지며, 만든 모듈을 재사용하기도 쉬워집니다. 손으로 설계도를 그리다가 설계 프로그램을 쓰게 된 것과 비슷합니다.","choices":[{"verdict":"오답","why":"CASE를 쓰면 문서와 설계가 자동으로 관리되어 유지보수를 간편하게 할 수 있으므로 장점에 해당합니다."},{"verdict":"오답","why":"자동화된 기법으로 오류가 줄어 소프트웨어 품질이 향상되므로 장점에 해당합니다."},{"verdict":"정답","why":"CASE는 모듈의 재사용성을 높여 주므로 '재사용성이 줄어든다'는 장점이 아니며 사실과도 반대입니다."},{"verdict":"오답","why":"개발 작업을 자동화해 소프트웨어 생산성을 향상시키므로 장점에 해당합니다."}],"keywords":[{"term":"CASE(Computer Aided Software Engineering)","desc":"소프트웨어 개발 과정을 자동화하는 도구·기법"},{"term":"상위 CASE","desc":"요구 분석·설계 단계를 지원"},{"term":"하위 CASE","desc":"코드 작성·테스트·문서화 단계를 지원"}],"memo":"CASE 장점은 다 '올라간다'(생산성·품질·재사용성↑, 유지보수 쉬움)"}},{"id":"written-2026-1-8","no":8,"unit":"소프트웨어 설계","q":"기본 유스케이스를 수행하는 도중 특별한 조건이 만족될 때 수행되는 유스케이스는?","choices":["특화","선택","연관","확장"],"ans":4,"exp":{"concept":"유스케이스 다이어그램에서 유스케이스끼리의 관계에는 포함, 확장, 일반화(특화) 등이 있습니다. 포함(include)은 기본 유스케이스를 수행할 때 반드시 함께 실행되는 것이고, 확장(extend)은 특정 조건이 만족될 때만 추가로 실행되는 것입니다. 예를 들어 '물건 주문'을 하다가 쿠폰이 있을 때만 '쿠폰 적용'을 하는 것이 확장입니다.","choices":[{"verdict":"오답","why":"특화(일반화, Generalization)는 상위 유스케이스와 이를 구체화한 하위 유스케이스 사이의 관계로, 조건부 실행과는 다릅니다."},{"verdict":"오답","why":"'선택'은 UML 유스케이스 관계의 공식 명칭이 아닙니다."},{"verdict":"오답","why":"연관(Association)은 액터와 유스케이스가 서로 상호작용한다는 것을 나타내는 관계입니다."},{"verdict":"정답","why":"확장(extend)은 기본 유스케이스 수행 중 특정 조건이 만족될 때만 실행되는 유스케이스와의 관계입니다."}],"keywords":[{"term":"포함(include)","desc":"기본 유스케이스 수행 시 반드시 함께 수행되는 관계"},{"term":"확장(extend)","desc":"특정 조건을 만족할 때만 수행되는 관계"},{"term":"일반화(Generalization)","desc":"상위·하위(특화) 유스케이스 간의 관계"},{"term":"연관(Association)","desc":"액터와 유스케이스 사이의 상호작용 관계"}],"memo":"포함은 항상, 확장은 조건 맞을 때만(extend = 옵션 추가)"}},{"id":"written-2026-1-9","no":9,"unit":"소프트웨어 설계","q":"아키텍처 설계 과정을 올바른 순서대로 나열한 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul class=\"is-labeled\"><li>가. 설계 목표 설정</li><li>나. 시스템 타입 결정</li><li>다. 스타일 적용 및 커스터마이즈</li><li>라. 서브시스템의 기능, 인터페이스 동작 작성</li><li>마. 아키텍처 설계 검토</li></ul></div>","choices":["㉮ → ㉯ → ㉰ → ㉱ → ㉲","㉲ → ㉮ → ㉯ → ㉱ → ㉰","㉮ → ㉲ → ㉯ → ㉱ → ㉰","㉮ → ㉯ → ㉰ → ㉲ → ㉱"],"ans":1,"exp":{"concept":"아키텍처 설계는 집을 짓기 전 설계도를 그리는 것처럼, 무엇을 목표로 할지 정하고 큰 틀을 고른 뒤 세부를 채우고 마지막에 검토합니다. 순서는 설계 목표 설정 → 시스템 타입 결정 → 아키텍처 패턴(스타일) 적용 및 커스터마이즈 → 서브시스템 구체화(기능·인터페이스 작성) → 검토입니다.","choices":[{"verdict":"정답","why":"설계 목표 설정(가) → 시스템 타입 결정(나) → 스타일 적용 및 커스터마이즈(다) → 서브시스템 기능·인터페이스 작성(라) → 아키텍처 설계 검토(마)가 올바른 순서입니다."},{"verdict":"오답","why":"검토(마)는 설계가 끝난 뒤 마지막에 하는 단계이므로 맨 앞에 올 수 없습니다."},{"verdict":"오답","why":"검토(마)가 두 번째에 오고, 스타일 적용(다)이 서브시스템 작성(라) 뒤에 와서 순서가 틀립니다."},{"verdict":"오답","why":"서브시스템 기능·인터페이스 작성(라)을 마친 뒤 검토(마)해야 하는데 둘의 순서가 바뀌었습니다."}],"keywords":[{"term":"소프트웨어 아키텍처","desc":"시스템의 구성 요소와 그 관계를 나타내는 전체 구조"},{"term":"아키텍처 패턴(스타일)","desc":"자주 쓰이는 아키텍처 구조의 전형(레이어, MVC 등)"},{"term":"서브시스템","desc":"전체 시스템을 이루는 독립적인 기능 단위"}],"memo":"목표 → 타입 → 스타일 → 서브시스템 → 검토 (목·타·스·서·검)"}},{"id":"written-2026-1-10","no":10,"unit":"소프트웨어 설계","q":"다음 설명에 해당하는 시스템은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>시스템 인터페이스를 구성하는 시스템으로, 연계할 데이터를 데이터베이스와 애플리케이션으로부터 연계 테이블 또는 파일 형태로 생성하여 송신하는 시스템이다.</p></div>","choices":["수신 시스템","연계 서버","중계 서버","송신 시스템"],"ans":4,"exp":{"concept":"시스템 연계는 데이터를 보내는 쪽(송신 시스템), 받는 쪽(수신 시스템), 그 사이에서 전달을 돕는 쪽(연계 서버, 중계 서버)으로 구성됩니다. 송신 시스템은 보낼 데이터를 DB나 애플리케이션에서 뽑아 연계 테이블이나 파일로 만들어 보냅니다. 편지를 써서 봉투에 넣어 부치는 사람이 송신 시스템입니다.","choices":[{"verdict":"오답","why":"수신 시스템은 받은 연계 테이블이나 파일을 자신의 형식에 맞게 변환해 DB에 저장하거나 애플리케이션에 활용하는 시스템입니다."},{"verdict":"오답","why":"연계 서버는 송신·수신 시스템 사이에서 데이터를 주고받는 송수신 처리와 진행 상태 관리를 수행하는 서버입니다."},{"verdict":"오답","why":"중계 서버는 내부망과 외부망 구간을 분리해 보안을 강화하기 위해 사이에 두는 서버입니다."},{"verdict":"정답","why":"연계할 데이터를 DB와 애플리케이션에서 연계 테이블 또는 파일 형태로 생성하여 송신하는 시스템은 송신 시스템입니다."}],"keywords":[{"term":"송신 시스템","desc":"연계 데이터를 테이블·파일로 생성해 보내는 시스템"},{"term":"수신 시스템","desc":"받은 데이터를 변환해 DB·애플리케이션에 반영하는 시스템"},{"term":"연계 서버","desc":"송수신 처리와 진행 상태를 관리하는 서버"},{"term":"중계 서버","desc":"내·외부 구간을 분리해 보안을 강화하는 서버"}],"memo":"'생성하여 송신' = 송신 시스템, 문장 끝 단어가 답"}},{"id":"written-2026-1-11","no":11,"unit":"소프트웨어 설계","q":"명확한 역할을 지니고 독립적으로 존재할 수 있는 시스템의 부분으로, 넓은 의미에서는 재사용되는 모든 단위라 할 수 있으며 인터페이스를 통해서만 접근이 가능한 것은?","choices":["Model","Cell","Component","Sheet"],"ans":3,"exp":{"concept":"컴포넌트(Component)는 명확한 역할을 갖고 독립적으로 존재할 수 있는 시스템의 부품입니다. 넓게는 재사용되는 모든 단위를 말하며, 내부는 감추고 인터페이스를 통해서만 접근합니다. 레고 블록처럼 정해진 연결 부위(인터페이스)로만 끼워 쓰는 부품이라고 생각하면 됩니다.","choices":[{"verdict":"오답","why":"Model(모델)은 현실 세계를 단순화해 표현한 것, 또는 MVC에서 데이터와 핵심 로직을 담당하는 부분을 뜻합니다."},{"verdict":"오답","why":"Cell(셀)은 표나 스프레드시트의 한 칸 등을 뜻하며, 재사용 단위의 정의와 관계가 없습니다."},{"verdict":"정답","why":"독립적으로 존재할 수 있고 재사용되며 인터페이스를 통해서만 접근할 수 있는 시스템의 부분은 컴포넌트(Component)입니다."},{"verdict":"오답","why":"Sheet(시트)는 스프레드시트의 작업 화면 등을 뜻하며, 이 정의와 관계가 없습니다."}],"keywords":[{"term":"컴포넌트(Component)","desc":"독립적이고 재사용 가능하며 인터페이스로만 접근하는 단위"},{"term":"CBD(Component Based Development)","desc":"컴포넌트를 조립해 소프트웨어를 만드는 개발 방법론"},{"term":"인터페이스(Interface)","desc":"구성 요소끼리 주고받는 방법을 정한 접점"}],"memo":"컴포넌트 = 레고 블록, 연결부(인터페이스)로만 조립"}},{"id":"written-2026-1-12","no":12,"unit":"소프트웨어 설계","q":"CASE에 관한 설명 중 옳지 않은 것은?","choices":["소프트웨어 사용자들이 소프트웨어 사용 방법을 빠르게 익힐 수 있도록 개발된 자동화 패키지이다.","자동화된 기법을 이용하여 소프트웨어 품질이 향상된다.","소프트웨어 유지보수를 간편하게 수행할 수 있게 된다.","소프트웨어 모듈의 재사용성이 높아진다."],"ans":1,"exp":{"concept":"CASE(Computer Aided Software Engineering)는 소프트웨어를 '개발하는' 과정(분석, 설계, 구현, 테스트, 유지보수)을 자동화해 개발자를 돕는 도구입니다. 사용자가 완성된 프로그램 사용법을 배우도록 돕는 교육용 도구가 아닙니다. 대상이 사용자가 아니라 개발자라는 점이 핵심입니다.","choices":[{"verdict":"정답","why":"CASE는 소프트웨어 개발 과정을 자동화하는 도구이며, 사용자에게 사용 방법을 익히게 하는 패키지가 아니므로 옳지 않은 설명입니다."},{"verdict":"오답","why":"자동화된 기법을 이용해 소프트웨어 품질이 향상되는 것은 CASE의 장점으로 옳은 설명입니다."},{"verdict":"오답","why":"설계·문서가 자동 관리되어 유지보수가 간편해지는 것은 CASE의 장점으로 옳은 설명입니다."},{"verdict":"오답","why":"CASE를 쓰면 모듈의 재사용성이 높아지므로 옳은 설명입니다."}],"keywords":[{"term":"CASE","desc":"컴퓨터를 이용해 소프트웨어 개발 과정을 자동화하는 도구"},{"term":"CASE의 장점","desc":"생산성·품질·재사용성 향상, 유지보수 용이, 개발 기간 단축"},{"term":"통합 CASE(I-CASE)","desc":"소프트웨어 개발 전 과정을 통합 지원하는 CASE"}],"memo":"CASE의 E는 Engineering, 사용자 교육이 아니라 개발 자동화"}},{"id":"written-2026-1-13","no":13,"unit":"소프트웨어 설계","q":"분산 시스템을 위한 마스터-슬레이브(Master-Slave) 아키텍처에 관한 설명 중 틀린 것은?","choices":["마스터 프로세스는 슬레이브 프로세스들을 제어할 수 있다.","일반적으로 실시간 시스템에 사용된다.","마스터 프로세스는 일반적으로 연산, 통신, 조정을 담당한다.","슬레이브 프로세스는 데이터 수집 기능을 수행하지 못한다."],"ans":4,"exp":{"concept":"마스터-슬레이브(Master-Slave) 아키텍처는 하나의 마스터가 여러 슬레이브에게 일을 나눠 주고 제어하는 구조입니다. 마스터는 연산·통신·조정을 맡고, 슬레이브는 마스터의 지시에 따라 데이터 수집 같은 실제 작업을 수행해 결과를 돌려줍니다. 반장(마스터)이 조원(슬레이브)에게 자료 조사를 시키는 것과 같으며 주로 실시간 시스템에 쓰입니다.","choices":[{"verdict":"오답","why":"마스터 프로세스가 슬레이브 프로세스들을 제어하는 것이 이 구조의 기본 특징이므로 옳은 설명입니다."},{"verdict":"오답","why":"마스터-슬레이브 구조는 일반적으로 실시간 시스템에서 사용되므로 옳은 설명입니다."},{"verdict":"오답","why":"마스터 프로세스는 일반적으로 연산, 통신, 조정을 책임지므로 옳은 설명입니다."},{"verdict":"정답","why":"슬레이브 프로세스는 마스터의 제어를 받아 데이터 수집 기능을 수행할 수 있으므로 '수행하지 못한다'는 틀린 설명입니다."}],"keywords":[{"term":"마스터-슬레이브 패턴","desc":"마스터가 슬레이브를 제어, 실시간 시스템에 사용"},{"term":"마스터(Master)","desc":"연산, 통신, 조정 담당"},{"term":"슬레이브(Slave)","desc":"마스터 지시에 따라 데이터 수집 등 작업 수행"}],"memo":"마스터는 지시·조정, 슬레이브는 현장에서 데이터 수집"}},{"id":"written-2026-1-14","no":14,"unit":"소프트웨어 설계","q":"순차 다이어그램(Sequence Diagram)에 대한 설명 중 틀린 것은?","choices":["객체들 간의 상호 작용을 나타내는 데 사용한다.","교류 다이어그램(Interaction Diagram)의 한 종류에 해당한다.","시간의 흐름에 따라 객체들이 주고 받는 메시지의 전달 과정을 강조하여 표현한다.","동적 다이어그램보다 정적 다이어그램에 가깝다."],"ans":4,"exp":{"concept":"UML 다이어그램은 시스템의 뼈대(구조)를 그리는 정적 다이어그램과, 시간에 따른 움직임(행위)을 그리는 동적 다이어그램으로 나뉩니다. 순차 다이어그램(Sequence Diagram)은 객체들이 시간 순서대로 메시지를 주고받는 과정을 그리는 대표적인 동적(행위) 다이어그램이며, 상호작용 다이어그램의 한 종류입니다. 만화의 컷을 시간 순서로 늘어놓은 것과 비슷합니다.","choices":[{"verdict":"오답","why":"순차 다이어그램은 객체들 간의 상호작용을 메시지로 나타내므로 옳은 설명입니다."},{"verdict":"오답","why":"순차 다이어그램은 교류(상호작용) 다이어그램(Interaction Diagram)에 속하므로 옳은 설명입니다."},{"verdict":"오답","why":"시간의 흐름에 따라 객체 간 메시지 전달 과정을 강조해 표현하는 것이 순차 다이어그램의 특징이므로 옳은 설명입니다."},{"verdict":"정답","why":"순차 다이어그램은 시간에 따른 행위를 표현하는 동적(행위) 다이어그램이므로 '정적 다이어그램에 가깝다'는 틀린 설명입니다."}],"keywords":[{"term":"구조(정적) 다이어그램","desc":"클래스, 객체, 컴포넌트, 배치, 복합체 구조, 패키지 다이어그램"},{"term":"행위(동적) 다이어그램","desc":"유스케이스, 순차, 커뮤니케이션, 상태, 활동, 상호작용 개요, 타이밍 다이어그램"},{"term":"순차 다이어그램","desc":"시간 순서에 따른 객체 간 메시지 흐름 표현"},{"term":"커뮤니케이션 다이어그램","desc":"메시지뿐 아니라 객체 간 연관까지 표현"}],"memo":"순차 = 시간 순서 = 움직임 = 동적"}},{"id":"written-2026-1-15","no":15,"unit":"소프트웨어 설계","q":"분산 시스템의 미들웨어(Middleware)에 관한 설명 중 틀린 것은?","choices":["분산 시스템의 다양한 부분을 관리하고 통신하며 데이터를 교환하도록 해주는 소프트웨어로 볼 수 있다.","애플리케이션과 사용자 사이에서만 분산 서비스를 제공해 준다.","위치 투명성(Location Transparency)을 제공해 준다.","분산 시스템의 여러 컴포넌트가 요구하는 재사용 가능한 서비스의 구현을 제공해 준다."],"ans":2,"exp":{"concept":"미들웨어(Middleware)는 운영체제와 응용 프로그램 사이, 클라이언트와 서버 사이처럼 서로 다른 시스템의 '중간'에서 통신과 데이터 교환을 돕는 소프트웨어입니다. 분산 시스템의 여러 부분이 상대가 어디에 있는지 몰라도(위치 투명성) 함께 일할 수 있게 해 줍니다. 서로 다른 언어를 쓰는 사람 사이의 통역사와 같습니다.","choices":[{"verdict":"오답","why":"미들웨어는 분산 시스템의 다양한 부분을 관리하고 통신·데이터 교환을 가능하게 하는 소프트웨어이므로 옳은 설명입니다."},{"verdict":"정답","why":"미들웨어는 애플리케이션과 사용자 사이뿐 아니라 운영체제와 애플리케이션, 클라이언트와 서버 등 다양한 계층 사이에서 서비스를 제공하므로 '사이에서만'은 틀린 설명입니다."},{"verdict":"오답","why":"미들웨어는 자원의 실제 위치를 몰라도 접근할 수 있는 위치 투명성을 제공하므로 옳은 설명입니다."},{"verdict":"오답","why":"여러 컴포넌트가 공통으로 필요로 하는 재사용 가능한 서비스의 구현을 제공하므로 옳은 설명입니다."}],"keywords":[{"term":"미들웨어(Middleware)","desc":"이기종 시스템 사이에서 통신·데이터 교환을 중개하는 소프트웨어"},{"term":"위치 투명성","desc":"자원의 물리적 위치를 몰라도 접근할 수 있는 성질"},{"term":"미들웨어 종류","desc":"DB, RPC, MOM, TP-Monitor, ORB, WAS"}],"memo":"미들(Middle) = 가운데, 여기저기 사이에 다 끼는 통역사"}},{"id":"written-2026-1-16","no":16,"unit":"소프트웨어 설계","q":"객체에 어떤 행위를 수행하도록 지시하는 명령을 무엇이라 하는가?","choices":["Class","Message","Package","Object"],"ans":2,"exp":{"concept":"객체지향에서 객체에게 '이 일을 해라'라고 요청하는 것을 메시지(Message)라고 합니다. 메시지를 받은 객체는 자신이 가진 메소드(함수)를 실행해 응답합니다. 리모컨 버튼을 눌러 TV에 '채널을 바꿔라'고 신호를 보내는 것이 메시지입니다.","choices":[{"verdict":"오답","why":"Class(클래스)는 공통된 속성과 연산을 가진 객체들을 만들기 위한 틀(설계도)입니다."},{"verdict":"정답","why":"객체에게 어떤 행위를 수행하도록 지시하는 명령(요청)을 Message(메시지)라고 합니다."},{"verdict":"오답","why":"Package(패키지)는 관련된 클래스나 요소들을 묶어 놓은 그룹입니다."},{"verdict":"오답","why":"Object(객체)는 데이터(속성)와 그 데이터를 처리하는 함수(메소드)를 하나로 묶은 실체로, 메시지를 받는 대상입니다."}],"keywords":[{"term":"메시지(Message)","desc":"객체에게 행위를 요청하는 명령"},{"term":"메소드(Method)","desc":"객체가 수행하는 연산(함수)"},{"term":"클래스(Class)","desc":"같은 속성·연산을 가진 객체의 틀"},{"term":"인스턴스(Instance)","desc":"클래스로부터 만들어진 실제 객체"}],"memo":"메시지 = 문자 메시지로 '이거 해 줘' 보내기"}},{"id":"written-2026-1-17","no":17,"unit":"소프트웨어 설계","q":"다음 중 소프트웨어 공학의 기본 원칙에 해당한다고 볼 수 없는 것은?","choices":["품질이 높은 소프트웨어 상품의 개발","인력을 최대한 많이 투입","검증을 지속적으로 시행","결과에 대한 기록을 명확하게 유지"],"ans":2,"exp":{"concept":"소프트웨어 공학의 기본 원칙은 현대적인 프로그래밍 기술을 계속 적용하고, 개발 과정에서 지속적으로 검증하며, 결과를 명확히 기록(문서화)하고, 품질 높은 소프트웨어를 만드는 것입니다. 사람을 많이 넣는다고 좋아지지 않으며, 오히려 늦어진 프로젝트에 인력을 더 넣으면 더 늦어진다는 브룩스의 법칙도 있습니다. 요리사가 많으면 배가 산으로 가는 것과 같습니다.","choices":[{"verdict":"오답","why":"품질 높은 소프트웨어 상품 개발은 소프트웨어 공학의 기본 원칙에 해당합니다."},{"verdict":"정답","why":"인력을 최대한 많이 투입하는 것은 기본 원칙이 아니며, 오히려 의사소통 비용이 늘어 효율이 떨어질 수 있습니다(브룩스의 법칙)."},{"verdict":"오답","why":"개발 단계마다 지속적인 검증을 시행하는 것은 기본 원칙에 해당합니다."},{"verdict":"오답","why":"결과에 대한 명확한 기록(문서화) 유지는 기본 원칙에 해당합니다."}],"keywords":[{"term":"소프트웨어 공학 기본 원칙","desc":"현대적 기술 적용, 지속적 검증, 명확한 기록 유지, 고품질 개발"},{"term":"브룩스의 법칙(Brooks' Law)","desc":"지연된 프로젝트에 인력을 추가하면 더 지연된다"},{"term":"소프트웨어 위기","desc":"개발 속도가 수요를 따라가지 못해 생긴 비용·품질 문제"}],"memo":"사람 많이 = 원칙 아님, 브룩스가 '더 늦어진다'고 했다"}},{"id":"written-2026-1-18","no":18,"unit":"소프트웨어 설계","q":"캡슐화된 객체 내부의 자료 구조나 함수 이용이 외부로부터 영향을 받지 않도록 부작용을 최소화하는 객체지향 개념은?","choices":["Inheritance","Information Hiding","Polymorphism","Finding"],"ans":2,"exp":{"concept":"정보 은닉(Information Hiding)은 객체 내부의 자료 구조나 처리 방법을 바깥에서 볼 수 없게 감추고, 정해진 인터페이스로만 접근하게 하는 개념입니다. 내부를 고쳐도 바깥에 영향이 가지 않아 부작용(Side Effect)이 줄어듭니다. 자동차 운전자는 엔진 구조를 몰라도 핸들과 페달(인터페이스)만으로 운전할 수 있는 것과 같습니다.","choices":[{"verdict":"오답","why":"Inheritance(상속)는 상위 클래스의 속성과 연산을 하위 클래스가 물려받아 쓰는 개념입니다."},{"verdict":"정답","why":"캡슐화된 객체 내부를 감추어 외부의 영향을 받지 않도록 부작용을 최소화하는 개념은 Information Hiding(정보 은닉)입니다."},{"verdict":"오답","why":"Polymorphism(다형성)은 같은 메시지에 대해 객체마다 각자의 방식으로 응답하는 성질입니다(오버로딩, 오버라이딩)."},{"verdict":"오답","why":"Finding은 객체지향의 기본 개념이 아닙니다."}],"keywords":[{"term":"캡슐화(Encapsulation)","desc":"데이터와 함수를 하나로 묶는 것"},{"term":"정보 은닉(Information Hiding)","desc":"내부 정보를 감추고 인터페이스로만 접근"},{"term":"상속(Inheritance)","desc":"상위 클래스의 속성·연산을 물려받음"},{"term":"다형성(Polymorphism)","desc":"같은 메시지에 객체별로 다르게 응답"}],"memo":"Hiding = 숨기기, 숨기면 밖의 영향(부작용)을 덜 받는다"}},{"id":"written-2026-1-19","no":19,"unit":"소프트웨어 설계","q":"소프트웨어 아키텍처 모델 가운데 MVC(Model-View-Controller)에 대한 설명으로 틀린 것은?","choices":["뷰(View)는 모델(Model)에 있는 데이터를 사용자 인터페이스에 표시하는 역할을 맡는다.","모델(Model)은 뷰(View)와 제어(Controller) 사이에서 전달자 역할을 하고, 뷰마다 모델 서브시스템이 하나씩 각각 연결된다.","제어(Controller)는 모델(Model)에 명령을 보내 모델의 상태를 변경할 수 있다.","MVC 모델은 사용자 인터페이스를 맡는 계층의 응집도를 높일 수 있으며, 서로 다른 UI를 여러 개 만들어 그 사이의 결합도를 낮출 수 있다."],"ans":2,"exp":{"concept":"MVC(Model-View-Controller)는 프로그램을 데이터와 핵심 로직을 담는 모델, 화면에 보여 주는 뷰, 사용자 입력을 받아 처리하는 컨트롤러(제어)로 나누는 구조입니다. 컨트롤러가 모델과 뷰 사이의 전달자 역할을 하며, 뷰마다 컨트롤러가 하나씩 연결됩니다. 식당에 비유하면 주방(모델), 테이블에 놓인 요리(뷰), 주문을 받아 주방에 전하는 직원(컨트롤러)입니다.","choices":[{"verdict":"오답","why":"뷰는 모델의 데이터를 사용자 인터페이스에 표시하는 역할이므로 옳은 설명입니다."},{"verdict":"정답","why":"모델과 뷰 사이에서 전달자 역할을 하고 뷰마다 하나씩 연결되는 것은 모델이 아니라 제어(Controller)이므로 틀린 설명입니다."},{"verdict":"오답","why":"제어(컨트롤러)는 모델에 명령을 보내 모델의 상태를 변경할 수 있으므로 옳은 설명입니다."},{"verdict":"오답","why":"MVC는 UI 계층의 응집도를 높이고, 여러 개의 서로 다른 UI를 만들어 그 사이의 결합도를 낮출 수 있으므로 옳은 설명입니다."}],"keywords":[{"term":"모델(Model)","desc":"데이터와 핵심 기능(서비스) 담당"},{"term":"뷰(View)","desc":"모델의 정보를 사용자에게 표시"},{"term":"컨트롤러(Controller)","desc":"사용자 입력 처리, 모델과 뷰 사이 전달자, 뷰마다 하나씩 연결"}],"memo":"중간 다리(전달자)는 컨트롤러, 모델은 데이터 창고"}},{"id":"written-2026-1-20","no":20,"unit":"소프트웨어 설계","q":"소프트웨어 요구사항 분석을 위해 대상이 되는 목표 집단에 속한 사용자 유형을 대표하는 가상 인물을 표현한 것으로 다음 중 옳은 것은?","choices":["진첩도","스토리 맵","번업 차트","페르소나"],"ans":4,"exp":{"concept":"페르소나(Persona)는 실제 사용자 조사를 바탕으로, 서비스를 쓸 대표 사용자 유형을 한 명의 가상 인물로 만든 것입니다. 이름, 나이, 직업, 목표, 불편한 점 등을 정해 두면 요구사항을 분석하고 설계할 때 '이 사람이라면 무엇을 원할까'를 기준으로 생각할 수 있습니다. 소설가가 이야기 속 주인공의 성격을 미리 정해 두는 것과 비슷합니다.","choices":[{"verdict":"오답","why":"진척도(보기의 '진첩도')는 작업이 얼마나 진행되었는지의 정도를 나타내는 말로, 가상 사용자를 뜻하지 않습니다."},{"verdict":"오답","why":"스토리 맵(Story Map)은 사용자 스토리를 사용자의 활동 흐름과 우선순위에 따라 배치한 지도입니다."},{"verdict":"오답","why":"번업 차트(Burn-up Chart)는 완료된 작업량이 시간에 따라 쌓여 가는 것을 보여 주는 진행 관리 차트입니다."},{"verdict":"정답","why":"목표 사용자 집단의 유형을 대표하는 가상 인물을 표현한 것은 페르소나(Persona)입니다."}],"keywords":[{"term":"페르소나(Persona)","desc":"대표 사용자 유형을 나타낸 가상 인물"},{"term":"사용자 스토리(User Story)","desc":"사용자 관점에서 짧게 쓴 요구사항"},{"term":"번다운 차트(Burn-down Chart)","desc":"남은 작업량이 줄어드는 추이를 보여 주는 차트"},{"term":"번업 차트(Burn-up Chart)","desc":"완료 작업량이 늘어나는 추이를 보여 주는 차트"}],"memo":"페르소나 = 가면(persona), 사용자 가면을 쓴 가상 인물"}},{"id":"written-2026-1-21","no":21,"unit":"소프트웨어 개발","q":"소프트웨어 품질과 관련된 국제 표준인 ISO/IEC 25000에 대한 설명으로 옳지 않은 것은?","choices":["ISO/IEC 2501n에서는 소프트웨어의 내부 측정, 외부 측정, 사용 품질 측정, 품질 측정 요소 등을 다루고 있다.","소프트웨어 품질 평가를 위해 마련된 소프트웨어 품질평가 통합 모델 표준이다.","System and Software Quality Requirements and Evaluation을 줄여 SQuaRE라고도 부른다.","기존의 소프트웨어 품질 평가 모델과 소프트웨어 평가 절차 모델인 ISO/IEC 9126 및 ISO/IEC 14598을 통합한 것이다."],"ans":1,"exp":{"concept":"ISO/IEC 25000(SQuaRE)은 기존의 품질 모델 표준 ISO/IEC 9126과 평가 절차 표준 ISO/IEC 14598 등을 하나로 합친 소프트웨어 품질 평가 통합 모델 표준입니다. 번호대별로 2500n 품질 관리, 2501n 품질 모델, 2502n 품질 측정, 2503n 품질 요구, 2504n 품질 평가를 다룹니다. 내부 측정·외부 측정·사용 품질 측정·품질 측정 요소는 '측정'이므로 2502n에서 다룹니다.","choices":[{"verdict":"정답","why":"내부 측정, 외부 측정, 사용 품질 측정, 품질 측정 요소를 다루는 것은 2502n(품질 측정)이며, 2501n은 품질 모델을 다루므로 옳지 않은 설명입니다."},{"verdict":"오답","why":"ISO/IEC 25000은 소프트웨어 품질 평가를 위한 통합 모델 표준이므로 옳은 설명입니다."},{"verdict":"오답","why":"System and Software Quality Requirements and Evaluation의 약자로 SQuaRE라고 부르므로 옳은 설명입니다."},{"verdict":"오답","why":"품질 모델 ISO/IEC 9126과 평가 절차 ISO/IEC 14598 등을 통합한 것이므로 옳은 설명입니다."}],"keywords":[{"term":"2500n","desc":"품질 관리(전체 개요, 관리)"},{"term":"2501n","desc":"품질 모델(품질 특성 정의)"},{"term":"2502n","desc":"품질 측정(내부·외부·사용 품질 측정, 측정 요소)"},{"term":"2503n","desc":"품질 요구"},{"term":"2504n","desc":"품질 평가"}],"memo":"0관리 1모델 2측정 3요구 4평가 (관·모·측·요·평)"}},{"id":"written-2026-1-22","no":22,"unit":"소프트웨어 개발","q":"다음 중 알고리즘 설계 기법과 가장 거리가 먼 것은?","choices":["Divide and Conquer","Greedy","Backtracking","Static Block"],"ans":4,"exp":{"concept":"알고리즘 설계 기법은 문제를 푸는 전략의 종류입니다. 분할 정복(문제를 잘게 나눠 풀고 합치기), 탐욕법(매 순간 가장 좋아 보이는 선택), 백트래킹(가 보고 아니면 되돌아오기), 동적 계획법(작은 문제 답을 저장해 재사용) 등이 있습니다. Static Block(정적 블록)은 자바에서 클래스가 처음 로딩될 때 한 번 실행되는 코드 블록으로, 알고리즘 설계 기법이 아닙니다.","choices":[{"verdict":"오답","why":"Divide and Conquer(분할 정복)는 문제를 작은 문제로 나누어 해결한 뒤 결과를 합치는 알고리즘 설계 기법입니다."},{"verdict":"오답","why":"Greedy(탐욕법)는 매 단계에서 그 순간 최적인 선택을 하는 알고리즘 설계 기법입니다."},{"verdict":"오답","why":"Backtracking(백트래킹)은 해를 찾아가다 조건에 맞지 않으면 이전 단계로 되돌아가 다른 경로를 탐색하는 알고리즘 설계 기법입니다."},{"verdict":"정답","why":"Static Block은 자바 등에서 클래스 로딩 시 한 번 실행되는 정적 초기화 블록으로, 알고리즘 설계 기법이 아닙니다."}],"keywords":[{"term":"분할 정복(Divide and Conquer)","desc":"나누고, 풀고, 합친다(예: 합병 정렬, 퀵 정렬)"},{"term":"탐욕법(Greedy)","desc":"매 순간 최선의 선택"},{"term":"백트래킹(Backtracking)","desc":"막히면 되돌아가 다른 길 탐색"},{"term":"동적 계획법(Dynamic Programming)","desc":"작은 문제의 답을 저장해 재사용"}],"memo":"분·탐·백·동은 전략, Static Block은 자바 문법"}},{"id":"written-2026-1-23","no":23,"unit":"소프트웨어 개발","q":"N개의 정렬된 데이터를 처리할 때 \\(O(N\\log_2 N)\\)의 시간이 걸리는 정렬 알고리즘은?","choices":["합병 정렬","삽입 정렬","버블 정렬","선택 정렬"],"ans":1,"exp":{"concept":"시간 복잡도는 데이터 개수 N이 늘어날 때 처리 시간이 얼마나 늘어나는지를 나타냅니다. 합병 정렬(Merge Sort)은 데이터를 반씩 계속 나누고(약 log2 N 단계), 단계마다 N개를 합치므로 항상 O(N log2 N)이 걸립니다. 삽입·버블·선택 정렬은 평균과 최악에서 O(N²)이 걸립니다(이미 정렬된 데이터라면 삽입 정렬은 O(N)까지 줄어들지만 O(N log N)은 아닙니다).","choices":[{"verdict":"정답","why":"합병 정렬은 log2 N 단계로 나누고 각 단계에서 N번 비교·병합하므로 최선·평균·최악 모두 O(N log2 N)입니다."},{"verdict":"오답","why":"삽입 정렬은 평균·최악 O(N²)이고, 이미 정렬된 경우 최선 O(N)입니다."},{"verdict":"오답","why":"버블 정렬은 인접한 두 값을 비교·교환하며 평균·최악 O(N²)입니다."},{"verdict":"오답","why":"선택 정렬은 매 회전 최솟값을 찾아 교환하며 데이터 상태와 관계없이 항상 O(N²)입니다."}],"keywords":[{"term":"합병 정렬(Merge Sort)","desc":"나누어 정렬 후 병합, 항상 O(N log N)"},{"term":"퀵 정렬(Quick Sort)","desc":"피벗 기준 분할, 평균 O(N log N), 최악 O(N²)"},{"term":"힙 정렬(Heap Sort)","desc":"힙 트리 이용, 항상 O(N log N)"},{"term":"삽입·선택·버블 정렬","desc":"평균·최악 O(N²)"}],"memo":"N log N 삼총사 = 합병·힙·퀵(평균), 나머지 단순 정렬은 N²"}},{"id":"written-2026-1-24","no":24,"unit":"소프트웨어 개발","q":"스택(Stack)에 대한 설명으로 옳은 것만 나열한 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul class=\"is-labeled\"><li>ㄱ. FIFO 방식에 따라 처리된다.</li><li>ㄴ. 순서 리스트의 뒤(Rear)에서 노드가 삽입되고, 앞(Front)에서 노드가 제거된다.</li><li>ㄷ. 선형 리스트의 양쪽 끝에서 삽입과 삭제를 모두 할 수 있는 자료 구조이다.</li><li>ㄹ. 인터럽트 처리나 서브루틴 호출 작업 등에 응용된다.</li></ul></div>","choices":["㉠, ㉡, ㉢, ㉣","㉡, ㉢","㉠, ㉡","㉣"],"ans":4,"exp":{"concept":"스택(Stack)은 한쪽 끝(Top)에서만 넣고(Push) 빼는(Pop) 자료 구조로, 나중에 넣은 것이 먼저 나오는 LIFO(Last In First Out) 방식입니다. 접시를 쌓아 올렸다가 맨 위부터 꺼내는 것과 같습니다. 함수(서브루틴)를 호출하고 돌아올 주소 저장, 인터럽트 처리, 수식 계산, 재귀 호출 등에 쓰입니다.","choices":[{"verdict":"오답","why":"ㄱ(FIFO)은 큐의 특징, ㄴ(뒤에서 삽입·앞에서 삭제)도 큐의 특징, ㄷ(양쪽 끝 삽입·삭제)은 데크의 특징이므로 모두 옳다고 할 수 없습니다."},{"verdict":"오답","why":"ㄴ은 큐(Queue), ㄷ은 데크(Deque)에 대한 설명입니다."},{"verdict":"오답","why":"ㄱ의 FIFO와 ㄴ의 Rear 삽입·Front 삭제는 모두 큐(Queue)에 대한 설명입니다."},{"verdict":"정답","why":"스택에 대한 옳은 설명은 인터럽트 처리와 서브루틴 호출에 응용된다는 ㄹ뿐입니다."}],"keywords":[{"term":"스택(Stack)","desc":"LIFO, 한쪽(Top)에서만 삽입·삭제"},{"term":"큐(Queue)","desc":"FIFO, 뒤(Rear)에서 삽입·앞(Front)에서 삭제"},{"term":"데크(Deque)","desc":"양쪽 끝에서 삽입·삭제 모두 가능"},{"term":"스택의 응용","desc":"서브루틴 호출, 인터럽트 처리, 수식 계산, 재귀, 후위 표기법 변환"}],"memo":"스택은 접시 쌓기(LIFO), 큐는 줄 서기(FIFO)"}},{"id":"written-2026-1-25","no":25,"unit":"소프트웨어 개발","q":"하향식 통합 시험에서 일시적으로 필요한 조건만 갖추어 임시로 제공하는 시험용 모듈은 무엇인가?","choices":["Function","Stub","Driver","Procedure"],"ans":2,"exp":{"concept":"통합 테스트는 여러 모듈을 합쳐 가며 확인하는 테스트입니다. 하향식은 위 모듈부터 시작하므로 아직 안 만든 아래 모듈 대신 가짜 모듈인 스텁(Stub)을 씁니다. 상향식은 아래 모듈부터 시작하므로 위에서 호출해 줄 가짜 모듈인 드라이버(Driver)를 씁니다. 연극 연습 때 아직 오지 않은 배우 대신 대역을 세우는 것과 같습니다.","choices":[{"verdict":"오답","why":"Function(함수)은 특정 작업을 수행하는 코드 묶음일 뿐, 통합 테스트용 임시 모듈의 명칭이 아닙니다."},{"verdict":"정답","why":"하향식 통합 테스트에서 아직 개발되지 않은 하위 모듈을 대신해 필요한 조건만 갖춘 임시 모듈은 스텁(Stub)입니다."},{"verdict":"오답","why":"Driver(드라이버)는 상향식 통합 테스트에서 하위 모듈을 호출하고 결과를 받는 임시 상위 제어 모듈입니다."},{"verdict":"오답","why":"Procedure(프로시저)는 일련의 처리 절차를 묶은 코드(또는 DB의 저장 프로시저)로, 테스트용 임시 모듈이 아닙니다."}],"keywords":[{"term":"스텁(Stub)","desc":"하향식 통합에서 하위 모듈을 대신하는 임시 모듈"},{"term":"드라이버(Driver)","desc":"상향식 통합에서 상위 모듈을 대신하는 임시 제어 모듈"},{"term":"하향식 통합 테스트","desc":"상위 모듈부터 하위 모듈 방향으로 통합"},{"term":"상향식 통합 테스트","desc":"하위 모듈부터 상위 모듈 방향으로 통합, 클러스터 단위로 결합"}],"memo":"하향식-스텁(하스), 상향식-드라이버(상드)"}},{"id":"written-2026-1-26","no":26,"unit":"소프트웨어 개발","q":"검증 검사 기법 가운데 개발자의 장소에서 사용자가 개발자 앞에서 수행하는 기법으로, 일반적으로 통제된 환경에서 사용자와 개발자가 함께 확인하며 진행되는 검사는?","choices":["베타 검사","알파 검사","형상 검사","동치 분할 검사"],"ans":2,"exp":{"concept":"인수(검증) 테스트 중 알파 테스트와 베타 테스트는 장소와 개발자 동석 여부로 구분합니다. 알파 테스트는 개발자의 장소에서 사용자가 개발자 앞에서 통제된 환경으로 진행하고, 베타 테스트는 사용자의 실제 환경에서 개발자 없이 진행합니다. 알파는 공방에서 주인과 함께 시험 삼아 써 보는 것, 베타는 집에 가져가서 혼자 써 보는 것입니다.","choices":[{"verdict":"오답","why":"베타 검사는 실제 사용자 환경에서 개발자 없이 사용자가 수행하고 발견한 오류를 개발자에게 알려 주는 검사입니다."},{"verdict":"정답","why":"개발자 장소에서 사용자가 개발자 앞에서, 통제된 환경으로 함께 확인하며 진행하는 검사는 알파 검사입니다."},{"verdict":"오답","why":"형상 검사는 소프트웨어의 구성 요소, 목록, 유지보수에 필요한 사항이 빠짐없이 갖추어졌는지 확인하는 검사입니다."},{"verdict":"오답","why":"동치 분할 검사는 입력 조건을 유효·무효 그룹으로 나누어 대표값으로 테스트하는 블랙박스 테스트 기법입니다."}],"keywords":[{"term":"알파 테스트","desc":"개발자 장소, 개발자 앞에서, 통제된 환경"},{"term":"베타 테스트","desc":"사용자 장소, 개발자 없이, 실제 환경"},{"term":"인수 테스트","desc":"사용자 요구를 충족하는지 사용자가 확인하는 테스트"}],"memo":"알파는 개발자 앞에서(개발자 장소, 통제된 환경), 베타는 개발자 없이(사용자 장소, 실제 환경)"}},{"id":"written-2026-1-27","no":27,"unit":"소프트웨어 개발","q":"다음이 설명하는 클린 코드 작성 원칙은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>한 번에 한 가지 처리만 수행한다.</li><li>클래스/메소드/함수를 최소 단위로 분리한다.</li></ul></div>","choices":["다형성","단순성","의존성","추상화"],"ans":2,"exp":{"concept":"클린 코드(Clean Code)는 누구나 쉽게 읽고 고칠 수 있게 작성된 코드입니다. 작성 원칙으로 가독성, 단순성, 의존성 배제, 중복성 최소화, 추상화가 있습니다. 그중 단순성은 한 번에 한 가지 일만 하도록 하고 클래스·메소드·함수를 최소 단위로 나누는 것입니다. 서랍 하나에 한 종류 물건만 넣는 정리법과 같습니다.","choices":[{"verdict":"오답","why":"다형성은 같은 메시지에 객체마다 다르게 응답하는 객체지향 특성으로, 클린 코드 작성 원칙이 아닙니다."},{"verdict":"정답","why":"한 번에 한 가지 처리만 수행하고 클래스·메소드·함수를 최소 단위로 분리하는 것은 단순성 원칙입니다."},{"verdict":"오답","why":"의존성 배제는 코드 변경 시 다른 부분에 영향이 없도록 하고 예외 처리를 명확히 하는 원칙입니다."},{"verdict":"오답","why":"추상화는 상위 클래스·메소드·함수에서 간략하게 애플리케이션의 특성을 나타내고 세부 내용은 하위에서 구현하는 원칙입니다."}],"keywords":[{"term":"가독성","desc":"누구든지 읽기 쉽게, 이해하기 쉬운 용어·들여쓰기 사용"},{"term":"단순성","desc":"한 번에 한 가지 처리, 최소 단위로 분리"},{"term":"의존성 배제","desc":"변경이 다른 부분에 영향을 주지 않게 함"},{"term":"중복성 최소화","desc":"중복된 코드를 제거하고 공통 코드 사용"},{"term":"추상화","desc":"상위에서 특성만 간략히, 세부는 하위에서 구현"}],"memo":"클린 코드 5원칙 = 가·단·의·중·추"}},{"id":"written-2026-1-28","no":28,"unit":"소프트웨어 개발","q":"소프트웨어 품질 목표 가운데 쉽게 배워서 사용할 수 있는 정도를 의미하는 것은?","choices":["Usability","Integrity","Correctness","Reliability"],"ans":1,"exp":{"concept":"소프트웨어 품질 목표(품질 특성)는 좋은 소프트웨어가 갖춰야 할 성질들입니다. 사용 용이성(Usability)은 사용자가 쉽게 배우고 편하게 쓸 수 있는 정도입니다. 처음 산 스마트폰을 설명서 없이도 바로 쓸 수 있다면 사용 용이성이 높은 것입니다.","choices":[{"verdict":"정답","why":"Usability(사용 용이성)는 사용자가 소프트웨어를 쉽게 배우고 사용할 수 있는 정도입니다."},{"verdict":"오답","why":"Integrity(무결성)는 허용되지 않은 사용이나 자료 변경을 제어하는 정도입니다."},{"verdict":"오답","why":"Correctness(정확성)는 사용자의 요구 기능을 충족시키는 정도입니다."},{"verdict":"오답","why":"Reliability(신뢰성)는 정해진 조건에서 오류 없이 기능을 수행하는 정도입니다."}],"keywords":[{"term":"Usability(사용 용이성)","desc":"쉽게 배우고 사용할 수 있는 정도"},{"term":"Reliability(신뢰성)","desc":"오류 없이 기능을 수행하는 정도"},{"term":"Integrity(무결성)","desc":"허용되지 않은 접근·변경을 막는 정도"},{"term":"Correctness(정확성)","desc":"요구 기능을 충족하는 정도"},{"term":"Portability(이식성)","desc":"다른 환경에서도 쉽게 사용할 수 있는 정도"}],"memo":"Use(쓰다) + ability(능력) = 쓰기 쉬운 정도"}},{"id":"written-2026-1-29","no":29,"unit":"소프트웨어 개발","q":"인터페이스 구현 검증 도구 가운데 아래에서 설명하고 있는 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>서비스 호출, 컴포넌트 재사용 등 여러 환경을 지원하는 테스트 프레임워크</li><li>각 테스트 대상 분산 환경에 데몬을 사용해 테스트 대상 프로그램을 통해 테스트를 수행하고, 이를 통합하여 자동화하는 검증 도구</li></ul></div>","choices":["FitNesse","RubyNode","STAF","xUnit"],"ans":3,"exp":{"concept":"인터페이스 구현 검증 도구는 시스템끼리 잘 연결되는지 자동으로 시험해 보는 도구입니다. STAF(Software Testing Automation Framework)는 서비스 호출, 컴포넌트 재사용 등 다양한 환경을 지원하며, 테스트 대상 분산 환경마다 데몬을 두어 테스트를 수행하고 이를 통합해 자동화합니다. 여러 지점에 감독관(데몬)을 보내 동시에 시험을 치르게 하고 결과를 본사에서 모으는 방식입니다.","choices":[{"verdict":"오답","why":"FitNesse는 웹 기반으로 테스트 케이스를 설계·실행하고 결과를 확인할 수 있게 지원하는 테스트 프레임워크입니다."},{"verdict":"오답","why":"RubyNode는 출제기준의 인터페이스 구현 검증 도구 목록에 있는 도구가 아닙니다(Ruby 기반 웹 테스트 도구로는 watir가 있습니다)."},{"verdict":"정답","why":"분산 환경마다 데몬을 사용해 테스트를 수행하고 통합·자동화하는 검증 도구는 STAF입니다."},{"verdict":"오답","why":"xUnit은 JUnit, CppUnit, NUnit 등 다양한 언어를 지원하는 단위 테스트 프레임워크입니다."}],"keywords":[{"term":"xUnit","desc":"다양한 언어 지원 단위 테스트 프레임워크(JUnit 등)"},{"term":"STAF","desc":"분산 환경에 데몬을 두고 테스트를 통합·자동화"},{"term":"FitNesse","desc":"웹 기반 테스트 케이스 설계·실행·결과 확인"},{"term":"NTAF","desc":"FitNesse와 STAF의 장점을 통합한 NHN의 자동화 프레임워크"},{"term":"Selenium / watir","desc":"웹 애플리케이션 테스트 도구 / Ruby 기반 웹 테스트 도구"}],"memo":"데몬이 나오면 STAF, 데몬 STAFF(직원)가 지점마다 상주"}},{"id":"written-2026-1-30","no":30,"unit":"소프트웨어 개발","q":"n개의 노드를 가진 무방향 그래프에서 간선 수의 최댓값은?","choices":["n(n-1)/2","n(n+1)","n-1","n/2"],"ans":1,"exp":{"concept":"무방향 그래프에서 간선은 두 노드를 방향 없이 잇는 선이며, 같은 두 노드 사이에는 간선을 하나만 둘 수 있습니다(단순 그래프 기준). 그래서 간선의 최대 개수는 n개의 노드 중 2개를 고르는 경우의 수와 같습니다. 계산: nC2 = n × (n-1) ÷ 2. 예를 들어 노드가 4개면 4×3÷2 = 6개입니다. 반 학생 n명이 서로 한 번씩 악수하는 횟수와 같습니다.","choices":[{"verdict":"정답","why":"n개 노드에서 2개씩 짝짓는 경우의 수가 nC2 = n(n-1)/2이므로 무방향 그래프의 최대 간선 수입니다(예: n=4이면 6)."},{"verdict":"오답","why":"n(n+1)은 그래프 간선 수 공식이 아닙니다. 방향 그래프의 최대 간선 수는 n(n-1)입니다."},{"verdict":"오답","why":"n-1은 n개의 노드를 사이클 없이 모두 연결하는 트리(신장 트리)의 간선 수입니다."},{"verdict":"오답","why":"n/2는 그래프 간선 수의 최댓값과 관계없는 값입니다."}],"keywords":[{"term":"무방향 그래프 최대 간선 수","desc":"n(n-1)/2"},{"term":"방향 그래프 최대 간선 수","desc":"n(n-1)"},{"term":"트리의 간선 수","desc":"노드가 n개이면 간선은 n-1개"},{"term":"완전 그래프","desc":"모든 노드 쌍이 간선으로 연결된 그래프"}],"memo":"무방향은 악수(나누기 2), 방향은 편지 주고받기(나누기 없음)"}},{"id":"written-2026-1-31","no":31,"unit":"소프트웨어 개발","q":"소프트웨어 패키징 도구를 활용할 때 고려할 사항으로 옳지 않은 것은?","choices":["보안을 위해서는 이기종 연동을 고려하지 않아도 된다.","내부 콘텐츠에 대한 암호화와 보안은 반드시 고려한다.","제품 소프트웨어의 종류에 적합한 암호화 알고리즘을 적용한다.","사용자 편의성을 위해 복잡성과 비효율성 문제를 고려한다."],"ans":1,"exp":{"concept":"소프트웨어 패키징은 완성된 소프트웨어를 사용자가 설치·사용할 수 있게 묶는 작업이며, 패키징 도구는 이때 저작권 보호와 암호화를 함께 처리합니다. 고려할 점은 내부 콘텐츠 암호화와 보안, 다른 시스템(이기종)과의 연동, 사용자 편의성을 위한 복잡성·비효율성 문제, 제품 종류에 맞는 암호화 알고리즘 적용입니다. 선물을 포장할 때 잠금장치도 달고, 받는 사람이 쉽게 열 수 있는지도 챙기는 것과 같습니다.","choices":[{"verdict":"정답","why":"패키징 도구 활용 시 추가로 다양한 이기종 콘텐츠 및 단말기 간 DRM 연동을 반드시 고려해야 하므로 '이기종 연동을 고려하지 않아도 된다'는 옳지 않습니다."},{"verdict":"오답","why":"반드시 내부 콘텐츠에 대한 암호화 및 보안을 고려해야 하므로 옳은 설명입니다."},{"verdict":"오답","why":"제품 소프트웨어의 종류에 적합한 암호화 알고리즘을 적용해야 하므로 옳은 설명입니다."},{"verdict":"오답","why":"보안이 사용자 편의성을 해치지 않도록 복잡성과 비효율성 문제를 고려해야 하므로 옳은 설명입니다."}],"keywords":[{"term":"소프트웨어 패키징","desc":"모듈별 실행 파일을 묶어 배포용 설치 파일로 만드는 작업"},{"term":"패키징 도구","desc":"배포 시 저작권 보호를 위해 암호화·보안 기능을 제공"},{"term":"DRM(Digital Rights Management)","desc":"디지털 콘텐츠 저작권 관리 기술"}],"memo":"패키징 도구 고려사항 = 암호화·보안, 이기종 연동, 편의성, 맞춤 알고리즘"}},{"id":"written-2026-1-32","no":32,"unit":"소프트웨어 개발","q":"다음 설명에 해당하는 소프트웨어 테스트의 기본 원칙은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>파레토 법칙이 좌우한다.</li><li>애플리케이션 결함의 대부분은 소수의 특정 모듈에 집중되어 존재한다.</li><li>결함은 발생한 모듈에서 계속해서 추가로 발생할 가능성이 높다.</li></ul></div>","choices":["완벽한 테스팅은 불가능","결함 집중","오류 부재의 궤변","살충제 패러독스"],"ans":2,"exp":{"concept":"소프트웨어 테스트의 기본 원칙 중 결함 집중(Defect Clustering)은 결함의 대부분이 소수의 특정 모듈에 몰려 있다는 원칙입니다. 파레토 법칙(80 대 20 법칙)처럼 결함의 80%가 20%의 모듈에서 발견된다는 뜻입니다. 교실 청소를 할 때 쓰레기가 늘 특정 구석에 몰려 있는 것과 같습니다.","choices":[{"verdict":"오답","why":"완벽한 테스팅은 불가능 원칙은 모든 경우를 다 테스트할 수 없으므로 결함을 줄일 수는 있어도 완전히 없앨 수는 없다는 원칙입니다."},{"verdict":"정답","why":"파레토 법칙에 따라 결함의 대부분이 소수 모듈에 집중된다는 원칙은 결함 집중입니다."},{"verdict":"오답","why":"오류-부재의 궤변은 결함을 다 없애도 사용자의 요구사항을 충족하지 못하면 품질이 높다고 할 수 없다는 원칙입니다."},{"verdict":"오답","why":"살충제 패러독스는 같은 테스트 케이스를 반복하면 새로운 결함을 찾지 못하므로 테스트 케이스를 계속 보완해야 한다는 원칙입니다."}],"keywords":[{"term":"결함 집중(파레토 법칙)","desc":"결함의 대부분은 소수 모듈에 몰려 있음"},{"term":"살충제 패러독스","desc":"같은 테스트 반복 시 새 결함 발견 불가"},{"term":"오류-부재의 궤변","desc":"결함이 없어도 요구사항 미충족이면 무의미"},{"term":"정황(상황) 의존","desc":"소프트웨어 특징·환경에 따라 테스트를 다르게 수행"},{"term":"결함 존재 증명","desc":"테스트는 결함이 있음을 밝힐 뿐 없음을 증명하지 못함"}],"memo":"파레토 = 80:20 = 결함은 한곳에 몰린다(결함 집중)"}},{"id":"written-2026-1-33","no":33,"unit":"소프트웨어 개발","q":"인터페이스를 구현할 때 사용하는 기술 중 다음 내용에서 설명하는 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>JavaScript를 이용한 비동기 통신기술로서, 클라이언트와 서버 사이에 XML 데이터를 주고받는 기술</p></div>","choices":["Trigger","AJAX","Greedy","Procedure"],"ans":2,"exp":{"concept":"AJAX(Asynchronous JavaScript and XML)는 자바스크립트로 서버와 비동기 통신을 해서, 웹 페이지 전체를 새로고침하지 않고 필요한 데이터(XML, JSON 등)만 주고받는 기술입니다. 검색창에 글자를 칠 때마다 아래에 추천 검색어가 바로 뜨는 것이 대표적인 예입니다.","choices":[{"verdict":"오답","why":"Trigger(트리거)는 데이터베이스에 삽입·갱신·삭제 같은 이벤트가 생기면 자동으로 실행되는 SQL 프로그램입니다."},{"verdict":"정답","why":"JavaScript를 이용한 비동기 통신으로 클라이언트와 서버가 XML 데이터를 주고받는 기술은 AJAX입니다."},{"verdict":"오답","why":"Greedy(탐욕법)는 매 순간 최선의 선택을 하는 알고리즘 설계 기법입니다."},{"verdict":"오답","why":"Procedure(프로시저)는 자주 쓰는 SQL 작업을 하나로 묶어 저장해 두고 호출해 쓰는 프로그램입니다."}],"keywords":[{"term":"AJAX","desc":"JavaScript로 비동기 통신하여 XML 등 데이터를 교환"},{"term":"JSON","desc":"속성-값 쌍으로 데이터를 표현하는 개방형 표준 포맷"},{"term":"XML","desc":"사용자가 태그를 정의할 수 있는 마크업 언어"},{"term":"REST","desc":"HTTP 메서드로 자원을 주고받는 웹 아키텍처 스타일"}],"memo":"AJAX = A(비동기)+J(자바스크립트)+A+X(XML), 이름 자체가 정의"}},{"id":"written-2026-1-34","no":34,"unit":"소프트웨어 개발","q":"공학적으로 잘된 소프트웨어(Well Engineered Software)에 대한 설명으로 틀린 것은?","choices":["소프트웨어는 높은 신뢰성을 가져야 한다.","소프트웨어는 유지보수하기 쉬워야 한다.","소프트웨어는 사용자 수준과 무관하게 일관된 인터페이스를 제공해야 한다.","소프트웨어는 충분한 테스팅을 거쳐야만 한다."],"ans":3,"exp":{"concept":"공학적으로 잘된 소프트웨어(Well Engineered Software)는 신뢰성이 높고, 유지보수가 쉽고, 충분히 테스트되었으며, 사용자 수준에 맞는 적당한 인터페이스를 제공하는 소프트웨어입니다. 어린이용 앱과 전문가용 프로그램의 화면이 다른 것처럼, 사용자 수준을 고려해야 합니다.","choices":[{"verdict":"오답","why":"높은 신뢰성을 가져야 한다는 것은 잘된 소프트웨어의 조건이므로 옳은 설명입니다."},{"verdict":"오답","why":"유지보수가 쉬워야 한다는 것은 잘된 소프트웨어의 조건이므로 옳은 설명입니다."},{"verdict":"정답","why":"잘된 소프트웨어는 사용자 수준에 맞는 적당한 사용자 인터페이스를 제공해야 하므로, 사용자 수준과 무관하다는 것은 틀린 설명입니다."},{"verdict":"오답","why":"충분한 테스팅을 거쳐야 한다는 것은 잘된 소프트웨어의 조건이므로 옳은 설명입니다."}],"keywords":[{"term":"Well Engineered Software","desc":"신뢰성, 유지보수성, 충분한 테스트, 사용자 수준에 맞는 인터페이스, 효율성"},{"term":"사용자 인터페이스(UI)","desc":"사용자와 시스템이 상호작용하는 접점"},{"term":"신뢰성(Reliability)","desc":"오류 없이 기능을 수행하는 정도"}],"memo":"잘된 SW는 사용자 눈높이에 맞춘다, '무관하다'가 나오면 틀린 말"}},{"id":"written-2026-1-35","no":35,"unit":"소프트웨어 개발","q":"저작권 관리의 구성 요소 가운데 패키저(Packager)가 맡는 주요 역할로 옳은 것은?","choices":["콘텐츠를 제공하는 저작권자를 뜻한다.","라이선스를 발급하며 관리한다.","콘텐츠를 메타 데이터와 함께 배포할 수 있는 단위로 묶는다.","배포된 콘텐츠의 이용 권한을 통제하는 역할을 한다."],"ans":3,"exp":{"concept":"디지털 저작권 관리(DRM)는 콘텐츠가 허가된 사람에게만 정해진 방식으로 쓰이도록 하는 기술이며, 여러 구성 요소가 역할을 나눠 맡습니다. 그중 패키저(Packager)는 콘텐츠를 메타데이터와 함께 배포 가능한 단위로 묶는 역할을 합니다. 택배 상자에 물건과 송장(메타데이터)을 함께 넣어 포장하는 사람과 같습니다.","choices":[{"verdict":"오답","why":"콘텐츠를 제공하는 저작권자는 콘텐츠 제공자(Contents Provider)입니다."},{"verdict":"오답","why":"라이선스를 발급하고 관리하며 저작권 사용 권한과 정산을 다루는 것은 클리어링 하우스(Clearing House)입니다."},{"verdict":"정답","why":"패키저는 콘텐츠를 메타데이터와 함께 배포 가능한 형태로 묶어 암호화하는 프로그램입니다."},{"verdict":"오답","why":"배포된 콘텐츠의 이용 권한을 통제하는 것은 DRM 컨트롤러(DRM Controller)입니다."}],"keywords":[{"term":"클리어링 하우스(Clearing House)","desc":"저작권 사용 권한·라이선스 발급, 정산 관리"},{"term":"콘텐츠 제공자(Contents Provider)","desc":"콘텐츠를 제공하는 저작권자"},{"term":"패키저(Packager)","desc":"콘텐츠를 메타데이터와 함께 배포 단위로 묶음"},{"term":"콘텐츠 분배자(Contents Distributor)","desc":"암호화된 콘텐츠를 유통하는 곳(쇼핑몰 등)"},{"term":"DRM 컨트롤러 / 보안 컨테이너","desc":"배포된 콘텐츠 이용 권한 통제 / 콘텐츠를 안전하게 유통하는 보호 장치"}],"memo":"패키저 = 포장(Package)하는 사람, 물건+송장(메타데이터)"}},{"id":"written-2026-1-36","no":36,"unit":"소프트웨어 개발","q":"아래 초기 자료를 삽입 정렬(Insertion Sort)로 오름차순 정렬할 때, 1회전 후의 결과로 옳은 것은?<div class=\"q-spec\"><p>초기 자료 : 8, 3, 4, 9, 7</p></div>","choices":["3, 4, 8, 7, 9","3, 4, 9, 7, 8","7, 8, 3, 4, 9","3, 8, 4, 9, 7"],"ans":4,"exp":{"concept":"삽입 정렬(Insertion Sort)은 카드 게임에서 손에 든 카드를 정리하듯, 두 번째 원소부터 하나씩 꺼내 앞쪽의 이미 정렬된 부분에서 알맞은 자리를 찾아 끼워 넣는 방식입니다. 1회전에서는 두 번째 원소를 첫 번째 원소와 비교합니다. 계산: 초기 8, 3, 4, 9, 7에서 두 번째 값 3을 앞의 8과 비교하면 3 < 8이므로 8 앞에 삽입 → 3, 8, 4, 9, 7. 참고로 2회전은 4를 삽입해 3, 4, 8, 9, 7, 3회전은 9가 그대로라 3, 4, 8, 9, 7, 4회전은 7을 삽입해 3, 4, 7, 8, 9가 됩니다.","choices":[{"verdict":"오답","why":"3, 4, 8, 7, 9는 버블 정렬 1회전 결과입니다(8과 3 교환, 8과 4 교환, 8과 9 유지, 9와 7 교환). 삽입 정렬 1회전에서는 3만 이동합니다."},{"verdict":"오답","why":"3, 4, 9, 7, 8은 삽입 정렬 어느 회전의 결과와도 맞지 않습니다."},{"verdict":"오답","why":"7, 8, 3, 4, 9는 오름차순으로 정렬해 가는 과정에서 나올 수 없는 배열입니다."},{"verdict":"정답","why":"1회전에서 두 번째 값 3을 8과 비교해 앞으로 삽입하므로 3, 8, 4, 9, 7이 됩니다."}],"keywords":[{"term":"삽입 정렬(Insertion Sort)","desc":"앞의 정렬된 부분에 원소를 하나씩 끼워 넣음, 평균 O(n²)"},{"term":"선택 정렬(Selection Sort)","desc":"최솟값을 찾아 맨 앞과 교환"},{"term":"버블 정렬(Bubble Sort)","desc":"인접한 두 값을 비교·교환, 1회전마다 최댓값이 맨 뒤로"}],"memo":"삽입 = 카드 정리, 1회전은 두 번째 카드만 제자리 찾기"}},{"id":"written-2026-1-37","no":37,"unit":"소프트웨어 개발","q":"소프트웨어 형상 관리(Configuration Management)에 대한 설명 중 틀린 것은?","choices":["버전 제어 기술은 형상 관리의 기능 중 하나이다.","형상 관리를 위해 구성된 팀을 “chief programmer team”이라고 부른다.","소프트웨어에서 발생하는 수정이나 변경을 알아내어 제어하는 것을 의미한다.","소프트웨어 개발의 전체 비용을 줄이며, 개발 과정의 여러 방해 요인이 최소화되도록 보증하는 것을 목적으로 한다."],"ans":2,"exp":{"concept":"형상 관리(SCM, Software Configuration Management)는 소프트웨어 개발 중 생기는 수정과 변경을 알아내고 기록·통제하는 활동입니다. 형상 식별, 버전 제어, 형상 통제, 형상 감사, 형상 기록이 주요 기능이며, 변경으로 인한 혼란을 줄여 개발 비용을 줄이는 것이 목적입니다. 문서 파일을 '최종', '최최종'으로 저장하는 혼란을 체계적으로 막는 것이라고 보면 됩니다.","choices":[{"verdict":"오답","why":"버전 제어는 형상 관리의 기능 중 하나이므로 옳은 설명입니다."},{"verdict":"정답","why":"책임 프로그래머 팀(Chief Programmer Team)은 한 명의 책임 프로그래머를 중심으로 구성하는 개발 팀 구성 방식이며, 형상 관리 팀을 부르는 이름이 아니므로 틀린 설명입니다."},{"verdict":"오답","why":"소프트웨어에서 발생하는 수정·변경을 알아내고 제어하는 것이 형상 관리의 정의이므로 옳은 설명입니다."},{"verdict":"오답","why":"개발 전체 비용을 줄이고 개발 과정의 방해 요인을 최소화하도록 보증하는 것이 형상 관리의 목적이므로 옳은 설명입니다."}],"keywords":[{"term":"형상 관리(SCM)","desc":"개발 중 변경 사항을 관리·통제하는 활동"},{"term":"형상 관리 기능","desc":"형상 식별, 버전 제어, 형상 통제, 형상 감사, 형상 기록"},{"term":"형상 통제 위원회(CCB)","desc":"변경 요청을 검토·승인하는 조직"},{"term":"책임 프로그래머 팀","desc":"책임 프로그래머 중심의 개발 팀 구성 방식"}],"memo":"Chief Programmer Team은 팀 구성 방식, 형상 관리와 무관"}},{"id":"written-2026-1-38","no":38,"unit":"소프트웨어 개발","q":"다음 설명에 해당하는 용어로 옳은 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>소프트웨어 구조를 이루며, 다른 것들과 구별되는 독립적인 기능을 가진 단위이다.</li><li>하나 또는 몇 개의 논리적인 기능을 수행하기 위한 명령어들의 집합이라고 할 수도 있다.</li><li>서로 모여서 하나의 완전한 프로그램이 될 수 있다.</li></ul></div>","choices":["데이터","저장소","모듈","통합 프로그램"],"ans":3,"exp":{"concept":"모듈(Module)은 소프트웨어 구조를 이루는 독립적인 기능 단위입니다. 하나 또는 몇 개의 논리적 기능을 수행하는 명령어들의 묶음이며, 여러 모듈이 모여 하나의 완전한 프로그램이 됩니다. 조립식 가구의 각 부품(서랍, 선반)이 모여 가구 하나가 되는 것과 같습니다. 좋은 모듈은 응집도는 높고 결합도는 낮습니다.","choices":[{"verdict":"오답","why":"데이터는 처리 대상이 되는 값이나 정보로, 독립적 기능을 가진 명령어 집합이 아닙니다."},{"verdict":"오답","why":"저장소(Repository)는 데이터나 소스 코드 등을 보관하는 장소입니다."},{"verdict":"정답","why":"독립적 기능을 가진 소프트웨어 구조의 단위이자 논리적 기능을 수행하는 명령어 집합으로, 모여서 완전한 프로그램이 되는 것은 모듈입니다."},{"verdict":"오답","why":"통합 프로그램은 여러 모듈이 합쳐진 결과물로, 구성 단위 자체를 말하는 용어가 아닙니다."}],"keywords":[{"term":"모듈(Module)","desc":"독립적 기능을 가진 소프트웨어 구성 단위"},{"term":"모듈화(Modularity)","desc":"시스템을 모듈 단위로 나누는 것"},{"term":"응집도(Cohesion)","desc":"모듈 내부 요소들이 관련된 정도, 높을수록 좋음"},{"term":"결합도(Coupling)","desc":"모듈 사이의 의존 정도, 낮을수록 좋음"}],"memo":"모듈 = 조립식 부품, 모이면 완성품(프로그램)"}},{"id":"written-2026-1-39","no":39,"unit":"소프트웨어 개발","q":"블랙박스 테스트의 유형에 해당하지 않는 것은?","choices":["동등 분할 기법","조건, 루프 검사","오류 예측","경계값 분석"],"ans":2,"exp":{"concept":"블랙박스 테스트는 프로그램 내부를 보지 않고 입력과 출력만으로 기능이 맞는지 확인하는 테스트이고, 화이트박스 테스트는 내부 코드의 논리 구조(조건문, 반복문, 경로)를 들여다보며 확인하는 테스트입니다. 자판기에 돈을 넣고 음료가 나오는지만 보면 블랙박스, 자판기를 열어 내부 회로를 점검하면 화이트박스입니다.","choices":[{"verdict":"오답","why":"동등(동치) 분할 기법은 입력 자료를 유효·무효 그룹으로 나눠 대표값으로 테스트하는 블랙박스 기법입니다."},{"verdict":"정답","why":"조건 검사와 루프(반복문) 검사는 내부 논리 구조를 확인하는 화이트박스 테스트 기법이므로 블랙박스 유형이 아닙니다."},{"verdict":"오답","why":"오류 예측 기법은 과거 경험이나 감각으로 오류가 생길 만한 곳을 예측해 테스트하는 블랙박스 기법입니다."},{"verdict":"오답","why":"경계값 분석은 입력 조건의 경계 근처 값을 테스트하는 블랙박스 기법입니다."}],"keywords":[{"term":"블랙박스 테스트 기법","desc":"동치 분할, 경계값 분석, 원인-효과 그래프, 오류 예측, 비교 검사"},{"term":"화이트박스 테스트 기법","desc":"기초 경로 검사, 제어 구조 검사(조건·루프·데이터 흐름)"},{"term":"경계값 분석","desc":"경계값에서 오류가 많다는 점을 이용한 기법"}],"memo":"조건·루프·경로처럼 코드 속 구조 이름이 나오면 화이트박스"}},{"id":"written-2026-1-40","no":40,"unit":"소프트웨어 개발","q":"DBMS의 구성 요소 중 데이터베이스 성능에 많은 영향을 미치며, 테이블 및 클러스터에 연관되어 독립적인 저장 공간을 가지고, 데이터베이스에 저장된 자료를 보다 빠르게 조회하기 위해 사용되는 것은?","choices":["트랙잭션(Transaction)","인덱스(Index)","트리거(Trigger)","역정규화(Denormalization)"],"ans":2,"exp":{"concept":"인덱스(Index)는 데이터를 빨리 찾기 위해 키 값과 그 데이터의 위치(포인터)를 따로 모아 둔 구조입니다. 테이블이나 클러스터에 연결되지만 별도의 저장 공간을 가지며, 잘 만들면 조회 속도가 크게 빨라지므로 성능에 큰 영향을 줍니다. 두꺼운 책 맨 뒤의 '찾아보기'와 같습니다.","choices":[{"verdict":"오답","why":"트랜잭션(Transaction)은 데이터베이스의 상태를 바꾸는 하나의 논리적 작업 단위로, 저장 공간을 가진 조회용 구조가 아닙니다."},{"verdict":"정답","why":"테이블·클러스터에 연관되어 독립적 저장 공간을 갖고, 데이터를 빠르게 조회하기 위해 쓰는 것은 인덱스(Index)입니다."},{"verdict":"오답","why":"트리거(Trigger)는 삽입·갱신·삭제 같은 이벤트가 발생할 때 자동으로 실행되는 프로그램입니다."},{"verdict":"오답","why":"역정규화(Denormalization)는 성능 향상을 위해 정규화된 테이블을 일부러 통합·중복시키는 설계 기법으로, DBMS의 구성 요소가 아닙니다."}],"keywords":[{"term":"인덱스(Index)","desc":"키 값과 포인터로 빠른 조회를 돕는 구조"},{"term":"클러스터드 인덱스","desc":"인덱스 키 순서대로 데이터가 물리적으로 정렬"},{"term":"넌클러스터드 인덱스","desc":"데이터는 정렬되지 않고 인덱스만 따로 정렬"},{"term":"트리거(Trigger)","desc":"이벤트 발생 시 자동 실행되는 SQL 프로그램"}],"memo":"인덱스 = 책의 색인(찾아보기), 빨리 찾게 해 준다"}},{"id":"written-2026-1-41","no":41,"unit":"데이터베이스 구축","q":"학적 테이블에서 전화번호가 Null 값이 아닌 학생명을 모두 검색하려고 할 때, 옳은 SQL 구문은?","choices":["SELECT 학생명 FROM 학적 WHERE 전화번호 !=NOT NULL;","SELECT 학생명 FROM 학적 WHERE 전화번호 DON’T NULL;","SELECT 학생명 FROM 학적 WHERE 전화번호 IS NULL;","SELECT 학생명 FROM 학적 WHERE 전화번호 IS NOT NULL;"],"ans":4,"exp":{"concept":"SQL에서 NULL은 '값이 없음(모름)'을 뜻하는 특별한 표시라서 =, != 같은 비교 연산자로 비교할 수 없습니다(결과가 참도 거짓도 아닌 UNKNOWN이 됨). 그래서 NULL인지 확인할 때는 IS NULL, NULL이 아닌지 확인할 때는 IS NOT NULL을 씁니다. 빈칸인지 묻는 전용 질문법이 따로 있다고 생각하면 됩니다.","choices":[{"verdict":"오답","why":"'!= NOT NULL'은 SQL 문법에 없는 표현이며, NULL은 비교 연산자로 비교할 수 없습니다."},{"verdict":"오답","why":"'DON'T NULL'은 SQL에 존재하지 않는 키워드입니다."},{"verdict":"오답","why":"IS NULL은 전화번호가 NULL인 학생을 찾으므로 문제와 반대 결과를 냅니다."},{"verdict":"정답","why":"NULL이 아닌 값을 찾을 때는 IS NOT NULL을 사용하므로 WHERE 전화번호 IS NOT NULL이 옳습니다."}],"keywords":[{"term":"NULL","desc":"값이 없거나 알 수 없음을 나타내는 표시"},{"term":"IS NULL","desc":"값이 NULL인 행을 찾는 조건"},{"term":"IS NOT NULL","desc":"값이 NULL이 아닌 행을 찾는 조건"}],"memo":"NULL 앞에는 =가 아니라 IS, '아니다'면 IS NOT"}},{"id":"written-2026-1-42","no":42,"unit":"데이터베이스 구축","q":"분산 데이터베이스의 목표 가운데 “데이터베이스가 분산된 물리적 환경에서 특정 지역의 컴퓨터 시스템이나 네트워크에 장애가 발생하더라도 데이터 무결성이 보장된다.”는 설명과 관련 있는 것은?","choices":["병행 투명성","중복 투명성","위치 투명성","장애 투명성"],"ans":4,"exp":{"concept":"분산 데이터베이스는 데이터가 여러 지역 컴퓨터에 흩어져 있지만, 사용자는 한 곳에 있는 것처럼 쓸 수 있어야 합니다. 이를 위한 목표가 4가지 투명성(위치, 중복, 병행, 장애)입니다. 그중 장애 투명성은 어느 한 지역의 컴퓨터나 네트워크가 고장 나도 데이터 무결성이 보장되는 것입니다. 한 지점이 정전돼도 다른 지점에서 은행 업무가 정상 처리되는 것과 같습니다.","choices":[{"verdict":"오답","why":"병행 투명성은 여러 사용자가 동시에 트랜잭션을 수행해도 결과에 이상이 없도록 보장하는 것입니다."},{"verdict":"오답","why":"중복 투명성은 같은 데이터가 여러 곳에 중복 저장되어 있어도 사용자는 하나의 데이터처럼 사용하고 시스템이 자동으로 관리하는 것입니다."},{"verdict":"오답","why":"위치 투명성은 데이터의 물리적 위치를 몰라도 논리적인 이름만으로 접근할 수 있게 하는 것입니다."},{"verdict":"정답","why":"특정 지역의 시스템이나 네트워크에 장애가 생겨도 데이터 무결성이 보장되는 것은 장애 투명성입니다."}],"keywords":[{"term":"위치 투명성","desc":"데이터 위치를 몰라도 논리 이름으로 접근"},{"term":"중복 투명성","desc":"중복 저장돼도 하나처럼 사용"},{"term":"병행 투명성","desc":"동시 트랜잭션에도 결과 이상 없음"},{"term":"장애 투명성","desc":"장애가 나도 데이터 무결성 보장"}],"memo":"분산 투명성 = 위·중·병·장, '장애'라는 단어가 나오면 장애 투명성"}},{"id":"written-2026-1-43","no":43,"unit":"데이터베이스 구축","q":"기본키는 NULL 값을 가질 수 없고 릴레이션 내에 오직 하나의 값만 존재해야 한다는 조건을 다음 중 무엇이라 하는가?","choices":["속성 무결성 제약 조건","참조 무결성 제약 조건","도메인 무결성 제약 조건","개체 무결성 제약 조건"],"ans":4,"exp":{"concept":"무결성 제약 조건은 데이터베이스의 데이터가 정확하고 일관되도록 지키는 규칙입니다. 개체 무결성은 기본키를 이루는 속성이 NULL이 될 수 없고 값이 중복되지 않아 각 행을 유일하게 구분할 수 있어야 한다는 규칙입니다. 학생마다 학번이 반드시 있고, 같은 학번이 두 명일 수 없는 것과 같습니다.","choices":[{"verdict":"오답","why":"속성 무결성은 속성 값이 지정된 데이터 형식, NULL 허용 여부, 기본값 등 속성에 정한 조건을 만족해야 한다는 규칙입니다."},{"verdict":"오답","why":"참조 무결성은 외래키 값이 NULL이거나 참조하는 릴레이션의 기본키 값과 같아야 한다는 규칙입니다."},{"verdict":"오답","why":"도메인 무결성은 속성 값이 정의된 도메인(허용 범위)에 속한 값이어야 한다는 규칙입니다."},{"verdict":"정답","why":"기본키는 NULL을 가질 수 없고 릴레이션 안에서 중복 없이 유일해야 한다는 규칙은 개체 무결성 제약 조건입니다."}],"keywords":[{"term":"개체 무결성","desc":"기본키는 NULL 불가, 중복 불가"},{"term":"참조 무결성","desc":"외래키는 NULL이거나 참조 릴레이션의 기본키 값"},{"term":"도메인 무결성","desc":"속성 값은 정해진 도메인 범위 안의 값"},{"term":"사용자 정의 무결성","desc":"사용자가 정한 업무 규칙을 만족해야 함"}],"memo":"기본키 = 개체(Entity)의 신분증, 비어도 겹쳐도 안 된다"}},{"id":"written-2026-1-44","no":44,"unit":"데이터베이스 구축","q":"다음 중 SQL의 집계 함수(Aggregation Function)에 해당하지 않는 것은?","choices":["SUM","COUNT","AVG","CREATE"],"ans":4,"exp":{"concept":"집계 함수(그룹 함수)는 여러 행의 값을 모아 하나의 결과값을 계산하는 함수입니다. COUNT(개수), SUM(합계), AVG(평균), MAX(최댓값), MIN(최솟값), STDDEV(표준편차), VARIANCE(분산) 등이 있습니다. CREATE는 테이블 같은 객체를 만드는 DDL(데이터 정의어) 명령입니다. 반 전체 시험 점수로 평균이나 최고점을 구하는 것이 집계입니다.","choices":[{"verdict":"오답","why":"SUM은 그룹별 합계를 구하는 집계 함수입니다."},{"verdict":"오답","why":"COUNT는 그룹별 행의 개수를 구하는 집계 함수입니다."},{"verdict":"오답","why":"AVG는 그룹별 평균을 구하는 집계 함수입니다."},{"verdict":"정답","why":"CREATE는 스키마, 테이블, 뷰, 인덱스 등을 정의하는 DDL 명령으로 집계 함수가 아닙니다."}],"keywords":[{"term":"집계 함수","desc":"COUNT, SUM, AVG, MAX, MIN, STDDEV, VARIANCE"},{"term":"DDL(데이터 정의어)","desc":"CREATE, ALTER, DROP"},{"term":"DML(데이터 조작어)","desc":"SELECT, INSERT, UPDATE, DELETE"},{"term":"DCL(데이터 제어어)","desc":"GRANT, REVOKE, COMMIT, ROLLBACK"}],"memo":"집계는 숫자를 모아 계산, CREATE는 만드는 명령(DDL)"}},{"id":"written-2026-1-45","no":45,"unit":"데이터베이스 구축","q":"SQL 문의 SELECT에 관한 설명으로 옳지 않은 것은?","choices":["ORDER BY 절은 특정 속성을 기준으로 정렬해 검색할 때 사용한다.","FROM 절에는 질의로 검색될 데이터들이 포함된 테이블명을 기술한다.","검색결과에서 중복되는 레코드를 없애려면 WHERE 절에 ‘DISTINCT’ 키워드를 사용한다.","HAVING 절은 GROUP BY 절과 함께 사용하며, 그룹에 대한 조건을 지정한다."],"ans":3,"exp":{"concept":"SELECT 문은 SELECT(가져올 속성), FROM(대상 테이블), WHERE(행 조건), GROUP BY(그룹 묶기), HAVING(그룹 조건), ORDER BY(정렬) 절로 이루어집니다. 결과에서 중복된 행을 없애는 DISTINCT는 WHERE 절이 아니라 SELECT 바로 뒤에 씁니다. 예: SELECT DISTINCT 학과 FROM 학생;","choices":[{"verdict":"오답","why":"ORDER BY 절은 특정 속성을 기준으로 정렬하여 검색할 때 사용하므로 옳은 설명입니다(기본 ASC 오름차순, DESC 내림차순)."},{"verdict":"오답","why":"FROM 절에는 검색할 데이터가 들어 있는 테이블 이름을 쓰므로 옳은 설명입니다."},{"verdict":"정답","why":"중복 레코드를 없애는 DISTINCT는 WHERE 절이 아니라 SELECT 절(SELECT DISTINCT 속성명)에 쓰므로 옳지 않은 설명입니다."},{"verdict":"오답","why":"HAVING 절은 GROUP BY와 함께 쓰여 그룹에 대한 조건을 지정하므로 옳은 설명입니다."}],"keywords":[{"term":"DISTINCT","desc":"SELECT 절에서 중복 행 제거"},{"term":"WHERE","desc":"개별 행에 대한 검색 조건"},{"term":"GROUP BY / HAVING","desc":"그룹으로 묶기 / 그룹에 대한 조건"},{"term":"ORDER BY","desc":"정렬(ASC 오름차순, DESC 내림차순)"}],"memo":"DISTINCT는 SELECT에 딱 붙는다: SELECT DISTINCT"}},{"id":"written-2026-1-46","no":46,"unit":"데이터베이스 구축","q":"소프트웨어 개발 활동을 수행할 때 시스템에 고장(Failure)을 일으키며, 오류(Error)가 있을 경우 발생하는 것은?","choices":["Inspection","Testcase","Mistake","Fault"],"ans":4,"exp":{"concept":"소프트웨어 결함 용어는 원인과 결과의 순서로 이해합니다. 사람이 실수해서 생긴 오류(Error)가 코드나 산출물 안에 결함(Fault, Defect, 버그)으로 남고, 이 결함이 실행될 때 시스템이 기대와 다르게 동작하는 고장(Failure)이 일어납니다. 오류가 있으면 생기고 고장을 일으키는 중간 단계가 결함(Fault)입니다. 요리사의 실수(오류) 때문에 음식에 이물질(결함)이 들어가고, 손님이 탈이 나는 것(고장)과 같습니다.","choices":[{"verdict":"오답","why":"Inspection(인스펙션)은 작성자를 제외한 전문가가 산출물을 검사해 결함을 찾아내는 검토 기법입니다."},{"verdict":"오답","why":"Testcase(테스트 케이스)는 입력값, 실행 조건, 기대 결과로 구성된 테스트 항목 명세서입니다."},{"verdict":"오답","why":"Mistake(실수)는 결함을 만들어 내는 사람의 행위로, 오류(Error)의 원인에 해당하며 오류가 있을 때 결과로 생기는 것이 아닙니다."},{"verdict":"정답","why":"오류(Error)가 있을 경우 발생하고 시스템의 고장(Failure)을 일으키는 것은 결함(Fault)입니다."}],"keywords":[{"term":"오류(Error)","desc":"사람의 실수로 생긴 잘못"},{"term":"결함(Fault, Defect, Bug)","desc":"오류 때문에 산출물 안에 생긴 결점, 고장의 원인"},{"term":"고장(Failure)","desc":"결함이 실행되어 시스템이 기대와 다르게 동작하는 것"}],"memo":"오류 → 결함 → 고장 (E → F → F), 사람 실수가 버그가 되어 장애로"}},{"id":"written-2026-1-47","no":47,"unit":"데이터베이스 구축","q":"데이터베이스 설계 단계 가운데 물리적 설계에서 고려할 사항으로 적절하지 않은 것은?","choices":["저장 공간의 효율화","트랜잭션 처리량","응답 시간","스키마의 평가 및 정제"],"ans":4,"exp":{"concept":"데이터베이스 설계는 요구 분석 → 개념적 설계 → 논리적 설계 → 물리적 설계 → 구현 순서로 진행합니다. 물리적 설계는 실제 저장 장치에 어떻게 저장할지 정하는 단계라서 응답 시간, 저장 공간 효율화, 트랜잭션 처리량을 고려합니다. 스키마의 평가 및 정제는 특정 DBMS에 맞는 논리적 스키마를 만든 뒤 다듬는 논리적 설계 단계의 작업입니다.","choices":[{"verdict":"오답","why":"저장 공간의 효율화는 물리적 설계에서 고려하는 사항입니다."},{"verdict":"오답","why":"트랜잭션 처리량은 물리적 설계에서 고려하는 사항입니다."},{"verdict":"오답","why":"응답 시간은 물리적 설계에서 고려하는 사항입니다."},{"verdict":"정답","why":"스키마의 평가 및 정제는 논리적 설계 단계에서 수행하는 작업이므로 물리적 설계 고려사항이 아닙니다."}],"keywords":[{"term":"개념적 설계","desc":"E-R 다이어그램 작성, DBMS와 독립적인 개념 스키마"},{"term":"논리적 설계","desc":"특정 DBMS에 맞는 논리 스키마 설계, 정규화, 스키마 평가 및 정제"},{"term":"물리적 설계","desc":"저장 구조·접근 경로 설계, 응답 시간·저장 공간 효율·트랜잭션 처리량 고려"}],"memo":"물리 = 성능 3종(응답 시간·저장 공간·처리량), 스키마 다듬기는 논리"}},{"id":"written-2026-1-48","no":48,"unit":"데이터베이스 구축","q":"정규화 과정에서 1NF가 2NF로 되기 위한 조건은?","choices":["1NF를 만족하며 모든 도메인이 원자값이어야 한다.","1NF를 만족하며, 키가 아닌 모든 애트리뷰트들이 기본키에 이행적으로 함수 종속되지 않아야 한다.","1NF를 만족하며 다치 종속이 제거되어야 한다.","1NF를 만족하며 키가 아닌 모든 속성이 기본키에 대하여 완전 함수적 종속 관계를 만족해야 한다 ."],"ans":4,"exp":{"concept":"정규화는 데이터 중복과 이상 현상을 줄이려고 테이블을 단계적으로 나누는 과정입니다. 1NF는 모든 도메인이 원자값, 2NF는 1NF이면서 부분 함수 종속을 제거해 기본키가 아닌 모든 속성이 기본키 전체에 완전 함수 종속, 3NF는 이행적 함수 종속 제거, BCNF는 결정자가 모두 후보키, 4NF는 다치 종속 제거, 5NF는 조인 종속 제거입니다. 예를 들어 (학번, 과목코드)가 기본키인데 학생 이름이 학번에만 종속되면 부분 종속이라 2NF가 아닙니다.","choices":[{"verdict":"오답","why":"모든 도메인이 원자값이어야 한다는 것은 1NF 자체의 조건입니다."},{"verdict":"오답","why":"기본키에 이행적 함수 종속되지 않아야 한다는 것은 2NF에서 3NF로 가는 조건입니다."},{"verdict":"오답","why":"다치 종속 제거는 BCNF에서 4NF로 가는 조건입니다."},{"verdict":"정답","why":"1NF에서 부분 함수 종속을 제거하여 키가 아닌 모든 속성이 기본키에 완전 함수 종속되면 2NF가 됩니다."}],"keywords":[{"term":"1NF","desc":"모든 도메인이 원자값"},{"term":"2NF","desc":"부분 함수 종속 제거(완전 함수 종속)"},{"term":"3NF","desc":"이행적 함수 종속 제거"},{"term":"BCNF","desc":"결정자이면서 후보키가 아닌 것 제거"},{"term":"4NF / 5NF","desc":"다치 종속 제거 / 조인 종속 제거"}],"memo":"도부이결다조 (원자값·부분·이행·결정자·다치·조인)"}},{"id":"written-2026-1-49","no":49,"unit":"데이터베이스 구축","q":"뷰(VIEW)에 관한 설명 중 옳지 않은 것은?","choices":["뷰의 정의는 기본 테이블처럼 ALTER문을 이용해 변경한다.","뷰가 정의된 기본 테이블이 제거되면 뷰 역시 자동적으로 제거된다.","뷰를 조작할 때 삽입, 갱신, 삭제 연산에는 제약이 따른다.","뷰 위에 다른 뷰를 또 정의할 수 있다."],"ans":1,"exp":{"concept":"뷰(View)는 실제 데이터를 저장하지 않고, 기본 테이블에서 원하는 부분을 골라 보여 주는 가상 테이블입니다. 뷰는 한번 정의하면 ALTER 문으로 바꿀 수 없어서, 바꾸려면 DROP으로 지우고 CREATE로 다시 만들어야 합니다. 원본 사진 위에 올려 둔 투명 필름(창문)과 같아서, 원본(기본 테이블)이 없어지면 뷰도 의미를 잃습니다.","choices":[{"verdict":"정답","why":"뷰는 ALTER 문으로 정의를 변경할 수 없고, 삭제(DROP) 후 다시 생성(CREATE)해야 하므로 옳지 않은 설명입니다."},{"verdict":"오답","why":"뷰가 정의된 기본 테이블이나 뷰가 삭제되면 그것을 기초로 정의된 뷰도 함께 삭제되므로 옳은 설명입니다."},{"verdict":"오답","why":"뷰는 가상 테이블이라 삽입·갱신·삭제 연산에 제약이 따르므로 옳은 설명입니다."},{"verdict":"오답","why":"이미 만든 뷰를 바탕으로 또 다른 뷰를 정의할 수 있으므로 옳은 설명입니다."}],"keywords":[{"term":"뷰(View)","desc":"기본 테이블에서 유도된 가상 테이블"},{"term":"뷰의 장점","desc":"논리적 데이터 독립성, 보안(필요한 데이터만 노출), 질의 단순화"},{"term":"뷰의 단점","desc":"ALTER로 변경 불가, 삽입·갱신·삭제 제약, 독자적 인덱스 불가"}],"memo":"뷰는 고칠(ALTER) 수 없다, 지우고(DROP) 다시 만든다(CREATE)"}},{"id":"written-2026-1-50","no":50,"unit":"데이터베이스 구축","q":"병렬 데이터베이스 환경의 수평 분할에서 사용되는 분할 기법에 해당하지 않는 것은?","choices":["범위 분할","예측 분할","라운드-로빈","해시 분할"],"ans":2,"exp":{"concept":"병렬 데이터베이스에서 수평 분할은 테이블의 행(레코드)들을 여러 디스크나 노드에 나누어 저장하는 것입니다. 나누는 기준에 따라 라운드-로빈(차례대로 돌아가며 배치), 범위 분할(값의 범위별로 배치), 해시 분할(해시 함수 결과로 배치)이 있습니다. 카드를 사람들에게 한 장씩 돌려 나누면 라운드-로빈, 번호 구간별로 나누면 범위 분할입니다.","choices":[{"verdict":"오답","why":"범위 분할(Range Partitioning)은 지정한 열 값의 범위에 따라 행을 나누는 수평 분할 기법입니다."},{"verdict":"정답","why":"예측 분할은 수평 분할 기법에 해당하지 않는, 존재하지 않는 기법입니다."},{"verdict":"오답","why":"라운드-로빈(Round-Robin)은 행을 각 분할 영역에 차례대로 돌아가며 고르게 배치하는 수평 분할 기법입니다."},{"verdict":"오답","why":"해시 분할(Hash Partitioning)은 해시 함수 결과값에 따라 행을 나누는 수평 분할 기법입니다."}],"keywords":[{"term":"수평 분할","desc":"행(레코드) 단위로 테이블을 나눔"},{"term":"수직 분할","desc":"열(속성) 단위로 테이블을 나눔"},{"term":"라운드-로빈 분할","desc":"차례대로 돌아가며 고르게 배치"},{"term":"범위 분할","desc":"값의 범위에 따라 배치"},{"term":"해시 분할","desc":"해시 함수 값에 따라 배치"}],"memo":"수평 분할 3총사 = 라·범·해(라운드-로빈·범위·해시)"}},{"id":"written-2026-1-51","no":51,"unit":"데이터베이스 구축","q":"학생 테이블을 만든 뒤 성별 필드가 빠진 것을 발견하여 이를 추가하고자 한다. 이때 사용하기에 알맞은 SQL 명령어는?","choices":["INSERT","DROP","MODIFY","ALTER"],"ans":4,"exp":{"concept":"이미 만들어진 테이블의 구조(열 추가, 열 변경, 열 삭제)를 바꿀 때는 데이터 정의어(DDL, Data Definition Language)인 ALTER를 쓴다. 성별 열을 추가하려면 ALTER TABLE 학생 ADD 성별 CHAR(1); 처럼 쓴다. 집으로 치면 데이터(가구)를 들이는 것이 아니라 방(구조)을 하나 더 만드는 공사다.","choices":[{"verdict":"오답","why":"INSERT는 데이터 조작어(DML)로, 테이블에 새 행(튜플)을 넣는 명령이다. 테이블 구조에 열을 추가하지는 못한다."},{"verdict":"오답","why":"DROP은 테이블, 뷰 같은 객체 자체를 삭제하는 DDL 명령이다. 열을 추가하는 용도가 아니다."},{"verdict":"오답","why":"MODIFY는 독립된 SQL 명령어가 아니라 일부 DBMS(Oracle, MySQL)에서 ALTER TABLE ... MODIFY 형태로 기존 열의 정의를 바꿀 때 쓰는 절이다. 새 열 추가와는 다르다."},{"verdict":"정답","why":"ALTER TABLE 학생 ADD 성별 ... 처럼 ALTER는 기존 테이블의 구조를 변경(열 추가, 수정, 삭제)하는 DDL 명령이다."}],"keywords":[{"term":"DDL(Data Definition Language)","desc":"CREATE, ALTER, DROP, TRUNCATE 등 구조를 정의, 변경, 삭제하는 언어"},{"term":"ALTER TABLE ... ADD","desc":"기존 테이블에 새 열을 추가"},{"term":"DML(Data Manipulation Language)","desc":"SELECT, INSERT, UPDATE, DELETE 등 데이터를 다루는 언어"}],"memo":"구조를 바꾸면 ALTER(바꾸다), 데이터를 넣으면 INSERT."}},{"id":"written-2026-1-52","no":52,"unit":"데이터베이스 구축","q":"관계 데이터 모델에서 릴레이션(relation)에 대한 설명으로 옳은 것은?","choices":["릴레이션의 각 행을 스키마(Schema)라 하는데, 예를 들어 도서 릴레이션을 구성하는 스키마에는 도서번호, 도서명, 저자, 가격 등이 있다.","도메인(Domain)은 하나의 속성이 가질 수 있는 같은 타입의 모든 값의 집합이며, 각 속성의 도메인은 원자값을 갖는다.","릴레이션의 각 열을 튜플(Tuple)이라 하는데, 하나의 튜플은 각 속성에서 정의된 값을 이용해 구성된다.","속성(Attribute)은 한 개의 릴레이션의 논리적인 구조를 정의한 것으로서 릴레이션의 이름과 릴레이션에 포함된 속성들의 집합을 뜻한다."],"ans":2,"exp":{"concept":"릴레이션은 행과 열로 된 표다. 행 하나를 튜플(Tuple), 열 하나를 속성(Attribute), 한 속성이 가질 수 있는 값 전체의 집합을 도메인(Domain), 릴레이션의 이름과 속성들의 구조 정의를 스키마(Schema)라고 한다. 예를 들어 성별 속성의 도메인은 {남, 여}이다.","choices":[{"verdict":"오답","why":"릴레이션의 각 행은 튜플이다. 도서번호, 도서명처럼 구조를 정의한 것은 스키마가 맞지만 '각 행을 스키마라 한다'는 설명이 틀렸다."},{"verdict":"정답","why":"도메인은 하나의 속성이 취할 수 있는 같은 타입의 원자값들의 집합이라는 표준 정의와 일치한다."},{"verdict":"오답","why":"릴레이션의 각 열은 속성(Attribute)이고, 튜플은 각 행이다. 행과 열을 바꿔 설명했다."},{"verdict":"오답","why":"릴레이션 이름과 속성들의 집합으로 논리적 구조를 정의한 것은 스키마(릴레이션 스키마)에 대한 설명이다. 속성은 릴레이션의 각 열(이름을 가진 항목)이다."}],"keywords":[{"term":"튜플(Tuple)","desc":"릴레이션의 행, 튜플 수 = 카디널리티(Cardinality)"},{"term":"속성(Attribute)","desc":"릴레이션의 열, 속성 수 = 차수(Degree)"},{"term":"도메인(Domain)","desc":"한 속성이 가질 수 있는 원자값들의 집합"},{"term":"릴레이션 스키마(Schema)","desc":"릴레이션 이름 + 속성 이름들로 된 구조 정의"}],"memo":"행은 튜플, 열은 속성, 값의 범위는 도메인, 틀은 스키마."}},{"id":"written-2026-1-53","no":53,"unit":"데이터베이스 구축","q":"어떤 릴레이션 R에서 X와 Y가 각각 R의 애트리뷰트 집합의 부분 집합일 때, 애트리뷰트 X의 각 값에 대하여 시간과 무관하게 항상 애트리뷰트 Y의 값이 오직 하나만 연관되어 있으면 Y는 X에 함수 종속이라고 한다. 이러한 함수 종속의 표기로 옳은 것은?","choices":["X ⊂ Y","Y → X","X → Y","Y ⊂ X"],"ans":3,"exp":{"concept":"함수 종속은 X 값이 정해지면 Y 값이 항상 하나로 정해지는 관계다. 이때 X를 결정자, Y를 종속자라 하고 X → Y로 쓰며 'Y는 X에 함수 종속'이라고 읽는다. 예를 들어 학번을 알면 이름이 하나로 정해지므로 학번 → 이름이다.","choices":[{"verdict":"오답","why":"X ⊂ Y는 X가 Y의 부분집합이라는 집합 관계 표기이지 함수 종속 표기가 아니다."},{"verdict":"오답","why":"Y → X는 Y가 X를 결정한다는 뜻(X가 Y에 함수 종속)으로 방향이 반대다."},{"verdict":"정답","why":"X의 값이 Y의 값을 유일하게 결정하므로 결정자 X를 왼쪽에 두어 X → Y로 표기한다."},{"verdict":"오답","why":"Y ⊂ X는 Y가 X의 부분집합이라는 집합 관계 표기다. 참고로 Y ⊆ X이면 X → Y는 자명한 함수 종속이지만, 표기 자체는 함수 종속을 나타내지 않는다."}],"keywords":[{"term":"결정자(Determinant)","desc":"화살표 왼쪽, 값을 결정하는 속성 X"},{"term":"종속자(Dependent)","desc":"화살표 오른쪽, 결정되는 속성 Y"},{"term":"완전/부분/이행 함수 종속","desc":"정규화 단계마다 제거하는 종속의 종류"}],"memo":"화살표는 '정해 주는 쪽 → 정해지는 쪽', 학번 → 이름."}},{"id":"written-2026-1-54","no":54,"unit":"데이터베이스 구축","q":"데이터웨어하우스에서 기본적으로 제공하는 OLAP(On-Line Analytical Processing) 연산에 해당하지 않는 것은?","choices":["Dicing","Roll-Up","Drill-Down","Translate"],"ans":4,"exp":{"concept":"OLAP(On-Line Analytical Processing)은 데이터 웨어하우스의 다차원 데이터를 사용자가 여러 관점에서 분석하도록 돕는 기술이다. 기본 연산으로 Roll-up(요약), Drill-down(상세화), Drill-through, Drill-across, Pivot(축 회전), Slice(한 차원 고정해 자르기), Dice(여러 차원 범위로 잘라 부분 큐브 만들기)가 있다. 지도 앱에서 축소하면 Roll-up, 확대하면 Drill-down이라고 생각하면 쉽다.","choices":[{"verdict":"오답","why":"Dicing은 여러 차원의 범위를 지정해 큐브의 일부(부분 큐브)를 잘라 보는 OLAP 연산이다."},{"verdict":"오답","why":"Roll-Up은 상세 데이터를 상위 수준으로 묶어 요약하는 OLAP 연산이다(예: 일별 → 월별)."},{"verdict":"오답","why":"Drill-Down은 요약 데이터를 더 상세한 수준으로 내려가 보는 OLAP 연산이다(예: 연도별 → 분기별)."},{"verdict":"정답","why":"Translate(번역, 변환)는 OLAP 연산에 해당하지 않는다."}],"keywords":[{"term":"Roll-up / Drill-down","desc":"요약 방향 / 상세 방향으로 분석 수준 이동"},{"term":"Slicing / Dicing","desc":"한 차원 값을 고정해 자르기 / 여러 차원 범위로 부분 큐브 추출"},{"term":"Pivoting","desc":"분석 축(차원)의 방향을 바꿔 보기"},{"term":"데이터 웨어하우스(DW)","desc":"의사결정 지원을 위해 통합, 정리된 대용량 데이터 저장소"}],"memo":"OLAP 연산은 '롤드슬다피(Roll, Drill, Slice, Dice, Pivot)', Translate는 없다."}},{"id":"written-2026-1-55","no":55,"unit":"데이터베이스 구축","q":"병행제어의 로킹(Locking) 단위에 관한 설명 중 옳지 않은 것은?","choices":["한꺼번에 로킹할 수 있는 단위를 로킹 단위라 한다.","로킹 단위가 작아질수록 병행성 수준은 낮아진다.","로킹 단위가 작아질수록 로킹 오버헤드는 증가한다.","데이터베이스, 파일, 레코드 등이 로킹 단위가 될 수 있다."],"ans":2,"exp":{"concept":"로킹(Locking)은 여러 트랜잭션이 같은 데이터를 동시에 바꾸지 못하도록 잠그는 병행제어 기법이다. 잠그는 단위가 작을수록(레코드, 필드) 서로 다른 부분을 동시에 쓸 수 있어 병행성은 높아지지만 관리할 잠금이 많아져 오버헤드가 커진다. 단위가 클수록(데이터베이스, 파일) 그 반대다. 도서관 전체를 잠그는 것보다 책 한 권만 잠그면 더 많은 사람이 동시에 이용할 수 있는 것과 같다.","choices":[{"verdict":"오답","why":"한 번에 로킹할 수 있는 데이터의 크기를 로킹 단위라고 하므로 옳은 설명이다."},{"verdict":"정답","why":"로킹 단위가 작아질수록 병행성(동시에 처리할 수 있는 정도)은 높아진다. '낮아진다'는 반대로 쓴 틀린 설명이다."},{"verdict":"오답","why":"단위가 작으면 잠가야 할 대상 수가 많아져 로크 관리 오버헤드가 증가하므로 옳은 설명이다."},{"verdict":"오답","why":"데이터베이스, 파일, 레코드, 필드 등이 모두 로킹 단위가 될 수 있으므로 옳은 설명이다."}],"keywords":[{"term":"로킹 단위 작음","desc":"병행성 높음, 오버헤드 큼, 관리 복잡"},{"term":"로킹 단위 큼","desc":"병행성 낮음, 오버헤드 작음, 관리 단순"},{"term":"2단계 로킹(2PL)","desc":"확장 단계와 축소 단계로 나눠 직렬성을 보장하는 로킹 규약"}],"memo":"작게 잠그면 많이 동시에(병행성 업), 대신 잠금 관리비(오버헤드)도 업."}},{"id":"written-2026-1-56","no":56,"unit":"데이터베이스 구축","q":"데이터 제어어(DCL)에 관한 설명 중 옳은 것은?","choices":["COMMIT : 데이터베이스 사용자의 사용 권한을 취소하는 명령이다.","ROLLBACK : 데이터의 보안 및 무결성을 정의한다.","GRANT : 데이터베이스 사용자에게 사용 권한을 부여한다.","REVOKE : 데이터베이스 조작 작업이 비정상적으로 종료된 경우 원래 상태로 복구한다."],"ans":3,"exp":{"concept":"데이터 제어어(DCL, Data Control Language)는 데이터의 보안, 무결성, 회복, 병행 제어를 위해 쓰는 명령이다. 권한 부여는 GRANT, 권한 회수는 REVOKE이며, 정보처리기사에서는 트랜잭션 제어 명령인 COMMIT(작업 확정)과 ROLLBACK(작업 취소)도 DCL에 함께 묶어 다룬다.","choices":[{"verdict":"오답","why":"COMMIT은 트랜잭션의 작업 결과를 데이터베이스에 영구적으로 반영(확정)하는 명령이다. 권한을 취소하는 명령은 REVOKE다."},{"verdict":"오답","why":"ROLLBACK은 트랜잭션이 비정상 종료되었을 때 수행 전 상태로 되돌리는 명령이다. 보안 및 무결성을 정의한다는 것은 DCL 전체의 목적에 대한 설명이다."},{"verdict":"정답","why":"GRANT는 사용자에게 테이블 등에 대한 사용 권한(SELECT, INSERT 등)을 부여하는 명령이다."},{"verdict":"오답","why":"REVOKE는 부여했던 사용 권한을 취소(회수)하는 명령이다. 비정상 종료 시 원래 상태로 복구하는 것은 ROLLBACK이다."}],"keywords":[{"term":"GRANT","desc":"권한 부여: GRANT 권한 ON 객체 TO 사용자"},{"term":"REVOKE","desc":"권한 회수: REVOKE 권한 ON 객체 FROM 사용자"},{"term":"COMMIT","desc":"트랜잭션 결과를 영구 반영"},{"term":"ROLLBACK","desc":"트랜잭션을 수행 전 상태로 되돌림"}],"memo":"그랜트(Grant)는 '준다', 리보크(Revoke)는 '뺏는다', 커밋은 '확정', 롤백은 '되감기'."}},{"id":"written-2026-1-57","no":57,"unit":"데이터베이스 구축","q":"데이터가 중복됨으로 인해 관계 연산을 처리할 때 예기치 못한 곤란한 현상이 나타나는 것을 무엇이라고 하는가?","choices":["변환(Translation)","이상(Anomaly)","제한(Restriction)","종속성(Dependency)"],"ans":2,"exp":{"concept":"이상(Anomaly)은 정규화가 덜 된 테이블에서 데이터 중복 때문에 삽입, 삭제, 갱신 시 생기는 곤란한 현상이다. 삽입 이상(원하지 않는 값까지 넣어야 함), 삭제 이상(지우면 필요한 정보까지 사라짐), 갱신 이상(중복된 값 중 일부만 바뀌어 불일치)이 있다. 같은 주소를 여러 장부에 적어 두면 이사할 때 한 장부만 고쳐 서로 달라지는 것이 갱신 이상이다.","choices":[{"verdict":"오답","why":"변환(Translation)은 이상 현상을 가리키는 용어가 아니다."},{"verdict":"정답","why":"데이터 중복으로 인해 삽입, 삭제, 갱신 시 예기치 못한 문제가 생기는 현상을 이상(Anomaly)이라 한다."},{"verdict":"오답","why":"제한(Restriction)은 관계 대수에서 조건에 맞는 튜플을 고르는 Select 연산의 다른 이름으로 쓰이며, 이상 현상과는 무관하다."},{"verdict":"오답","why":"종속성(Dependency)은 속성 간 함수 종속 등 결정 관계를 뜻한다. 이상의 원인이 될 수는 있지만 현상 자체의 이름은 아니다."}],"keywords":[{"term":"삽입 이상","desc":"데이터를 넣을 때 원치 않는 값도 함께 넣어야 하는 문제"},{"term":"삭제 이상","desc":"한 튜플을 지울 때 필요한 정보까지 연쇄 삭제되는 문제"},{"term":"갱신 이상","desc":"중복 데이터 중 일부만 수정되어 정보가 불일치하는 문제"},{"term":"정규화(Normalization)","desc":"이상을 없애기 위해 릴레이션을 분해하는 과정"}],"memo":"이상은 '삽삭갱' 세 가지, 해결책은 정규화."}},{"id":"written-2026-1-58","no":58,"unit":"데이터베이스 구축","q":"다음 두 릴레이션 R과 S에 대해 Division 연산을 수행한 결과는?<div class=\"q-spec\"><span class=\"q-spec__label\">보기</span><div class=\"q-tbl-title\">R</div><table class=\"q-tbl is-data\"><thead><tr><th>D1</th><th>D2</th><th>D3</th></tr></thead><tbody><tr><td>a</td><td>1</td><td>A</td></tr><tr><td>b</td><td>1</td><td>A</td></tr><tr><td>c</td><td>2</td><td>A</td></tr><tr><td>d</td><td>2</td><td>B</td></tr></tbody></table><div class=\"q-tbl-title\">S</div><table class=\"q-tbl is-data\"><thead><tr><th>D2</th><th>D3</th></tr></thead><tbody><tr><td>1</td><td>A</td></tr></tbody></table></div>","choices":["<table class=\"q-tbl is-data is-center\"><thead><tr><th>D2</th></tr></thead><tbody><tr><td>2</td></tr><tr><td>2</td></tr></tbody></table>","<table class=\"q-tbl is-data is-center\"><thead><tr><th>D3</th></tr></thead><tbody><tr><td>A</td></tr></tbody></table>","<table class=\"q-tbl is-data is-center\"><thead><tr><th>D1</th></tr></thead><tbody><tr><td>a</td></tr><tr><td>b</td></tr></tbody></table>","<table class=\"q-tbl is-data is-center\"><thead><tr><th>D3</th></tr></thead><tbody><tr><td>A</td></tr><tr><td>B</td></tr></tbody></table>"],"ans":3,"exp":{"concept":"Division(÷) 연산은 R ÷ S에서 S의 모든 튜플과 짝을 이루는 R의 나머지 속성 값만 골라내는 관계 대수 연산이다. 결과에는 S에 없는 R의 속성(여기서는 D1)만 남는다. 계산: S는 (D2=1, D3=A) 한 개이므로 R에서 (D2=1, D3=A)를 가진 튜플을 찾으면 (a,1,A), (b,1,A)이고, 이들의 D1 값 a, b가 결과다. (c,2,A)는 D2가 2, (d,2,B)는 D2와 D3가 모두 달라 제외된다.","choices":[{"verdict":"오답","why":"결과 속성은 S에 없는 R의 속성인 D1이어야 한다. D2는 나누는 S의 속성이므로 결과에 남지 않는다."},{"verdict":"오답","why":"D3도 S의 속성이므로 결과에 남지 않는다. 결과는 D1 열이다."},{"verdict":"정답","why":"S의 튜플 (1, A)와 모두 짝을 이루는 R의 D1 값은 a와 b이므로 결과는 D1 = {a, b}다."},{"verdict":"오답","why":"D3 = {A, B}는 R의 D3 열 값을 모아 놓은 것일 뿐 Division 결과가 아니다."}],"keywords":[{"term":"Division(÷)","desc":"S의 모든 튜플과 관련된 R의 튜플을 골라 S의 속성을 뺀 결과를 반환"},{"term":"Select(σ)","desc":"조건에 맞는 행을 고르는 연산"},{"term":"Project(π)","desc":"원하는 열만 골라내는 연산"},{"term":"Join(⋈)","desc":"공통 속성으로 두 릴레이션을 합치는 연산"}],"memo":"나누기 결과에는 '나누는 쪽(S)의 열'이 사라지고 남은 열만 남는다."}},{"id":"written-2026-1-59","no":59,"unit":"데이터베이스 구축","q":"다음 설명에 해당하는 트랜잭션의 특징은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>트랜잭션의 연산은 전부 실행되거나, 전혀 실행되지 않아야 한다.</p></div>","choices":["Atomicity","Durability","Consistency","Isolation"],"ans":1,"exp":{"concept":"트랜잭션은 데이터베이스에서 한 번에 처리되어야 하는 작업 묶음이며 ACID 특성을 가져야 한다. 원자성(Atomicity)은 모두 실행되거나 전혀 실행되지 않아야 한다(All or Nothing)는 성질이다. 계좌 이체에서 출금만 되고 입금이 안 되는 일이 없어야 하는 것이 원자성이다.","choices":[{"verdict":"정답","why":"원자성(Atomicity)은 트랜잭션의 연산이 전부 반영되거나 전혀 반영되지 않아야 한다는 특성이다."},{"verdict":"오답","why":"지속성(Durability)은 성공적으로 완료(COMMIT)된 트랜잭션의 결과가 시스템 장애가 나도 영구히 보존되어야 한다는 특성이다."},{"verdict":"오답","why":"일관성(Consistency)은 트랜잭션 수행 전후에 데이터베이스가 항상 일관된(무결성 제약을 만족하는) 상태여야 한다는 특성이다."},{"verdict":"오답","why":"독립성 또는 격리성(Isolation)은 동시에 실행되는 트랜잭션이 서로의 중간 결과에 끼어들 수 없어야 한다는 특성이다."}],"keywords":[{"term":"Atomicity(원자성)","desc":"All or Nothing, COMMIT/ROLLBACK으로 보장"},{"term":"Consistency(일관성)","desc":"수행 전후 일관된 상태 유지"},{"term":"Isolation(독립성)","desc":"동시 실행 트랜잭션끼리 간섭 금지"},{"term":"Durability(지속성)","desc":"완료된 결과는 영구 반영"}],"memo":"ACID: 원자는 쪼갤 수 없다 = 전부 아니면 전무."}},{"id":"written-2026-1-60","no":60,"unit":"데이터베이스 구축","q":"정규화 과정에서 함수 종속이 A → B, B → C일 때 성립하는 A → C의 관계를 제거하는 단계는 무엇인가?","choices":["1NF → 2NF","2NF → 3NF","3NF → BCNF","BCNF → 4NF"],"ans":2,"exp":{"concept":"A → B이고 B → C이면 A → C가 성립하는데, 이처럼 중간 속성을 거쳐 결정되는 종속을 이행적 함수 종속이라고 한다. 이행적 함수 종속을 제거하는 단계가 2NF에서 3NF로 가는 과정이다. 학번 → 학과, 학과 → 학과장이면 학번 → 학과장이 이행 종속이며, 학과 테이블을 따로 떼어 내 해결한다.","choices":[{"verdict":"오답","why":"1NF → 2NF는 기본키의 일부에만 종속되는 부분 함수 종속을 제거하는 단계다."},{"verdict":"정답","why":"2NF → 3NF는 A → B, B → C에 따른 A → C 같은 이행적 함수 종속을 제거하는 단계다."},{"verdict":"오답","why":"3NF → BCNF는 결정자이면서 후보키가 아닌 것을 제거하는 단계다(모든 결정자가 후보키가 되도록)."},{"verdict":"오답","why":"BCNF → 4NF는 다치(다중 값) 종속을 제거하는 단계다."}],"keywords":[{"term":"1NF","desc":"모든 도메인이 원자값"},{"term":"2NF","desc":"부분 함수 종속 제거"},{"term":"3NF","desc":"이행적 함수 종속 제거"},{"term":"BCNF","desc":"결정자이면서 후보키가 아닌 것 제거"},{"term":"4NF / 5NF","desc":"다치 종속 제거 / 조인 종속 제거"}],"memo":"'도부이결다조': 도메인 원자값, 부분, 이행, 결정자, 다치, 조인 순으로 제거."}},{"id":"written-2026-1-61","no":61,"unit":"프로그래밍 언어 활용","q":"UDP 프로토콜의 특징으로 볼 수 없는 것은?","choices":["주로 주소를 지정하며, 경로를 설정하는 기능을 수행한다.","헤더 구조가 단순하여 오버헤드가 적다.","비연결형 서비스를 제공하는 프로토콜이다.","TCP와 마찬가지로 트랜스포트 계층에 존재한다."],"ans":1,"exp":{"concept":"UDP(User Datagram Protocol)는 전송 계층 프로토콜로, 연결 설정 없이 데이터를 보내는 비연결형 방식이다. 흐름 제어, 순서 보장, 재전송이 없어 신뢰성은 낮지만 헤더가 8바이트로 단순해 빠르므로 실시간 스트리밍, DNS 조회 등에 쓰인다. 주소 지정과 경로 설정(라우팅)은 네트워크 계층의 IP가 하는 일이다.","choices":[{"verdict":"정답","why":"주소 지정과 경로 설정(라우팅)은 네트워크 계층 프로토콜인 IP의 기능이다. UDP는 포트 번호로 응용 프로그램을 구분해 줄 뿐 경로를 설정하지 않는다."},{"verdict":"오답","why":"UDP 헤더는 출발지 포트, 목적지 포트, 길이, 체크섬의 8바이트로 단순해 오버헤드가 적다. UDP의 특징이 맞다."},{"verdict":"오답","why":"UDP는 연결 설정 과정 없이 데이터그램을 보내는 비연결형 서비스를 제공한다. UDP의 특징이 맞다."},{"verdict":"오답","why":"UDP는 TCP와 함께 OSI 4계층인 전송(트랜스포트) 계층에 속한다. UDP의 특징이 맞다."}],"keywords":[{"term":"TCP","desc":"연결형, 신뢰성 보장(순서, 흐름, 오류 제어), 3-way handshake"},{"term":"UDP","desc":"비연결형, 신뢰성 낮음, 빠름, 헤더 8바이트"},{"term":"IP","desc":"네트워크 계층, 주소 지정과 라우팅 담당"}],"memo":"길 찾기(라우팅)는 IP, 빠른 배달(비연결)은 UDP, 꼼꼼한 배달은 TCP."}},{"id":"written-2026-1-62","no":62,"unit":"프로그래밍 언어 활용","q":"다음 중 가장 높은 응집도에 해당하는 것은?","choices":["절차적 응집도","논리적 응집도","우연적 응집도","순차적 응집도"],"ans":4,"exp":{"concept":"응집도(Cohesion)는 한 모듈 안의 구성 요소들이 얼마나 하나의 목적을 위해 뭉쳐 있는지를 나타내며 높을수록 좋다. 강한 것부터 기능적 > 순차적 > 교환적(통신적) > 절차적 > 시간적 > 논리적 > 우연적 순이다. 보기 중에는 순차적 응집도가 가장 높다.","choices":[{"verdict":"오답","why":"절차적 응집도는 모듈 내 요소들이 정해진 순서로 실행되어야 하는 관계로 묶인 경우로, 순차적, 교환적 응집도보다 낮다."},{"verdict":"오답","why":"논리적 응집도는 유사한 성격의 처리들을 한 모듈에 모아 두고 선택해 실행하는 경우로, 우연적 바로 위의 낮은 단계다."},{"verdict":"오답","why":"우연적 응집도는 서로 관련 없는 요소들이 우연히 한 모듈에 모인 경우로, 가장 낮은 응집도다."},{"verdict":"정답","why":"순차적 응집도는 한 요소의 출력이 다음 요소의 입력으로 쓰이는 관계로, 기능적 응집도 다음으로 높아 보기 중 가장 높다."}],"keywords":[{"term":"기능적 응집도","desc":"모든 요소가 단일 기능을 위해 수행, 가장 강함"},{"term":"교환적(통신적) 응집도","desc":"같은 입력이나 출력을 사용하는 요소들의 모임"},{"term":"시간적 응집도","desc":"특정 시점에 함께 처리되는 요소들의 모임(예: 초기화)"},{"term":"결합도(Coupling)","desc":"모듈 간 의존 정도, 낮을수록 좋음"}],"memo":"응집도 강한 순 '기순교절시논우(기능, 순차, 교환, 절차, 시간, 논리, 우연)'."}},{"id":"written-2026-1-63","no":63,"unit":"프로그래밍 언어 활용","q":"다음 중 프로세스에 관한 설명으로 틀린 것은?","choices":["PCB를 가지며, PCB에는 프로세스의 현재상태와 고유식별자가 들어 있다.","프로세스는 비동기적 행위를 일으키는 주체에 해당한다.","프로세서가 할당되는 실체이며, 디스패치가 가능한 단위이다.","프로세스는 스레드 내의 작업단위를 뜻하며, 경량 스레드라고도 불린다."],"ans":4,"exp":{"concept":"프로세스는 실행 중인 프로그램으로, 운영체제가 CPU를 할당하는 단위이며 PCB(Process Control Block)에 상태, 식별자 등의 정보를 담아 관리한다. 스레드(Thread)는 프로세스 안에서 실행되는 더 작은 작업 단위로, 자원을 공유해 가볍기 때문에 경량 프로세스(LWP, Light Weight Process)라고 부른다. 프로세스가 공장이라면 스레드는 그 안의 작업자다.","choices":[{"verdict":"오답","why":"프로세스는 PCB를 가지며, PCB에는 프로세스 식별자(PID), 현재 상태, 레지스터 정보 등이 저장되므로 옳은 설명이다."},{"verdict":"오답","why":"프로세스는 비동기적 행위를 일으키는 주체라는 것이 프로세스의 표준 정의 중 하나이므로 옳은 설명이다."},{"verdict":"오답","why":"프로세스는 프로세서(CPU)가 할당되는 실체이며 디스패치(준비 상태에서 실행 상태로 전환)가 가능한 단위이므로 옳은 설명이다."},{"verdict":"정답","why":"관계가 거꾸로 되었다. 스레드가 프로세스 내의 작업 단위이고, 스레드를 경량 프로세스라고 부른다."}],"keywords":[{"term":"PCB(Process Control Block)","desc":"프로세스의 상태, PID, 레지스터, 메모리 정보 등을 담은 자료구조"},{"term":"스레드(Thread)","desc":"프로세스 내 실행 단위, 경량 프로세스"},{"term":"디스패치(Dispatch)","desc":"준비 상태의 프로세스에 CPU를 할당해 실행 상태로 바꾸는 것"}],"memo":"프로세스 안에 스레드가 있다: 큰 집(프로세스) 안의 방(스레드)."}},{"id":"written-2026-1-64","no":64,"unit":"프로그래밍 언어 활용","q":"OSI 7계층 가운데 다음 설명에 해당하는 계층은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>개방 시스템 간의 네트워크 연결을 관리하는 기능과 데이터의 교환 및 중계 기능을 수행함</li><li>네트워크 연결을 설정하고 유지하며 해제하는 기능을 수행함</li></ul></div>","choices":["네트워크 계층","표현 계층","전송 계층","데이터 링크 계층"],"ans":1,"exp":{"concept":"OSI 7계층의 네트워크 계층(3계층)은 서로 다른 네트워크에 있는 시스템 간 연결을 관리하고, 패킷의 경로 설정(라우팅)과 데이터 교환 및 중계를 담당한다. 네트워크 연결을 설정, 유지, 해제하는 것도 이 계층의 역할이며 대표 프로토콜은 IP, 장비는 라우터다.","choices":[{"verdict":"정답","why":"개방 시스템 간 네트워크 연결 관리, 데이터 교환 및 중계, 네트워크 연결 설정, 유지, 해제는 네트워크 계층의 기능이다."},{"verdict":"오답","why":"표현 계층(6계층)은 데이터의 형식 변환, 암호화, 압축 등 표현 방식을 다루는 계층이다."},{"verdict":"오답","why":"전송 계층(4계층)은 종단 간(End-to-End) 신뢰성 있는 데이터 전송, 흐름 제어, 오류 제어를 담당한다(TCP, UDP)."},{"verdict":"오답","why":"데이터 링크 계층(2계층)은 인접한 두 노드 사이의 신뢰성 있는 전송을 위해 프레임 단위로 동기화, 오류 제어, 흐름 제어를 한다."}],"keywords":[{"term":"네트워크 계층","desc":"3계층, 라우팅, 패킷, IP, 라우터"},{"term":"전송 계층","desc":"4계층, 종단 간 신뢰성, 세그먼트, TCP/UDP"},{"term":"데이터 링크 계층","desc":"2계층, 인접 노드 간 전송, 프레임, 스위치"}],"memo":"'중계, 경로'가 보이면 네트워크 계층(라우터)."}},{"id":"written-2026-1-65","no":65,"unit":"프로그래밍 언어 활용","q":"UNIX에서 새로운 프로세스를 생성할 때 사용하는 명령어는?","choices":["ls","cat","chmod","fork"],"ans":4,"exp":{"concept":"UNIX에서 새로운 프로세스는 fork를 호출해 만든다. fork는 현재 프로세스(부모)를 복제해 자식 프로세스를 생성하는 시스템 호출이며, 시험에서는 프로세스 생성 명령으로 출제된다. 나머지 ls, cat, chmod는 파일을 다루는 명령어다.","choices":[{"verdict":"오답","why":"ls는 현재 디렉터리의 파일 목록을 보여 주는 명령어다."},{"verdict":"오답","why":"cat은 파일 내용을 화면에 출력하거나 여러 파일을 이어 붙이는 명령어다."},{"verdict":"오답","why":"chmod는 파일이나 디렉터리의 접근 권한(읽기, 쓰기, 실행)을 변경하는 명령어다."},{"verdict":"정답","why":"fork는 부모 프로세스를 복제해 새로운 자식 프로세스를 생성한다."}],"keywords":[{"term":"fork","desc":"새 프로세스(자식) 생성"},{"term":"exec","desc":"현재 프로세스를 다른 프로그램으로 교체해 실행"},{"term":"kill","desc":"프로세스 종료(시그널 전송)"},{"term":"ps","desc":"현재 실행 중인 프로세스 상태 확인"}],"memo":"포크(fork)로 길이 갈라지듯 프로세스가 부모, 자식 둘로 갈라진다."}},{"id":"written-2026-1-66","no":66,"unit":"프로그래밍 언어 활용","q":"다음 JAVA 프로그램을 실행했을 때 출력되는 결과는?<pre class=\"qcode\"><code class=\"language-java\">public class Operator {\n    public static void main(String[ ] args) {\n        int x=5, y=0, z=0;\n        y = x++;\n        z = --x;\n        System.out.print(x + \", \" + y +\", \" +z);\n    }\n}</code></pre>","choices":["5, 5, 5","5, 6, 5","6, 5, 5","5, 6, 4"],"ans":1,"exp":{"concept":"후위 증가 x++는 현재 값을 먼저 쓰고 나중에 1을 더하고, 전위 감소 --x는 먼저 1을 뺀 뒤 그 값을 쓴다. 계산: 처음 x=5. y = x++ 에서 y에 5가 들어간 뒤 x는 6이 된다. z = --x 에서 x가 먼저 5가 되고 z에 5가 들어간다. 따라서 x=5, y=5, z=5이고 출력은 '5, 5, 5'다.","choices":[{"verdict":"정답","why":"y = x++ 로 y=5, x=6이 되고, z = --x 로 x=5, z=5가 되므로 '5, 5, 5'가 출력된다."},{"verdict":"오답","why":"y를 6으로 본 것은 x++를 전위 증가처럼 계산한 실수다. 후위 증가는 증가 전 값 5를 대입한다."},{"verdict":"오답","why":"x를 6으로 본 것은 --x로 다시 1이 감소된 것을 빠뜨린 실수다. 최종 x는 5다."},{"verdict":"오답","why":"y를 6, z를 4로 본 것은 x++와 --x를 모두 잘못 계산한 결과다. 실제로는 y=5, z=5다."}],"keywords":[{"term":"후위 연산(x++, x--)","desc":"값을 먼저 사용하고 나중에 증감"},{"term":"전위 연산(++x, --x)","desc":"먼저 증감하고 그 값을 사용"},{"term":"문자열 연결(+)","desc":"Java에서 숫자 + 문자열은 문자열로 이어 붙임"}],"memo":"기호가 뒤에 있으면 '쓰고 나서' 바꾸고, 앞에 있으면 '바꾸고 나서' 쓴다."}},{"id":"written-2026-1-67","no":67,"unit":"프로그래밍 언어 활용","q":"프로세스 적재 정책에 관한 설명 중 틀린 것은?","choices":["반복, 스택, 부프로그램은 시간 지역성(Temporal Locality)과 관련된다.","스레싱(Thrashing) 현상을 방지하려면 각 프로세스가 필요로 하는 프레임을 제공할 수 있어야 한다.","공간 지역성(Spatial Locality)은 프로세스가 어떤 페이지를 참조했다면 그 이후 가상주소 공간상 해당 페이지와 인접한 페이지들을 참조할 가능성이 높다는 것을 의미한다.","일반적으로 프로세스 수행에 보내는 시간이 페이지 교환에 보내는 시간보다 더 크면 스레싱(Thrashing)이 발생한다."],"ans":4,"exp":{"concept":"지역성(Locality)은 프로세스가 실행 중 일부 페이지만 집중적으로 참조하는 성질로, 시간 지역성(최근 참조한 곳을 곧 다시 참조: 반복문, 스택, 부프로그램, 카운터)과 공간 지역성(참조한 곳 근처를 참조: 배열 순회, 순차 코드)이 있다. 스레싱(Thrashing)은 페이지 부재가 너무 자주 일어나 실제 프로세스 실행보다 페이지 교환에 더 많은 시간을 쓰는 현상이다. 공부 시간보다 책을 꺼냈다 넣었다 하는 시간이 더 긴 상태라고 보면 된다.","choices":[{"verdict":"오답","why":"반복(Loop), 스택, 부프로그램(Subroutine), 카운터, 집계 변수는 대표적인 시간 지역성의 예이므로 옳은 설명이다."},{"verdict":"오답","why":"각 프로세스가 필요로 하는 만큼의 프레임(워킹 셋)을 제공하면 페이지 부재가 줄어 스레싱을 막을 수 있으므로 옳은 설명이다."},{"verdict":"오답","why":"공간 지역성은 참조한 위치와 인접한 위치(페이지)를 이어서 참조할 가능성이 높다는 의미이므로 옳은 설명이다."},{"verdict":"정답","why":"스레싱은 페이지 교환에 보내는 시간이 프로세스 수행 시간보다 더 클 때 발생한다. 보기는 크기 관계를 반대로 썼다."}],"keywords":[{"term":"스레싱(Thrashing)","desc":"페이지 교환 시간 > 실행 시간이 되어 CPU 이용률이 급감하는 현상"},{"term":"워킹 셋(Working Set)","desc":"일정 시간 동안 자주 참조하는 페이지 집합, 스레싱 방지에 활용"},{"term":"시간 지역성","desc":"반복, 스택, 부프로그램, 카운터"},{"term":"공간 지역성","desc":"배열 순회, 순차적 코드 실행"}],"memo":"스레싱 = 일(실행)보다 짐 옮기기(페이지 교환)가 더 많은 상태."}},{"id":"written-2026-1-68","no":68,"unit":"프로그래밍 언어 활용","q":"다음 C언어 프로그램을 실행한 결과는?<pre class=\"qcode\"><code class=\"language-c\">#include &lt;stdio.h&gt;\nmain( ) {\n    int sum = 0;\n    for (int i = 0; i &lt;= 10; i++) {\n        if (i % 2 == 0)\n            continue;\n        sum = sum + i;\n    }\n    printf(\"%d\", sum);\n}</code></pre>","choices":["20","25","30","55"],"ans":2,"exp":{"concept":"continue는 반복문의 남은 부분을 건너뛰고 다음 반복으로 넘어가게 한다. 이 코드는 i가 짝수(i % 2 == 0)이면 건너뛰므로 0부터 10까지 중 홀수만 더한다. 계산: 1 + 3 + 5 + 7 + 9 = 25.","choices":[{"verdict":"오답","why":"20은 짝수만 일부 더하거나 계산을 잘못한 값이다. 실제로는 홀수 1, 3, 5, 7, 9를 더해 25다."},{"verdict":"정답","why":"짝수는 continue로 건너뛰고 홀수 1, 3, 5, 7, 9만 더하므로 1+3+5+7+9 = 25가 출력된다."},{"verdict":"오답","why":"30은 짝수 0, 2, 4, 6, 8, 10을 모두 더한 값이다. 이 코드는 짝수를 건너뛴다."},{"verdict":"오답","why":"55는 0부터 10까지 모두 더한 값으로, continue 조건을 무시한 결과다."}],"keywords":[{"term":"continue","desc":"남은 문장을 건너뛰고 다음 반복으로 이동"},{"term":"break","desc":"반복문(또는 switch)을 즉시 빠져나감"},{"term":"% (나머지 연산자)","desc":"i % 2 == 0이면 짝수"}],"memo":"continue는 '이번 판 패스', break는 '게임 끝'."}},{"id":"written-2026-1-69","no":69,"unit":"프로그래밍 언어 활용","q":"OSI 7계층 중 물리적 연결을 이용하여 신뢰성 있는 정보를 전송하기 위해 동기화, 오류 제어, 흐름 제어 등의 전송 에러를 제어하는 계층은?","choices":["물리 계층","데이터 링크 계층","표현 계층","응용 계층"],"ans":2,"exp":{"concept":"데이터 링크 계층(2계층)은 물리 계층이 만든 물리적 연결 위에서 인접한 두 장치 사이에 신뢰성 있는 정보를 전송하는 계층이다. 프레임 단위로 데이터를 보내며 동기화, 오류 제어, 흐름 제어를 수행한다. 대표 프로토콜은 HDLC, PPP, 이더넷이고 장비는 스위치, 브리지다.","choices":[{"verdict":"오답","why":"물리 계층(1계층)은 전기적, 기계적 특성을 이용해 비트를 전송 매체로 실어 나르는 계층으로, 오류 제어나 흐름 제어를 하지 않는다."},{"verdict":"정답","why":"물리적 연결을 이용해 신뢰성 있는 전송을 위해 동기화, 오류 제어, 흐름 제어를 하는 계층은 데이터 링크 계층이다."},{"verdict":"오답","why":"표현 계층(6계층)은 코드 변환, 암호화, 압축 등 데이터 표현 형식을 다룬다."},{"verdict":"오답","why":"응용 계층(7계층)은 사용자가 네트워크 서비스(HTTP, FTP, SMTP 등)를 이용할 수 있게 하는 계층이다."}],"keywords":[{"term":"데이터 링크 계층","desc":"프레임, 동기화, 오류/흐름 제어, HDLC, 스위치"},{"term":"물리 계층","desc":"비트 전송, 케이블, 허브, 리피터"},{"term":"OSI 7계층 순서","desc":"물리, 데이터 링크, 네트워크, 전송, 세션, 표현, 응용"}],"memo":"OSI 아래부터 '물데네전세표응', 물리 연결 바로 위에서 오류를 잡는 건 데이터 링크."}},{"id":"written-2026-1-70","no":70,"unit":"프로그래밍 언어 활용","q":"C언어의 연산자 중 산술 연산자에 해당하지 않는 것은?","choices":["&lt;&lt;","/","%","*"],"ans":1,"exp":{"concept":"C언어의 산술 연산자는 +, -, *, /, % 이다. <<와 >>는 비트를 왼쪽이나 오른쪽으로 이동시키는 시프트 연산자로, 비트 연산자에 속한다. 예를 들어 3 << 1은 비트를 한 칸 왼쪽으로 밀어 6이 된다.","choices":[{"verdict":"정답","why":"<<는 왼쪽 시프트(Shift) 연산자로 비트 연산자에 속하며 산술 연산자가 아니다."},{"verdict":"오답","why":"/는 나눗셈 산술 연산자다(정수끼리는 몫만 구함)."},{"verdict":"오답","why":"%는 나머지를 구하는 산술 연산자다."},{"verdict":"오답","why":"*는 곱셈 산술 연산자다."}],"keywords":[{"term":"산술 연산자","desc":"+, -, *, /, %"},{"term":"비트 연산자","desc":"&, |, ^, ~, <<, >>"},{"term":"관계 연산자","desc":"==, !=, >, <, >=, <="}],"memo":"화살표 두 개(<<, >>)는 비트를 미는 시프트, 계산기 버튼에 있는 건 산술."}},{"id":"written-2026-1-71","no":71,"unit":"프로그래밍 언어 활용","q":"아래 C언어 프로그램을 실행하고 ‘c’를 입력했을 때의 출력 결과는?<pre class=\"qcode\"><code class=\"language-c\">#include &lt;stdio.h&gt;\nmain() {\n    char ch;\n    scanf(\"%c\", &amp;ch);\n    switch (ch) {\n    case 'a':\n        printf(\"one \");\n    case 'b':\n        printf(\"two \");\n    case 'c':\n        printf(\"three \");\n        break;\n    case 'd':\n        printf(\"four \");\n        break;\n    }\n}</code></pre>","choices":["one two","one two three four","one","three"],"ans":4,"exp":{"concept":"switch 문은 일치하는 case로 바로 이동해 실행하며, break를 만나기 전까지는 아래 case들도 이어서 실행한다(폴스루, Fall-through). 'c'를 입력하면 case 'c'로 이동해 'three '를 출력하고, 바로 뒤에 break가 있으므로 switch를 빠져나간다. 그래서 출력은 'three'다.","choices":[{"verdict":"오답","why":"'one two'는 'a'를 입력했을 때 출력의 앞부분일 뿐이며, 'c' 입력 시에는 case 'a', 'b'를 거치지 않는다."},{"verdict":"오답","why":"'one two three four'는 모든 case를 다 실행한 경우로, case 'c' 뒤의 break 때문에 이런 출력은 나올 수 없다."},{"verdict":"오답","why":"'one'은 case 'a'의 출력이다. 'c'를 입력하면 case 'a'는 실행되지 않는다."},{"verdict":"정답","why":"case 'c'에서 'three '를 출력하고 break로 종료하므로 'three'가 출력된다."}],"keywords":[{"term":"switch-case","desc":"식의 값과 일치하는 case로 이동해 실행"},{"term":"폴스루(Fall-through)","desc":"break가 없으면 다음 case까지 이어서 실행"},{"term":"default","desc":"일치하는 case가 없을 때 실행되는 부분"}],"memo":"switch는 '맞는 곳에서 출발해 break에서 하차'."}},{"id":"written-2026-1-72","no":72,"unit":"프로그래밍 언어 활용","q":"C언어의 malloc( ) 함수에 관한 설명 중 틀린 것은?","choices":["할당된 메모리는 free 명령어로 해제한다.","원하는 시점에 원하는 만큼 동적으로 메모리를 할당한다.","메모리 할당이 불가능하면 NULL이 반환된다.","사용자가 입력한 bit만큼의 메모리를 할당한다."],"ans":4,"exp":{"concept":"malloc(Memory Allocation)은 프로그램 실행 중 필요한 시점에 필요한 크기만큼 힙(Heap) 영역에 메모리를 동적으로 할당하는 C 함수다. 인수로 바이트(byte) 단위 크기를 받아 할당한 메모리의 시작 주소를 돌려주며, 할당에 실패하면 NULL을 반환한다. 다 쓴 메모리는 free로 해제해야 한다.","choices":[{"verdict":"오답","why":"malloc으로 할당한 메모리는 free 함수로 해제하므로 옳은 설명이다(문제에서는 '명령어'라고 표현했지만 정확히는 함수다)."},{"verdict":"오답","why":"malloc은 실행 중 원하는 시점에 원하는 크기만큼 동적으로 메모리를 할당하므로 옳은 설명이다."},{"verdict":"오답","why":"메모리 할당에 실패하면 NULL 포인터를 반환하므로 옳은 설명이다."},{"verdict":"정답","why":"malloc은 bit가 아니라 byte 단위로 크기를 받아 할당한다. 예: malloc(sizeof(int) * 10)."}],"keywords":[{"term":"malloc","desc":"byte 단위로 힙에 메모리 동적 할당, 실패 시 NULL"},{"term":"free","desc":"동적 할당한 메모리 해제"},{"term":"calloc / realloc","desc":"0으로 초기화하며 할당 / 할당 크기 변경"},{"term":"메모리 누수(Memory Leak)","desc":"free를 하지 않아 메모리가 계속 점유되는 문제"}],"memo":"malloc 단위는 바이트(byte), 빌린 건 free로 반납."}},{"id":"written-2026-1-73","no":73,"unit":"프로그래밍 언어 활용","q":"빈 기억공간의 크기가 20KB, 16KB, 8KB, 40KB 일 때 기억장치 배치 전략으로 “Best Fit”을 사용해 17KB의 프로그램을 적재한다면 내부 단편화의 크기는 얼마인가?","choices":["3KB","23KB","64KB","67KB"],"ans":1,"exp":{"concept":"최적 적합(Best Fit)은 프로그램이 들어갈 수 있는 빈 공간 중 남는 공간이 가장 작은 곳에 배치하는 전략이다. 계산: 17KB가 들어갈 수 있는 공간은 20KB와 40KB이고(16KB, 8KB는 작음), 그중 가장 작은 20KB에 배치한다. 남는 공간은 20 - 17 = 3KB이므로 내부 단편화는 3KB다.","choices":[{"verdict":"정답","why":"Best Fit은 20KB 공간에 17KB를 배치하므로 내부 단편화는 20 - 17 = 3KB다."},{"verdict":"오답","why":"23KB는 40KB 공간에 배치했을 때의 단편화(40 - 17)로, 최악 적합(Worst Fit)의 결과다."},{"verdict":"오답","why":"64KB는 빈 공간 20 + 16 + 8 + 40 = 84KB에서 20KB를 뺀 값 등으로 문제와 무관한 수치다."},{"verdict":"오답","why":"67KB는 전체 빈 공간 84KB에서 17KB를 뺀 값으로, 내부 단편화의 크기가 아니다."}],"keywords":[{"term":"최초 적합(First Fit)","desc":"들어갈 수 있는 첫 번째 공간에 배치"},{"term":"최적 적합(Best Fit)","desc":"단편화가 가장 작게 남는 공간에 배치"},{"term":"최악 적합(Worst Fit)","desc":"단편화가 가장 크게 남는 공간에 배치"},{"term":"내부 단편화","desc":"할당된 공간에서 쓰고 남은 부분"}],"memo":"Best는 '딱 맞는 옷', Worst는 '제일 큰 옷', First는 '처음 맞는 옷'."}},{"id":"written-2026-1-74","no":74,"unit":"프로그래밍 언어 활용","q":"TCP/IP에서 논리 주소를 물리 주소로 바꾸어 주는 프로토콜은?","choices":["ARP","IP","TCP","FTP"],"ans":1,"exp":{"concept":"ARP(Address Resolution Protocol)는 IP 주소(논리 주소)를 알고 있을 때 그 장치의 MAC 주소(물리 주소)를 알아내는 프로토콜이다. 같은 네트워크 안에서 실제로 프레임을 보내려면 MAC 주소가 필요하기 때문이다. 반대로 MAC 주소로 IP 주소를 얻는 것은 RARP다.","choices":[{"verdict":"정답","why":"ARP는 논리 주소(IP)를 물리 주소(MAC)로 변환한다."},{"verdict":"오답","why":"IP는 패킷의 주소 지정과 경로 설정을 담당하는 네트워크 계층 프로토콜이며, 주소 변환 기능은 없다."},{"verdict":"오답","why":"TCP는 연결형으로 신뢰성 있는 데이터 전송을 담당하는 전송 계층 프로토콜이다."},{"verdict":"오답","why":"FTP는 파일 전송을 위한 응용 계층 프로토콜이다."}],"keywords":[{"term":"ARP","desc":"IP 주소 → MAC 주소"},{"term":"RARP","desc":"MAC 주소 → IP 주소"},{"term":"ICMP","desc":"IP 통신 중 오류, 제어 메시지 전달(ping)"}],"memo":"ARP(Address Resolution Protocol)는 IP 주소로 MAC(물리) 주소를 찾는다. 앞에 R(Reverse)이 붙은 RARP는 그 반대."}},{"id":"written-2026-1-75","no":75,"unit":"프로그래밍 언어 활용","q":"아래 JAVA 프로그램을 실행했을 때의 실행 결과는?<pre class=\"qcode\"><code class=\"language-java\">public class Ape {\n    static void rs(char a[ ]) {\n        for(int i = 0; i &lt; a.length; i ++)\n            if(a[i] = = 'B')\n                a[i] = 'C';\n            else if(i = = a.length - 1)\n                a[i] = a[i-1];\n            else a[i] = a[i+1];\n    }\n    static void pca(char a[ ]) {\n        for(int i = 0; i &lt; a.length; i ++)\n            System.out.print(a[i]);\n        System.out.println( );\n    }\n    public static void main(String[ ] args) {\n        char c[ ] = {'A','B','D','D','A','B','C'};\n        rs(c);\n        pca(c);\n    }\n}</code></pre>","choices":["CDDACCA","BCDABCC","CDDACCC","BCDABCA"],"ans":2,"exp":{"concept":"배열을 제자리에서 바꾸므로 앞에서 바뀐 값이 뒤 계산에 영향을 준다. 규칙: 값이 'B'면 'C'로, 마지막 칸이면 바로 앞 칸 값으로, 그 외는 바로 다음 칸 값으로 바꾼다(코드의 '= ='는 비교 연산자 ==를 띄어 쓴 것이다). 계산: 처음 A B D D A B C. i=0: 'A'이므로 a[1]='B' → B B D D A B C. i=1: 'B'이므로 'C' → B C D D A B C. i=2: a[3]='D' → 그대로 D. i=3: a[4]='A' → B C D A A B C. i=4: a[5]='B' → B C D A B B C. i=5: 'B'이므로 'C' → B C D A B C C. i=6: 마지막이므로 a[5]='C' → B C D A B C C. 출력은 BCDABCC다.","choices":[{"verdict":"오답","why":"CDDACCA는 첫 글자부터 맞지 않는다. i=0에서 a[0]은 'A'이고 마지막 칸도 아니므로 다음 칸 값 'B'로 바뀐다. 따라서 첫 글자는 C가 아니라 B다."},{"verdict":"정답","why":"앞에서 바뀐 값을 반영해 차례로 계산하면 B C D A B C C가 되어 BCDABCC가 출력된다."},{"verdict":"오답","why":"CDDACCC도 첫 글자가 틀렸다. i=0에서 'A'는 'B'가 아니므로 다음 칸 값 'B'로 바뀌어 첫 글자는 B여야 한다."},{"verdict":"오답","why":"BCDABCA는 마지막 칸을 잘못 계산한 결과다. i=6에서는 바로 앞 칸 a[5]가 이미 'C'로 바뀌었으므로 마지막 글자도 C다."}],"keywords":[{"term":"배열의 참조 전달","desc":"Java에서 배열을 메서드에 넘기면 원본 배열이 직접 바뀜"},{"term":"a.length","desc":"배열 길이, 여기서는 7(인덱스 0~6)"},{"term":"if - else if - else","desc":"위에서부터 처음 참인 조건 하나만 실행"}],"memo":"제자리 변경 문제는 '한 칸 바꿀 때마다 배열을 다시 적어라'."}},{"id":"written-2026-1-76","no":76,"unit":"프로그래밍 언어 활용","q":"다음 파이썬 코드에 ‘53t44’를 입력하면 출력되는 결과는?<pre class=\"qcode\"><code class=\"language-python\">a, b = map(int, input( ).split(\"t\"));\nprint(a, b)</code></pre>","choices":["53 t 44","53t44","53 44","53, 44"],"ans":3,"exp":{"concept":"input()은 한 줄을 문자열로 읽고, split('t')는 문자 't'를 기준으로 문자열을 나눠 리스트로 만든다. map(int, ...)은 각 조각을 정수로 바꾼다. 계산: '53t44'.split('t') → ['53', '44'] → a=53, b=44. print(a, b)는 값 사이에 공백 하나를 넣어 출력하므로 '53 44'가 나온다.","choices":[{"verdict":"오답","why":"구분자 't'는 split 과정에서 제거되므로 출력에 't'가 나타나지 않는다."},{"verdict":"오답","why":"53t44는 입력 문자열 그대로이며, split과 int 변환을 거친 결과가 아니다."},{"verdict":"정답","why":"a=53, b=44가 되고 print의 기본 구분자(sep)가 공백이므로 '53 44'가 출력된다."},{"verdict":"오답","why":"print(a, b)의 기본 구분자는 쉼표가 아니라 공백이므로 '53, 44'는 나오지 않는다."}],"keywords":[{"term":"split(구분자)","desc":"구분자로 문자열을 나눠 리스트 반환"},{"term":"map(함수, 반복 가능 객체)","desc":"각 원소에 함수를 적용"},{"term":"print의 sep","desc":"여러 값 사이 구분 문자, 기본값은 공백"}],"memo":"split은 칼, map(int)는 숫자 변환기, print 사이엔 기본 한 칸 띄기."}},{"id":"written-2026-1-77","no":77,"unit":"프로그래밍 언어 활용","q":"C언어의 자료형 가운데 논리형에 속하는 것은?","choices":["bool","char","int","short"],"ans":1,"exp":{"concept":"논리형은 참(true)과 거짓(false) 두 값만 갖는 자료형이다. C언어에서는 C99부터 _Bool 형이 생겼고, stdbool.h를 포함하면 bool로 쓸 수 있다(C23부터는 bool이 기본 키워드). char, int, short는 문자형과 정수형이다.","choices":[{"verdict":"정답","why":"bool은 true/false 값을 저장하는 논리형 자료형이다."},{"verdict":"오답","why":"char는 문자 1개(1바이트)를 저장하는 문자형이다."},{"verdict":"오답","why":"int는 정수를 저장하는 정수형(보통 4바이트)이다."},{"verdict":"오답","why":"short는 int보다 작은 범위의 정수를 저장하는 정수형(보통 2바이트)이다."}],"keywords":[{"term":"bool / _Bool","desc":"논리형, true(1) 또는 false(0)"},{"term":"정수형","desc":"short, int, long, long long"},{"term":"실수형","desc":"float, double"},{"term":"문자형","desc":"char"}],"memo":"bool은 불(켜짐/꺼짐) 두 가지뿐."}},{"id":"written-2026-1-78","no":78,"unit":"프로그래밍 언어 활용","q":"소프트웨어 개발에서 모듈(Module)이 되기 위한 주요 특징으로 볼 수 없는 것은?","choices":["독립적으로 컴파일이 가능하다.","다른 모듈에서 접근할 수 없어야 한다.","다른 것들과 구별되는 독립적인 기능을 가진 단위(Unit)이다.","유일한 이름을 가지고 있어야 한다."],"ans":2,"exp":{"concept":"모듈(Module)은 소프트웨어를 기능 단위로 나눈 조각으로, 독립적인 기능을 갖고 단독으로 컴파일할 수 있으며 유일한 이름을 가진다. 모듈은 다른 모듈에서 호출되거나 다른 프로그램에서 접근해 사용할 수 있어야 의미가 있다. 레고 블록처럼 따로 만들어지지만 서로 끼워 쓸 수 있어야 한다.","choices":[{"verdict":"오답","why":"모듈은 독립적으로 컴파일할 수 있다는 것이 주요 특징이므로 옳은 설명이다."},{"verdict":"정답","why":"모듈은 다른 모듈에서 호출(접근)해 사용할 수 있어야 한다. 접근할 수 없어야 한다는 것은 모듈의 특징이 아니다."},{"verdict":"오답","why":"모듈은 다른 것과 구별되는 독립적인 기능을 가진 단위이므로 옳은 설명이다."},{"verdict":"오답","why":"모듈은 호출되기 위해 유일한 이름을 가져야 하므로 옳은 설명이다."}],"keywords":[{"term":"모듈화(Modularity)","desc":"시스템을 기능 단위 모듈로 나누는 설계 원리"},{"term":"응집도(Cohesion)","desc":"모듈 내부 요소의 관련 정도, 높을수록 좋음"},{"term":"결합도(Coupling)","desc":"모듈 간 의존 정도, 낮을수록 좋음"},{"term":"정보 은닉(Information Hiding)","desc":"모듈 내부 구현은 숨기고 인터페이스로만 접근"}],"memo":"모듈은 '독립 컴파일, 독립 기능, 유일 이름, 호출 가능'."}},{"id":"written-2026-1-79","no":79,"unit":"프로그래밍 언어 활용","q":"다음 중 소프트웨어 개발 지원 도구에 관한 설명으로 옳지 않은 것은?","choices":["외부의 플러그인을 쉽게 검색하여 적용할 수 있는 IDE를 선정해야 한다.","IDE는 개발자가 컴파일 및 디버깅을 편리하게 할 수 있도록 지원하는 도구이다.","코드 품질 및 인터페이스 검사 도구는 모든 코딩이 완료된 후에 실행하는 것이 좋다.","개발 도구를 선정할 때는 성능이나 편의성뿐 아니라 범용성도 고려해야 한다."],"ans":3,"exp":{"concept":"소프트웨어 개발 지원 도구에는 IDE(통합 개발 환경), 빌드 도구, 형상 관리 도구, 테스트 도구, 코드 품질(정적 분석) 및 인터페이스 검사 도구 등이 있다. 품질 검사 도구는 결함을 일찍 찾아 수정 비용을 줄이도록 개발하는 동안 수시로 실행하는 것이 바람직하다. 숙제를 다 끝낸 뒤 한꺼번에 채점하는 것보다 문제를 풀 때마다 확인하는 편이 고치기 쉬운 것과 같다.","choices":[{"verdict":"오답","why":"필요한 외부 플러그인을 쉽게 찾아 적용할 수 있는 확장성은 IDE 선정 기준이므로 옳은 설명이다."},{"verdict":"오답","why":"IDE는 코드 편집, 컴파일, 디버깅, 배포 등을 하나의 환경에서 편리하게 하도록 지원하는 도구이므로 옳은 설명이다."},{"verdict":"정답","why":"코드 품질 및 인터페이스 검사 도구는 코딩이 다 끝난 뒤가 아니라 개발 중에 수시로(지속적으로) 실행해 결함을 조기에 발견하는 것이 좋다."},{"verdict":"오답","why":"개발 도구 선정 시 성능, 편의성뿐 아니라 범용성(많이 쓰이는지, 여러 환경 지원), 적정성, 효율성 등을 고려하므로 옳은 설명이다."}],"keywords":[{"term":"IDE(Integrated Development Environment)","desc":"편집, 컴파일, 디버깅을 통합 지원하는 도구(Eclipse, IntelliJ, VS Code)"},{"term":"정적 분석 도구","desc":"실행하지 않고 코드를 분석해 결함, 규칙 위반을 찾음(PMD, SonarQube, Checkstyle)"},{"term":"빌드 도구","desc":"컴파일, 패키징을 자동화(Ant, Maven, Gradle)"}],"memo":"품질 검사는 '끝나고 한 번'이 아니라 '하면서 수시로'."}},{"id":"written-2026-1-80","no":80,"unit":"프로그래밍 언어 활용","q":"다음 C언어 프로그램을 실행했을 때의 결과는?<pre class=\"qcode\"><code class=\"language-c\">#include &lt;stdio.h&gt;\nint main(void) {\n    int n = 4;\n    int* pt = NULL;\n    pt = &amp;n;\n    printf(\"%d\", &amp;n + *pt - *&amp;pt + n);\n    return 0;\n}</code></pre>","choices":["0","4","8","12"],"ans":3,"exp":{"concept":"포인터 연산에서 &n은 n의 주소, *pt는 pt가 가리키는 값, *&pt는 &pt를 다시 역참조한 것이므로 pt 자체(= &n)다. 포인터에 정수를 더하면 자료형 크기 단위로 이동하고, 같은 배열 기준의 두 포인터를 빼면 그 사이 원소 개수가 나온다. 계산: 식은 왼쪽부터 ((&n + *pt) - *&pt) + n. *pt = 4이므로 &n + 4는 n에서 int 4칸 뒤의 주소, 여기서 *&pt(= &n)를 빼면 4칸 차이인 정수 4, 마지막에 n(4)을 더해 8이 출력된다.","choices":[{"verdict":"오답","why":"주소끼리 빼서 상쇄되는 것은 맞지만 *pt(4)와 n(4)이 남으므로 0이 아니다."},{"verdict":"오답","why":"4는 *pt나 n 중 하나만 반영한 값이다. 포인터 차 4와 n 4를 더해야 한다."},{"verdict":"정답","why":"(&n + 4) - &n = 4(int 4칸 차이), 여기에 n = 4를 더해 8이 출력된다."},{"verdict":"오답","why":"12는 4를 세 번 더한 값으로, *&pt가 &n과 같은 주소라서 &n과 상쇄된다는 점을 놓친 오답이다. 실제로는 포인터 차 4 + n 4 = 8이다."}],"keywords":[{"term":"& (주소 연산자)","desc":"변수의 메모리 주소를 구함"},{"term":"* (간접 참조 연산자)","desc":"포인터가 가리키는 곳의 값을 구함"},{"term":"*&p","desc":"주소를 구한 뒤 다시 역참조하므로 p 자신과 같음"},{"term":"포인터 뺄셈","desc":"두 주소 차이를 자료형 크기로 나눈 원소 개수"}],"memo":"*와 &는 서로 지우개: *&pt = pt."}},{"id":"written-2026-1-81","no":81,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발 방법론의 테일러링(Tailoring)에 대한 설명으로 옳지 않은 것은?","choices":["프로젝트에 최적화된 개발 방법론을 적용하고자 절차, 산출물 등을 적절히 변경하는 활동이다.","관리 측면에서의 목적 중 하나는 최단기간에 안정적으로 프로젝트를 진행하기 위한 사전 위험을 식별하고 제거하는 것이다.","프로젝트를 수행할 때 예상되는 변화는 배제하고 신속하게 진행해야 한다.","기술적 측면에서의 목적 중 하나는 프로젝트에 최적화된 기술 요소를 도입해 프로젝트 특성에 맞는 최적의 기법과 도구를 사용하는 것이다."],"ans":3,"exp":{"concept":"테일러링(Tailoring)은 표준 개발 방법론을 프로젝트의 특성(규모, 기간, 기술, 조직 등)에 맞게 절차, 활동, 산출물을 가감하고 수정하는 작업이다. 옷을 몸에 맞게 수선하듯 방법론을 프로젝트에 맞춘다. 이때 프로젝트 수행 중 예상되는 변화(요구사항, 환경 변화 등)를 미리 고려해 반영해야 한다.","choices":[{"verdict":"오답","why":"테일러링은 프로젝트에 최적화된 방법론을 적용하기 위해 절차, 산출물 등을 변경하는 활동이라는 정의에 맞는 옳은 설명이다."},{"verdict":"오답","why":"관리 측면 목적으로 최단기간에 안정적인 진행을 위한 사전 위험 식별과 제거가 있으므로 옳은 설명이다."},{"verdict":"정답","why":"테일러링은 프로젝트 수행 시 예상되는 변화를 배제하는 것이 아니라 오히려 고려해 반영해야 한다."},{"verdict":"오답","why":"기술 측면 목적으로 프로젝트에 최적화된 기술 요소를 도입해 최적의 기법과 도구를 사용하는 것이 있으므로 옳은 설명이다."}],"keywords":[{"term":"테일러링(Tailoring)","desc":"방법론을 프로젝트 특성에 맞게 수정, 보완"},{"term":"내부 기준","desc":"목표 환경, 요구사항, 프로젝트 규모, 보유 기술"},{"term":"외부 기준","desc":"법적 제약사항, 표준 품질 기준"}],"memo":"테일러(재단사)는 몸(프로젝트)과 앞으로의 변화까지 재서 옷을 고친다."}},{"id":"written-2026-1-82","no":82,"unit":"정보시스템 구축 관리","q":"LOC 기법으로 예측된 총 라인수가 36,000라인이고, 개발에 참여할 프로그래머가 6명, 프로그래머들의 평균 생산성이 월간 300라인일 때 개발에 소요되는 기간은?","choices":["5개월","10개월","15개월","20개월"],"ans":4,"exp":{"concept":"LOC(Lines Of Code) 기법은 예상 코드 라인 수로 노력(인월)과 기간을 추정하는 방법이다. 개발 기간 = 총 라인 수 / (참여 인원 × 1인당 월 생산성)으로 구한다. 계산: 36,000 / (6 × 300) = 36,000 / 1,800 = 20개월.","choices":[{"verdict":"오답","why":"5개월이 되려면 월 생산성이 1,200라인이어야 한다. 실제 계산 결과는 20개월이다."},{"verdict":"오답","why":"10개월은 인원이나 생산성을 2배로 잘못 적용한 값이다. 36,000 / 1,800 = 20개월이다."},{"verdict":"오답","why":"15개월은 계산 근거가 맞지 않는 값이다. 36,000 / 1,800 = 20개월이다."},{"verdict":"정답","why":"6명 × 300라인 = 월 1,800라인을 생산하므로 36,000 / 1,800 = 20개월이 걸린다."}],"keywords":[{"term":"LOC 기법","desc":"원시 코드 라인 수의 낙관치, 비관치, 기대치로 추정"},{"term":"노력(인월, Man-Month)","desc":"총 라인 수 / 1인당 월 생산성"},{"term":"개발 기간","desc":"노력(인월) / 투입 인원"}],"memo":"기간 = 라인 ÷ (사람 × 생산성)."}},{"id":"written-2026-1-83","no":83,"unit":"정보시스템 구축 관리","q":"소프트웨어 프로젝트 관리를 효율적으로 수행하기 위한 3P 가운데, 소프트웨어 프로젝트 수행을 위한 Task Framework의 고려와 가장 관련이 깊은 것은?","choices":["People","Problem","Process","Product"],"ans":3,"exp":{"concept":"효과적인 프로젝트 관리를 위한 3P는 사람(People), 문제(Problem), 프로세스(Process)다. People은 인적 자원, Problem은 문제 인식(무엇을 해결할지), Process는 작업을 어떤 절차와 틀로 수행할지에 대한 관리다. 소프트웨어 개발 작업의 틀(Task Framework)을 고려하는 것은 Process에 해당한다.","choices":[{"verdict":"오답","why":"People은 프로젝트 관리에서 가장 기본이 되는 인적 자원에 대한 관리다."},{"verdict":"오답","why":"Problem은 사용자 입장에서 문제를 분석하고 인식하는 것이다."},{"verdict":"정답","why":"Process는 소프트웨어 개발에 필요한 전체 작업의 틀(Task Framework)을 정하는 것이다."},{"verdict":"오답","why":"Product(제품)는 3P에 포함되지 않는다(3P는 People, Problem, Process)."}],"keywords":[{"term":"People","desc":"프로젝트 관리의 가장 기본 요소, 인적 자원"},{"term":"Problem","desc":"사용자 관점의 문제 분석과 인식"},{"term":"Process","desc":"개발 작업의 틀(Task Framework)"}],"memo":"3P는 '사람이 문제를 프로세스로 푼다', 제품(Product)은 없다."}},{"id":"written-2026-1-84","no":84,"unit":"정보시스템 구축 관리","q":"기존 무선 랜의 한계를 극복하기 위해 등장한 것으로, 대규모 디바이스의 네트워크 생성에 최적화되어 있어 차세대 이동통신, 홈네트워킹, 공공 안전 등 특수목적에 사용되는 새로운 방식의 네트워크 기술은 무엇인가?","choices":["Mesh Network","Software Defined Perimeter","Virtual Private Network","Local Area Network"],"ans":1,"exp":{"concept":"메시 네트워크(Mesh Network)는 여러 노드(기기)가 그물처럼 서로 직접 연결되어 데이터를 중계하는 네트워크다. 기존 무선 랜의 한계를 극복하고 대규모 디바이스 네트워크 생성에 최적화되어 있어 차세대 이동통신, 홈네트워킹, 공공 안전 등 특수 목적에 쓰인다. 한 경로가 끊겨도 다른 노드를 거쳐 우회할 수 있어 안정적이다.","choices":[{"verdict":"정답","why":"대규모 디바이스 네트워크 생성에 최적화되어 차세대 이동통신, 홈네트워킹, 공공 안전 등에 쓰이는 새로운 방식의 네트워크는 메시 네트워크다."},{"verdict":"오답","why":"SDP(Software Defined Perimeter)는 인증된 사용자와 기기에만 자원 접근을 허용해 네트워크 경계를 소프트웨어로 정의하는 보안 기술이다."},{"verdict":"오답","why":"VPN(Virtual Private Network)은 공중망을 이용해 암호화된 터널로 전용망처럼 쓰는 가상 사설망이다."},{"verdict":"오답","why":"LAN(Local Area Network)은 건물, 학교 등 좁은 지역을 연결하는 근거리 통신망이다."}],"keywords":[{"term":"Mesh Network","desc":"노드끼리 그물처럼 연결, 대규모 디바이스 네트워크"},{"term":"SDP(Software Defined Perimeter)","desc":"소프트웨어 정의 경계, 제로 트러스트 기반 접근 제어"},{"term":"VPN","desc":"공중망 위의 암호화된 가상 사설망"}],"memo":"메시(Mesh) = 그물, 그물처럼 엮인 대규모 기기 네트워크."}},{"id":"written-2026-1-85","no":85,"unit":"정보시스템 구축 관리","q":"시스템이 몇 대가 되더라도 하나의 시스템에서 인증에 성공하면 다른 시스템에 대한 접근 권한까지 얻게 되는 시스템을 의미하는 것은?","choices":["SOA","SOS","SSO","SBO"],"ans":3,"exp":{"concept":"SSO(Single Sign-On)는 한 번의 로그인(인증)으로 여러 시스템이나 서비스를 추가 인증 없이 이용할 수 있게 하는 기술이다. 회사 포털에 한 번 로그인하면 메일, 결재, 인사 시스템을 다시 로그인하지 않고 쓰는 것이 예다.","choices":[{"verdict":"오답","why":"SOA(Service Oriented Architecture)는 기능을 서비스 단위로 나눠 재사용, 연동하는 서비스 지향 아키텍처다."},{"verdict":"오답","why":"SOS는 하나의 인증으로 여러 시스템에 접근하는 기술을 가리키는 표준 용어가 아니다."},{"verdict":"정답","why":"SSO(Single Sign-On)는 한 시스템에서 인증하면 다른 시스템에도 접근 권한을 얻는 통합 인증 방식이다."},{"verdict":"오답","why":"SBO는 통합 인증과 관련된 표준 용어가 아니다."}],"keywords":[{"term":"SSO(Single Sign-On)","desc":"한 번 인증으로 여러 시스템 이용"},{"term":"SOA(Service Oriented Architecture)","desc":"서비스 단위로 구성하는 아키텍처"},{"term":"OAuth","desc":"비밀번호 없이 다른 서비스에 권한을 위임하는 표준"}],"memo":"SSO = Single(한 번) Sign-On(로그인)."}},{"id":"written-2026-1-86","no":86,"unit":"정보시스템 구축 관리","q":"침입 차단 시스템(방화벽) 가운데 아래 그림과 같은 형태로 구축된 유형은?<img class=\"q-img\" src=\"data/img/5ce3fdded5a0381eaa2120ed91e9c614.png\" width=\"498\" alt=\"문항 원본 자료\">","choices":["Ring Homed","Screened Subnet","Block Host","Tree Host"],"ans":2,"exp":{"concept":"그림은 인터넷 쪽의 외부 라우터와 내부 PC 망 쪽의 내부 라우터 사이에, 서버들과 배스천 호스트(Bastion Host)가 놓인 별도 네트워크가 있는 구조다. 이처럼 외부 라우터(스크리닝 라우터)와 내부 라우터 사이에 DMZ(완충 지대) 서브넷을 두는 방화벽 구성을 스크린드 서브넷(Screened Subnet)이라 한다. 외부에서 들어오면 문(라우터)을 두 번 지나야 내부망에 닿으므로 가장 안전한 구성으로 꼽힌다.","choices":[{"verdict":"오답","why":"Ring Homed는 방화벽 구축 유형의 표준 용어가 아니다. 표준 유형은 스크리닝 라우터, 배스천 호스트, 듀얼 홈드 게이트웨이, 스크린드 호스트 게이트웨이, 스크린드 서브넷 게이트웨이다."},{"verdict":"정답","why":"외부 라우터와 내부 라우터 사이에 배스천 호스트와 서버가 있는 DMZ 서브넷을 둔 구조이므로 스크린드 서브넷이다."},{"verdict":"오답","why":"Block Host는 표준 방화벽 구축 유형이 아니다. 비슷한 이름의 스크린드 호스트(Screened Host)는 라우터 하나와 배스천 호스트 하나로 구성되며 별도의 서브넷이 없다."},{"verdict":"오답","why":"Tree Host는 방화벽 구축 유형의 표준 용어가 아니다."}],"keywords":[{"term":"배스천 호스트(Bastion Host)","desc":"외부 공격에 노출되는 위치에서 접근을 통제하는 강화된 호스트"},{"term":"듀얼 홈드 게이트웨이(Dual-Homed Gateway)","desc":"네트워크 카드 2개로 내부와 외부를 분리하는 배스천 호스트"},{"term":"스크린드 호스트 게이트웨이","desc":"스크리닝 라우터 + 배스천 호스트"},{"term":"스크린드 서브넷 게이트웨이","desc":"두 스크리닝 라우터 사이에 DMZ 서브넷을 둔 구조, 가장 안전"},{"term":"DMZ(Demilitarized Zone)","desc":"외부에 서비스하는 서버를 두는 완충 지대"}],"memo":"라우터 두 개 사이에 서브넷(DMZ)이 끼어 있으면 스크린드 서브넷."}},{"id":"written-2026-1-87","no":87,"unit":"정보시스템 구축 관리","q":"합법적으로 소유하고 있던 사용자의 도메인을 탈취하거나 DNS 이름을 속여, 사용자들이 진짜 사이트로 오인하도록 유도해 개인 정보를 훔치는 공격 기법은 무엇인가?","choices":["XSS","Phishing","Ransomware","Pharming"],"ans":4,"exp":{"concept":"파밍(Pharming)은 사용자 PC의 hosts 파일이나 DNS 정보를 조작하거나 도메인을 탈취해, 사용자가 정상 주소를 입력해도 가짜 사이트로 접속되게 만들어 개인정보를 빼내는 공격이다. 피싱이 가짜 링크를 클릭하도록 유인하는 것이라면, 파밍은 주소를 제대로 입력해도 가짜 사이트로 가게 길 안내 자체를 바꿔 버리는 것이다.","choices":[{"verdict":"오답","why":"XSS(Cross Site Scripting)는 게시판 등 웹 페이지에 악성 스크립트를 삽입해 방문자의 브라우저에서 실행되게 하는 공격이다."},{"verdict":"오답","why":"피싱(Phishing)은 금융기관 등을 사칭한 메일, 메시지로 가짜 사이트 링크를 보내 사용자가 직접 접속해 정보를 입력하도록 유도하는 공격이다. 도메인 탈취나 DNS 조작은 파밍의 특징이다."},{"verdict":"오답","why":"랜섬웨어(Ransomware)는 파일을 암호화한 뒤 복호화를 대가로 돈을 요구하는 악성코드다."},{"verdict":"정답","why":"도메인을 탈취하거나 DNS 이름을 속여 사용자가 진짜 사이트로 오인하게 하고 개인정보를 훔치는 공격은 파밍이다."}],"keywords":[{"term":"파밍(Pharming)","desc":"DNS, hosts 조작으로 정상 주소 입력 시에도 가짜 사이트 접속"},{"term":"피싱(Phishing)","desc":"사칭 메일, 메시지로 가짜 사이트 접속 유도"},{"term":"스미싱(Smishing)","desc":"문자 메시지(SMS)를 이용한 피싱"},{"term":"DNS 스푸핑","desc":"DNS 응답을 위조해 다른 IP로 유도"}],"memo":"파밍(Pharming)은 길 안내판(DNS)을 바꿔치기, 피싱은 미끼(링크)로 낚기."}},{"id":"written-2026-1-88","no":88,"unit":"정보시스템 구축 관리","q":"다음의 암호 알고리즘 가운데 성격이 다른 것은?","choices":["AES","MD4","MD5","SHA-1"],"ans":1,"exp":{"concept":"AES는 같은 키로 암호화와 복호화를 하는 대칭 키 블록 암호 알고리즘이다. MD4, MD5, SHA-1은 임의 길이의 입력을 고정 길이 값으로 바꾸는 해시(Hash) 함수로, 원래 값으로 되돌릴 수 없는 단방향 함수다. 따라서 성격이 다른 하나는 AES다.","choices":[{"verdict":"정답","why":"AES(Advanced Encryption Standard)는 복호화가 가능한 대칭 키 암호 알고리즘으로, 나머지 해시 함수들과 성격이 다르다."},{"verdict":"오답","why":"MD4는 128비트 해시값을 만드는 해시 함수다."},{"verdict":"오답","why":"MD5는 MD4를 개선한 128비트 해시 함수다."},{"verdict":"오답","why":"SHA-1은 160비트 해시값을 만드는 해시 함수다."}],"keywords":[{"term":"대칭 키 암호","desc":"암호화, 복호화 키가 같음(DES, AES, SEED, ARIA)"},{"term":"비대칭(공개) 키 암호","desc":"공개키와 개인키를 사용(RSA, ECC)"},{"term":"해시 함수","desc":"단방향, 고정 길이 출력(MD5, SHA 계열, HAVAL)"}],"memo":"MD, SHA는 해시(되돌릴 수 없음), AES는 암호(되돌릴 수 있음)."}},{"id":"written-2026-1-89","no":89,"unit":"정보시스템 구축 관리","q":"다음 설명에 해당하는 IT 기술은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>네트워크를 제어부와 데이터 전달부로 분리하여 네트워크 관리자가 네트워크를 보다 효율적으로 제어, 관리할 수 있도록 하는 기술</li><li>기존의 라우터, 스위치 등과 같이 하드웨어에 의존하던 네트워크 체계에서 안정성, 속도, 보안 등을 소프트웨어로 제어, 관리하기 위해 개발됨</li><li>네트워크 장비의 펌웨어 업그레이드를 통해 사용자가 데이터 전송 경로를 직접 관리할 수 있으며, 기존 네트워크에 영향을 주지 않고 특정 서비스의 전송 경로를 수정하여 인터넷상에서 발생하는 문제를 처리할 수 있음</li></ul></div>","choices":["NFS(Network File System)","SDN(Software Defined Networking)","Network Mapper","AOE Network"],"ans":2,"exp":{"concept":"SDN(Software Defined Networking)은 네트워크를 제어부(Control Plane)와 데이터 전달부(Data Plane)로 분리해, 소프트웨어(컨트롤러)로 네트워크 경로와 정책을 중앙에서 프로그래밍하듯 관리하는 기술이다. 장비마다 일일이 설정하던 것을 한 곳의 소프트웨어로 지휘하는 교통관제센터와 같다.","choices":[{"verdict":"오답","why":"NFS(Network File System)는 네트워크로 연결된 다른 컴퓨터의 파일을 자기 파일처럼 사용하게 하는 분산 파일 시스템 프로토콜이다."},{"verdict":"정답","why":"제어부와 데이터 전달부를 분리하고 네트워크를 소프트웨어로 제어, 관리하는 기술은 SDN이다."},{"verdict":"오답","why":"Network Mapper(Nmap)는 네트워크의 호스트와 열린 포트, 서비스를 탐색하는 보안 스캐닝 도구다."},{"verdict":"오답","why":"AOE(Activity On Edge) Network는 작업을 간선으로 표현해 프로젝트 일정(임계 경로)을 분석하는 그래프 모델이다."}],"keywords":[{"term":"SDN","desc":"제어부와 데이터 전달부 분리, 소프트웨어로 네트워크 제어"},{"term":"NFV(Network Functions Virtualization)","desc":"라우터, 방화벽 등 네트워크 기능을 가상화해 범용 서버에서 실행"},{"term":"OpenFlow","desc":"SDN 컨트롤러와 스위치 간 표준 통신 프로토콜"}],"memo":"SDN = 네트워크를 소프트웨어(S)로 정의(D)."}},{"id":"written-2026-1-90","no":90,"unit":"정보시스템 구축 관리","q":"악성코드의 유형 가운데 다른 컴퓨터의 취약점을 이용해 스스로 전파되거나 메일을 통해 전파되면서 스스로를 증식하는 것은?","choices":["Worm","Adware","Rogue Ware","Reflection Attack"],"ans":1,"exp":{"concept":"웜(Worm)은 다른 프로그램에 기생하지 않고 스스로를 복제해 네트워크 취약점이나 이메일을 통해 퍼지는 악성코드다. 바이러스가 숙주 파일이 있어야 퍼진다면, 웜은 혼자서 기어다니며(Worm, 벌레) 번식한다. 대량 복제로 네트워크 부하를 일으키기도 한다.","choices":[{"verdict":"정답","why":"다른 컴퓨터의 취약점이나 메일을 통해 스스로 전파, 증식하는 악성코드는 웜이다."},{"verdict":"오답","why":"애드웨어(Adware)는 사용자 동의 없이 광고를 띄우는 소프트웨어로, 스스로 전파하지는 않는다."},{"verdict":"오답","why":"로그웨어(Rogue Ware)는 백신처럼 위장해 가짜 감염 경고를 띄우고 결제를 유도하는 가짜 보안 프로그램이다."},{"verdict":"오답","why":"반사 공격(Reflection Attack)은 악성코드가 아니라 응답을 되돌려 보내는 제3자(반사체)를 이용해 공격 대상에게 트래픽을 보내는 공격 기법이다."}],"keywords":[{"term":"웜(Worm)","desc":"독자 실행, 자기 복제, 네트워크로 전파"},{"term":"바이러스(Virus)","desc":"다른 파일에 기생해 감염"},{"term":"트로이 목마(Trojan Horse)","desc":"정상 프로그램으로 위장, 자기 복제 없음"}],"memo":"웜은 벌레처럼 혼자 기어다니며 번식한다."}},{"id":"written-2026-1-91","no":91,"unit":"정보시스템 구축 관리","q":"공격자가 패킷의 출발지 주소를 바꿔 출발지와 목적지의 주소(또는 포트)가 서로 같아지도록 만드는 공격 유형은?","choices":["SYN Flooding","Key Logger Attack","TearDrop","Land"],"ans":4,"exp":{"concept":"랜드(Land) 공격은 패킷의 출발지 IP 주소(와 포트)를 목적지와 똑같이 위조해 보내는 서비스 거부(DoS) 공격이다. 공격 대상은 자기 자신에게 계속 응답을 보내는 무한 루프에 빠져 자원이 고갈된다. 보낸 사람 주소에 받는 사람 주소를 적은 편지를 보내 계속 자기에게 답장하게 만드는 것과 같다.","choices":[{"verdict":"오답","why":"SYN Flooding은 TCP 3-way handshake에서 SYN만 대량으로 보내고 응답하지 않아 서버의 연결 대기 공간을 가득 채우는 공격이다."},{"verdict":"오답","why":"키로거 공격(Key Logger Attack)은 사용자의 키보드 입력을 몰래 기록해 비밀번호 등을 빼내는 공격이다."},{"verdict":"오답","why":"티어드롭(TearDrop)은 IP 패킷 조각(Fragment)의 오프셋(Offset) 값을 겹치게 조작해 재조립 과정에서 오류를 일으키는 공격이다."},{"verdict":"정답","why":"출발지와 목적지 주소(포트)를 같게 만들어 보내는 공격은 랜드(Land) 공격이다."}],"keywords":[{"term":"Land Attack","desc":"출발지 IP = 목적지 IP로 위조"},{"term":"TearDrop","desc":"Fragment Offset 조작"},{"term":"Smurf","desc":"ICMP 브로드캐스트 증폭"},{"term":"Ping of Death","desc":"규정 크기 초과 ICMP 패킷 전송"}],"memo":"Land = 제자리로 착륙(Land), 출발지와 목적지가 같다."}},{"id":"written-2026-1-92","no":92,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발 프레임워크에 관한 설명 중 틀린 것은?","choices":["생산성 향상, 유지보수성 향상 등의 장점이 있다.","개발해야 할 애플리케이션의 일부분이 이미 구현되어 있으므로 동일한 로직 반복을 줄일 수 있다.","라이브러리와 달리 사용자 코드가 직접 호출하여 사용하므로 소프트웨어 개발 프레임워크가 직접 코드의 흐름을 제어할 수 없다.","반제품 상태의 제품을 바탕으로 도메인별로 필요한 서비스 컴포넌트를 사용해 재사용성 확대와 성능을 보장 받을 수 있도록 하는 개발 소프트웨어이다."],"ans":3,"exp":{"concept":"소프트웨어 개발 프레임워크는 애플리케이션 개발에 필요한 기본 구조와 공통 기능을 미리 구현해 둔 반제품 형태의 소프트웨어다. 라이브러리는 개발자 코드가 필요할 때 호출하지만, 프레임워크는 프레임워크가 전체 흐름을 쥐고 개발자 코드를 호출한다. 이를 제어의 역전(IoC, Inversion of Control)이라 한다.","choices":[{"verdict":"오답","why":"공통 기능이 이미 구현되어 있어 생산성과 유지보수성이 향상되므로 옳은 설명이다."},{"verdict":"오답","why":"애플리케이션 일부가 이미 구현되어 있어 동일한 로직의 반복 구현을 줄일 수 있으므로 옳은 설명이다."},{"verdict":"정답","why":"설명이 반대다. 라이브러리는 사용자 코드가 직접 호출하지만, 프레임워크는 프레임워크가 코드의 흐름을 제어하며 사용자 코드를 호출한다(제어의 역전)."},{"verdict":"오답","why":"반제품 상태의 제품을 바탕으로 도메인별 서비스 컴포넌트를 사용해 재사용성과 성능을 보장받는 개발 소프트웨어라는 정의와 일치하므로 옳은 설명이다."}],"keywords":[{"term":"IoC(Inversion of Control)","desc":"제어의 역전, 프레임워크가 흐름을 제어"},{"term":"라이브러리","desc":"개발자가 필요할 때 호출해 쓰는 기능 모음"},{"term":"전자정부 표준프레임워크","desc":"Spring 기반 국내 공공 표준 개발 프레임워크"},{"term":"프레임워크 특성","desc":"모듈화, 재사용성, 확장성, 제어의 역흐름"}],"memo":"라이브러리는 내가 부르고, 프레임워크는 나를 부른다."}},{"id":"written-2026-1-93","no":93,"unit":"정보시스템 구축 관리","q":"DoS(Denial of Service) 공격에 관한 설명으로 틀린 것은?","choices":["Ping of Death 공격은 정상 크기보다 큰 ICMP 패킷을 작은 조각(Fragment)으로 쪼개어 공격 대상이 조각화된 패킷을 처리하도록 만드는 공격 방법이다.","SYN Flooding은 존재하지 않는 클라이언트가 서버별로 한정된 접속 가능 공간에 접속한 것처럼 속여서 다른 사용자가 서비스를 이용할 수 없게 하는 것이다.","Smurf 공격은 멀티캐스트(Multicast)를 활용해 공격 대상이 네트워크의 임의의 시스템에 패킷을 보내도록 만드는 공격이다.","Land 공격은 패킷을 전송할 때 출발지 IP 주소와 목적지 IP 주소 값을 동일하게 만들어 공격 대상에게 보내는 공격 방법이다."],"ans":3,"exp":{"concept":"DoS(Denial of Service) 공격은 시스템 자원을 고갈시켜 정상 사용자가 서비스를 이용하지 못하게 하는 공격이다. 대표 유형으로 Ping of Death(큰 ICMP 패킷), SYN Flooding(연결 대기 공간 고갈), Smurf(ICMP 브로드캐스트 증폭), TearDrop(Fragment 오프셋 조작), Land(출발지 = 목적지) 등이 있다. Smurf는 멀티캐스트가 아니라 브로드캐스트를 이용한다는 점이 핵심이다.","choices":[{"verdict":"오답","why":"Ping of Death는 규정 크기(65,535바이트)를 넘는 ICMP 패킷을 보내 잘게 조각난 패킷을 처리하게 만드는 공격이므로 옳은 설명이다."},{"verdict":"오답","why":"SYN Flooding은 존재하지 않는 클라이언트가 접속한 것처럼 속여 서버의 한정된 접속 대기 공간을 채우는 공격이므로 옳은 설명이다."},{"verdict":"정답","why":"Smurf 공격은 출발지를 공격 대상 IP로 위조한 ICMP 패킷을 네트워크의 브로드캐스트(Broadcast) 주소로 보내, 다수 시스템의 응답이 공격 대상에게 몰리게 하는 공격이다. 멀티캐스트가 아니다."},{"verdict":"오답","why":"Land 공격은 출발지 IP와 목적지 IP를 같게 만들어 공격 대상에게 보내는 공격이므로 옳은 설명이다."}],"keywords":[{"term":"Smurf(Smurfing)","desc":"ICMP + 브로드캐스트 주소 + 출발지 위조로 응답 폭주"},{"term":"Ping of Death","desc":"65,535바이트 초과 ICMP 패킷"},{"term":"브로드캐스트 vs 멀티캐스트","desc":"네트워크 전체에 전송 vs 특정 그룹에만 전송"}],"memo":"스머프는 마을 전체(브로드캐스트)에 소문을 퍼뜨려 한 명에게 답장이 몰리게 한다."}},{"id":"written-2026-1-94","no":94,"unit":"정보시스템 구축 관리","q":"다음 설명에 해당하는 서비스 공격 유형은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>공격자가 가상의 클라이언트로 위장한 뒤 3-way-handshake 과정을 의도적으로 중단시켜, 공격 대상인 서버를 대기 상태에 놓이게 함으로써 정상적인 서비스를 수행하지 못하도록 만드는 공격 방법이다.</p></div>","choices":["SMURFING","Land","SYN Flooding","TearDrop"],"ans":3,"exp":{"concept":"TCP는 연결할 때 SYN → SYN+ACK → ACK의 3-way handshake를 거친다. SYN Flooding은 공격자가 가짜 클라이언트로 SYN만 대량으로 보내고 마지막 ACK를 보내지 않아, 서버가 반쯤 열린 연결을 계속 기다리다 대기 공간(백로그 큐)이 가득 차 정상 접속을 받지 못하게 하는 공격이다. 식당에 예약 전화만 잔뜩 걸고 아무도 오지 않아 진짜 손님을 못 받는 상황과 같다.","choices":[{"verdict":"오답","why":"스머핑(SMURFING)은 출발지를 공격 대상으로 위조한 ICMP 패킷을 브로드캐스트로 보내 응답을 몰아주는 공격으로, 3-way handshake와는 무관하다."},{"verdict":"오답","why":"Land 공격은 출발지 IP와 목적지 IP를 같게 위조해 보내는 공격이다."},{"verdict":"정답","why":"가짜 클라이언트로 위장해 3-way handshake를 의도적으로 중단시켜 서버를 대기 상태로 만드는 공격은 SYN Flooding이다."},{"verdict":"오답","why":"TearDrop은 IP 조각(Fragment)의 오프셋 정보를 조작해 재조립 오류를 일으키는 공격이다."}],"keywords":[{"term":"3-way handshake","desc":"SYN → SYN+ACK → ACK로 TCP 연결 설정"},{"term":"SYN Flooding","desc":"ACK를 보내지 않아 서버 대기 큐 고갈"},{"term":"SYN Cookie","desc":"SYN Flooding 대응 기법 중 하나"}],"memo":"'3-way handshake 중단, 대기 상태'가 보이면 SYN Flooding."}},{"id":"written-2026-1-95","no":95,"unit":"정보시스템 구축 관리","q":"Python을 기반으로 하는 웹 크롤링(Web Crawling) 프레임워크로 옳은 것은?","choices":["CrawlCat","SBAS","Li-fi","Scrapy"],"ans":4,"exp":{"concept":"웹 크롤링(Web Crawling)은 프로그램이 웹 페이지를 자동으로 돌아다니며 정보를 수집하는 것이다. 스크래피(Scrapy)는 파이썬(Python)으로 작성된 대표적인 오픈 소스 웹 크롤링 프레임워크로, 페이지 수집과 데이터 추출 과정을 체계적으로 처리해 준다.","choices":[{"verdict":"오답","why":"CrawlCat은 정보처리기사 출제 범위에서 다루는 파이썬 기반 웹 크롤링 프레임워크가 아니다. 이름에 crawl이 들어가 헷갈리게 만든 오답 보기다."},{"verdict":"오답","why":"SBAS(Satellite Based Augmentation System)는 위성을 이용해 GPS 위치 오차를 보정하는 위성 기반 보정 시스템이다."},{"verdict":"오답","why":"Li-Fi(Light Fidelity)는 LED 조명의 빛을 이용해 데이터를 전송하는 무선 통신 기술이다."},{"verdict":"정답","why":"Scrapy는 Python 기반의 웹 크롤링 프레임워크다."}],"keywords":[{"term":"Scrapy","desc":"Python 기반 웹 크롤링 프레임워크"},{"term":"Li-Fi","desc":"가시광선(LED)을 이용한 무선 통신"},{"term":"SBAS","desc":"위성 기반 GPS 오차 보정 시스템"}],"memo":"스크래피(Scrapy)는 스크랩(Scrap)하는 파이썬 도구."}},{"id":"written-2026-1-96","no":96,"unit":"정보시스템 구축 관리","q":"취약점 관리를 위한 응용 프로그램의 보안 설정과 가장 거리가 먼 것은 무엇인가?","choices":["서버 관리실의 출입 통제","운영체제에 대한 접근 제한","실행 프로세스의 권한 설정","운영체제의 정보 수집에 대한 제한"],"ans":1,"exp":{"concept":"응용 프로그램의 보안 설정은 소프트웨어 차원에서 취약점을 줄이는 작업으로, 운영체제 접근 제한, 실행 프로세스 권한 설정, 운영체제 정보 수집 제한, 서비스 관리 등이 있다. 서버실 출입 통제는 사람과 장소를 통제하는 물리적 보안에 해당하므로 응용 프로그램 보안 설정과는 거리가 멀다.","choices":[{"verdict":"정답","why":"서버 관리실 출입 통제는 물리적 보안(시설 보안)이며 응용 프로그램의 보안 설정이 아니다."},{"verdict":"오답","why":"응용 프로그램이 운영체제 자원에 함부로 접근하지 못하도록 접근을 제한하는 것은 응용 프로그램 보안 설정에 해당한다."},{"verdict":"오답","why":"실행 프로세스에 필요한 최소한의 권한만 주도록 권한을 설정하는 것은 응용 프로그램 보안 설정에 해당한다."},{"verdict":"오답","why":"응용 프로그램이 운영체제 정보를 수집해 노출하지 않도록 제한하는 것은 응용 프로그램 보안 설정에 해당한다."}],"keywords":[{"term":"물리적 보안","desc":"출입 통제, CCTV, 잠금장치 등 시설 보호"},{"term":"최소 권한의 원칙","desc":"작업에 필요한 최소한의 권한만 부여"},{"term":"취약점 관리","desc":"보안 설정, 패치, 무결성 검사, 불필요 서비스 제거"}],"memo":"'출입 통제'는 문(물리), '권한, 접근 제한'은 코드(소프트웨어)."}},{"id":"written-2026-1-97","no":97,"unit":"정보시스템 구축 관리","q":"정보보호를 위한 암호화에 관한 설명 중 틀린 것은?","choices":["평문 - 암호화되기 이전의 원본 메시지","키(Key) - 적절한 암호화를 위해 사용되는 값","복호화 - 평문을 암호문으로 변환하는 작업","암호문 - 암호화를 적용한 메시지"],"ans":3,"exp":{"concept":"암호화는 누구나 읽을 수 있는 평문을 키(Key)를 이용해 알아볼 수 없는 암호문으로 바꾸는 것이고, 복호화는 그 반대로 암호문을 평문으로 되돌리는 것이다. 자물쇠로 상자를 잠그는 것이 암호화, 열쇠로 다시 여는 것이 복호화다.","choices":[{"verdict":"오답","why":"평문(Plaintext)은 암호화되기 전의 원본 메시지이므로 옳은 설명이다."},{"verdict":"오답","why":"키(Key)는 암호화와 복호화를 위해 알고리즘에 넣는 값이므로 옳은 설명이다."},{"verdict":"정답","why":"평문을 암호문으로 바꾸는 것은 암호화(Encryption)다. 복호화(Decryption)는 암호문을 평문으로 되돌리는 작업이다."},{"verdict":"오답","why":"암호문(Ciphertext)은 평문에 암호화를 적용한 메시지이므로 옳은 설명이다."}],"keywords":[{"term":"암호화(Encryption)","desc":"평문 → 암호문"},{"term":"복호화(Decryption)","desc":"암호문 → 평문"},{"term":"평문 / 암호문","desc":"Plaintext / Ciphertext"}],"memo":"복호화의 '복'은 회복, 원래(평문)로 돌아간다."}},{"id":"written-2026-1-98","no":98,"unit":"정보시스템 구축 관리","q":"취약점 관리를 위해 일반적으로 수행하는 작업으로 볼 수 없는 것은?","choices":["응용 프로그램의 보안 설정과 패치(Patch) 적용","중단된 프로세스와 닫힌 포트 위주의 확인","무결성 검사","불필요한 서비스와 악성 프로그램의 확인 및 제거"],"ans":2,"exp":{"concept":"취약점 관리는 시스템의 보안 약점을 찾아 없애는 작업으로, 응용 프로그램 보안 설정과 패치 적용, 무결성 검사, 불필요한 서비스와 악성 프로그램 제거, 실행 중인 프로세스와 열린 포트 확인 등이 있다. 공격은 지금 살아 있는 프로세스와 열려 있는 포트로 들어오므로 점검도 그쪽을 본다. 도둑을 막으려면 잠긴 문이 아니라 열린 문을 살펴야 하는 것과 같다.","choices":[{"verdict":"오답","why":"응용 프로그램의 보안 설정과 최신 보안 패치 적용은 대표적인 취약점 관리 작업이다."},{"verdict":"정답","why":"취약점 관리에서는 중단된 프로세스와 닫힌 포트가 아니라 실행 중인 프로세스와 열린 포트를 확인해야 한다."},{"verdict":"오답","why":"파일이나 시스템이 무단으로 변경되지 않았는지 확인하는 무결성 검사는 취약점 관리 작업이다."},{"verdict":"오답","why":"불필요한 서비스와 악성 프로그램을 찾아 제거하는 것은 공격 경로를 줄이는 취약점 관리 작업이다."}],"keywords":[{"term":"취약점 관리","desc":"보안 설정, 패치, 무결성 검사, 불필요 서비스 제거, 실행 프로세스/열린 포트 점검"},{"term":"패치(Patch)","desc":"발견된 결함, 취약점을 수정하는 업데이트"},{"term":"무결성 검사","desc":"파일, 시스템이 허가 없이 변경되지 않았는지 확인"}],"memo":"점검은 '살아 있는 프로세스, 열린 포트'를 본다."}},{"id":"written-2026-1-99","no":99,"unit":"정보시스템 구축 관리","q":"침입 탐지 시스템(IDS; Intrusion Detection System)에 관한 설명 중 틀린 것은?","choices":["HIDS(Host-Based Intrusion Detection)는 운영체제에 설정된 사용자 계정에 따라 어떤 사용자가 어떤 접근을 시도하였고 어떤 작업을 하였는지 기록을 남겨 추적한다.","외부 인터넷에 서비스를 제공하는 서버가 위치한 네트워크인 DMZ(Demilitarized Zone)에도 IDS를 설치할 수 있다.","NIDS(Network-Based Intrusion Detection System)의 대표적인 예로는 Snort가 있다.","이상 탐지 기법(Anomaly Detection)은 Signature Base 또는 Knowledge Base라고도 하며, 이미 발견되어 정립된 공격 패턴을 미리 입력해 두었다가 탐지하고 차단한다."],"ans":4,"exp":{"concept":"침입 탐지 시스템(IDS)은 시스템이나 네트워크의 비정상적인 사용, 오용, 침입을 실시간으로 탐지하는 시스템이다. 탐지 방식은 오용 탐지(Misuse Detection, 알려진 공격 패턴인 시그니처와 비교)와 이상 탐지(Anomaly Detection, 평소 정상 행위에서 벗어난 비정상 행위를 통계, 행위 기반으로 탐지)로 나뉜다. 지명수배 사진과 비교하는 것이 오용 탐지, 평소와 다른 수상한 행동을 잡는 것이 이상 탐지다.","choices":[{"verdict":"오답","why":"HIDS는 호스트(서버)에 설치되어 운영체제의 사용자 계정별로 누가 어떤 접근과 작업을 했는지 기록하고 추적하므로 옳은 설명이다."},{"verdict":"오답","why":"외부에 서비스를 제공하는 서버가 위치한 DMZ에도 IDS를 설치할 수 있으므로 옳은 설명이다(패킷이 라우터로 들어오기 전, 라우터 뒤, 방화벽 뒤, 내부망 등에도 설치 가능)."},{"verdict":"오답","why":"Snort는 대표적인 오픈 소스 네트워크 기반 침입 탐지 시스템(NIDS)이므로 옳은 설명이다."},{"verdict":"정답","why":"Signature Base 또는 Knowledge Base라고 하며 이미 알려진 공격 패턴을 입력해 두고 탐지하는 것은 오용 탐지(Misuse Detection)다. 이상 탐지는 평균적인 정상 행위와 비교해 벗어난 행위를 탐지하는 방식(Behavior, Statistical Detection)이다."}],"keywords":[{"term":"오용 탐지(Misuse Detection)","desc":"시그니처(알려진 공격 패턴) 기반, 오탐 적음, 새로운 공격 탐지 어려움"},{"term":"이상 탐지(Anomaly Detection)","desc":"정상 행위 기준에서 벗어난 행위 탐지, 새로운 공격 탐지 가능"},{"term":"HIDS / NIDS","desc":"호스트 기반 / 네트워크 기반 침입 탐지"},{"term":"Snort","desc":"대표적인 오픈 소스 NIDS"}],"memo":"시그니처(지문)로 잡으면 오용 탐지, 평소와 다르면 이상 탐지."}},{"id":"written-2026-1-100","no":100,"unit":"정보시스템 구축 관리","q":"다음이 설명하는 접근 제어 모델은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>군대의 보안 레벨처럼 정보의 기밀성에 따라 상하 관계가 구분된 정보를 보호하기 위하여 사용된다.</li><li>자신의 권한보다 낮은 보안 레벨 권한을 가지고 있으면 높은 보안 레벨의 문서를 읽을 수 없으며, 자신의 권한보다 낮은 수준의 문서만 읽을 수 있다.</li><li>자신의 권한보다 높은 보안 레벨의 문서에는 쓸 수 있지만 보안 레벨이 낮은 문서에 대한 쓰기 권한은 제한된다.</li></ul></div>","choices":["PDCA Model","Clark-Wilson Integrity Model","Chinese Wall Mode","Bell-Lapadula Model"],"ans":4,"exp":{"concept":"벨-라파둘라 모델(Bell-LaPadula Model)은 군대처럼 비밀 등급이 나뉜 정보의 기밀성을 지키기 위한 강제적 접근 제어 모델이다. 핵심 규칙은 'No Read Up(자기보다 높은 등급 문서는 읽기 금지)'과 'No Write Down(자기보다 낮은 등급 문서에 쓰기 금지)'이다. 높은 등급의 비밀이 낮은 곳으로 새어 나가지 않게 하는 것이 목적이다.","choices":[{"verdict":"오답","why":"PDCA는 계획(Plan), 실행(Do), 검토(Check), 조치(Act)를 반복하는 품질 및 관리 개선 사이클로, 접근 제어 모델이 아니다."},{"verdict":"오답","why":"클락-윌슨(Clark-Wilson) 무결성 모델은 잘 짜인 트랜잭션과 직무 분리를 통해 데이터 무결성을 보장하는 상업용 모델로, 기밀성 중심의 등급 모델이 아니다."},{"verdict":"오답","why":"만리장성(Chinese Wall) 모델은 이해 충돌 관계에 있는 회사들의 정보에 동시에 접근하지 못하게 하는 모델이다."},{"verdict":"정답","why":"보안 레벨에 따른 상하 관계로 기밀성을 보호하고, 위로 읽기 금지와 아래로 쓰기 금지 규칙을 가진 모델은 벨-라파둘라 모델이다."}],"keywords":[{"term":"Bell-LaPadula","desc":"기밀성 모델, No Read Up, No Write Down"},{"term":"Biba","desc":"무결성 모델, No Read Down, No Write Up"},{"term":"Clark-Wilson","desc":"상업용 무결성 모델, 직무 분리와 정형 트랜잭션"},{"term":"Chinese Wall(Brewer-Nash)","desc":"이해 충돌 방지 모델"}],"memo":"벨라파둘라는 '위로 읽지 말고 아래로 쓰지 마라'(기밀성), 비바는 그 반대(무결성)."}}]};